(window.GIM_TS=window.GIM_TS||{})["Pesachim.0"]={"from":0,"a":[["\u0003אור לארבעה עשר\u0004 יום לחודש ניסן \u0003בודקין את החמץ\u0004 המצוי בבית \u0003לאור הנר. כל מקום שאין מכניסין בו חמץ\u0004 כרגיל, \u0003אין צריך בדיקה,\u0004 שהרי אין מסתבר שיהא שם חמץ. \u0003ובמה אמרו\u0004 חכמים ראשונים שקבעו הלכה שצריך לבדוק בין \u0003\"שתי שורות\u0004 של חביות יין המונחות \u0003במרתף\"\u0004 — הכוונה היא למרתף שהוא \u0003מקום ש\u0004כרגיל \u0003מכניסין בו חמץ\u0004 כלשהו. בפירוש דברי הלכה קדומים אלו נחלקו כבר תנאים ראשונים, \u0003בית שמאי אומרים:\u0004 הכוונה היא \u0003שתי שורות על פני כל המרתף, ובית הלל אומרים:\u0004 אין צורך בבדיקה מרובה כל כך, ודי ב\u0003שתי שורות החיצונות שהן העליונות.\u0004","תחילה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעותו\u0005]\u0006 של \u0003\"אור\"\u0004 בביטוי \"אור לארבעה עשר\"? על כך ניתנו שתי תשובות. \u0003רב הונא אמר: נגהי\u0004 \u0005[אור,\u0006 נוגה\u0005],\u0006 \u0003ורב יהודה אמר\u0004 שפירוש \"אור\" כאן הוא \u0003לילי\u0004 \u0005[לילה].\u0006 \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתנו]\u0006 מתחילה, כאשר דנו בנושא זה לומר \u0003דמאן\u0004 \u0005[שמי]\u0006 ש\u0003אמר נגהי\u0004 \u0005[אור] —\u0006 התכוון ל\u0003נגהי\u0004 \u0005[אור]\u0006 \u0003ממש,\u0004 אור היום. שלדעתו יש לבדוק בבוקרו של יום הארבעה עשר. \u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר לילי\u0004 \u0005[לילה] —\u0006 כוונתו ל\u0003לילי\u0004 \u0005[לילה]\u0006 \u0003ממש.\u0004 וכדי להכריע בדבר הביאו ראיות וקושיות מן הכתובים ומדברי חכמים לברר משמעותה של המלה 'אור'.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 נאמר \u0003\"הבקר אור והאנשים שלחו\u0004 המה וחמוריהם\u0003\"\u0004 (בראשית מד, ג), \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" יממא\u0004 \u0005[יום]\u0006 \u0003הוא!\u0004 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"האור בקר\"? \"הבקר אור\" כתיב\u0004 \u0005[נאמר]\u0006 ואין להבין \"אור\" כשם עצם אלא כפועל (בזמן הווה), \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003צפרא נהר\u0004 \u0005[הבוקר האיר],\u0006 \u0003וכ\u0004דברי \u0003רב יהודה אמר רב.\u0004 ש\u0003אמר רב יהודה אמר רב: לעולם יכנס אדם\u0004 לעיר זרה \u0003בכי טוב,\u0004 כלומר בתוך הזמן שהחמה עדיין זורחת. שכן נאמר באור הביטוי \"כי טוב\", והטוב שבו הוא הבטחון לאדם בשעות האור. וכן כשרוצה לצאת מן העיר, \u0003יצא בכי טוב,\u0004 כאשר כבר האירה השמש בבוקר.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]:\u0006 נאמר \u0003\"וכאור בקר יזרח שמש\u0004 בקר לא עבות מנגה ממטר דשא מארץ\u0003\"\u0004 (שמואל ב כג, ד) \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אור יממא\u0004 \u0005[יום]\u0006 \u0003הוא!\u0004 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"אור בקר\"? \"וכאור בקר\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003וכאור בקר בעולם הזה\u0004 כעין האור הבא ומאיר בבוקר, כאשר האור בתוקפו, \u0003כעין\u0004 זה תהיה \u0003זריחת\u0004 ה\u0003שמש\u0004 אף בתחילת זריחתה \u0003לצדיקים לעולם הבא\u0004 (תוספות), שאור החמה יהא אז שבעתיים (ראה ישעיה ל, כו).","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]:\u0006 הלא נאמר \u0003\"ויקרא אלהים לאור יום\u0004 ולחשך קרא לילה\u0003\"\u0004 (בראשית א, ה), \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אור יממא\u0004 \u0005[יום]\u0006 \u0003הוא!\u0004 ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]\u0006 \u0003למאיר ובא קראו יום.\u0004 כפי שאמרנו כי 'אור' איננו שם עצם אלא פועל, ולדבר שמוסיף ומביא הארה קרא יום. ומקשים: \u0003אלא מעתה,\u0004 לפי עקרון זה את המשך הכתוב \u0003\"ולחשך קרא לילה\"\u0004 תצטרך לפרשו: \u0003\"למחשיך ובא קרא לילה\"\u0004 עוד לפני חשיכה. ואולם השערה זו אי אפשר לקיימה, \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק לנו\u0006 בידינו\u0005]\u0006 כי \u0003עד צאת הכוכבים יממא\u0004 \u0005[יום]\u0006 \u0003הוא,\u0004 נמצא שהמחשיך ובא עדיין אינו דווקא לילה אלא אפילו יום!","\u0003אלא\u0004 יש לחזור מדרך הפירוש הקודמת, ו\u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך היתה כוונתו\u0005]:\u0006 \u0003קרייה רחמנא לנהורא ופקדיה אמצותא דיממא\u0004 \u0005[קרא ה' לאור\u0006 שיבוא \u0005וציוהו על מצוות היום],\u0006 \u0003וקרייה רחמנא לחשוכא ופקדיה אמצותא דלילה\u0004 \u0005[וקרא ה' לחושך וציוהו על מצוות הלילה]\u0006 ונבין \"קרא\" לא במשמעות קריאת שמות, אלא קריאה לדבר מסויים שיבוא.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]:\u0006 נאמר \u0003\"\u0004הללוהו שמש וירח \u0003הללוהו כל כוכבי אור\"\u0004 (תהילים קמח, ג) \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא,\u0004 שמבינים \"כוכבי אור\" במשמעות כוכבי הלילה. ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003הללוהו כל כוכבים המאירים,\u0004 ו\"אור\" אינו כינוי ללילה אלא תיאור מצב. ומקשים: \u0003אלא מעתה\u0004 לפי פירוש זה, \u0003כוכבים המאירים הוא דבעו שבוחי\u0004 \u0005[שצריכים לשבח].\u0006 \u0003שאינן מאירין לא בעו שבוחי\u0004 \u0005[אינם צריכים לשבח]?!\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 (תהילים קמח, ג): \u0003\"הללוהו כל צבאו\"\u0004 משמע שכל הכוכבים בכלל זה!","\u0003אלא\u0004 לא כך הפירוש ו\u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 באמרו \"כוכבי אור\" — ש\u0003אור כוכבים נמי\u0004 \u0005[גם כן]\u0006 \u0003אור הוא.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 אם אור הכוכבים קרוי אור? ומשיבים: יש בכך חשיבות \u0003ל\u0004ענין \u0003נודר מן האור.\u0004 שאם נדר אדם ואמר: קונם עלי הנאת האור, יש לדעת מהו הקרוי אור, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנודר מן האור אסור\u0004 אף \u0003באורן של כוכבים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]:\u0006 נאמר \u0003\"לאור יקום רוצח יקטל עני ואביון ובלילה יהי כגנב\"\u0004 (איוב כד, יד)"],["\u0003הא מדקאמר\u0004 \u0005[הרי ממה שאמר]\u0006 \u0003\"ובלילה יהי כגנב\" אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\"\u0004 האמור שם בתחילה \u0003יממא\u0004 \u0005[יום]\u0006 \u0003הוא,\u0004 שהרי מעמיד הכתוב ניגודים בין לילה ואור! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 זו כוונתו\u0005]:\u0006 \u0003אי פשיטא לך מילתא כנהורא דאנפשות קאתי\u0004 \u0005[אם ברור לך הדבר כאור שבא\u0006 הגנב אף לרצוח \u0005נפשות]\u0006 הרי \u0003רוצח הוא\u0004 גנב זה, \u0003וניתן להצילו בנפשו.\u0004 כלומר, רשאי המתגונן מפני הגנב להרגו, שהבא במחתרת מותר להורגו. \u0003ואי מספקא לך מילתא כליליא\u0004 \u0005[ואם מסופק לך הדבר כלילה]\u0006 \u0003יהי בעיניך כגנב\u0004 בלבד ולא כרוצח \u0003ולא ניתן להצילו בנפשו.\u0004 ואם כן פסוק זה אינו מדבר ביום ובלילה ממש אלא בדימויים של אור וחושך.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]\u0006 על האומר ש\"אור\" לילה הוא: הלא נאמר \u0003\"יחשכו כוכבי נשפו יקו לאור ואין ואל יראה בעפעפי שחר\"\u0004 (איוב ג, ט) \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003\"יקו לאור ואין\" אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" יממא\u0004 \u0005[יום]\u0006 \u0003הוא!\u0004 ודוחים: אין זו ראיה, אפשר לומר ש\"אור\" משמעו אורה בכלל, אבל לאו דווקא יום, ו\u0003התם מילט הוא דקא לייט ליה איוב למזליה\u0004 \u0005[שם מקלל הוא איוב את מזלו]\u0006 \u0003אמר: יהא רעוא דליצפיה הך גברא לנהורא, ולא לישכחיה\u0004 \u0005[יהי רצון שיצפה אותו אדם לאור, ולא ימצאנו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]\u0006 על שיטה זו מן הפסוק שנאמר: \u0003\"ואמר אך חשך ישופני ולילה אור בעדני\"\u0004 (תהלים קלט, יא) \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" יממא\u0004 \u0005[יום]\u0006 \u0003הוא!\u0004 ודוחים: \u0003התם, הכי קאמר\u0004 \u0005[שם, כך אמר]\u0006 \u0003דוד: אני אמרתי\u0004 לאחר שחטאתי \u0003אך חשך ישופני\u0004 (יכני) \u0003לעולם הבא שהוא דומה ליום, עכשיו\u0004 כשאני יודע שנמחל לי, אפילו \u0003העולם הזה שהוא דומה ללילה — אור בעדני\u0004 הואר עבורי, ואם כן אין ללמוד מכאן ש\"אור\" הוא כינוי ליום.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]\u0006 מן המשנה: \u0003ר' יהודה אומר: בודקין אור לארבעה עשר ובארבעה עשר שחרית ובשעת הביעור.\u0004 ונדייק: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003ר' יהודה בודקין אור ארבעה עשר ובארבעה עשר שחרית, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא\u0004 שברור שאור ארבעה עשר קודם לארבעה עשר שחרית. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ועוד, \u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]:\u0006 להוכיח דבר זה ממקור אחר. שנינו: \u0003מאימתי\u0004 יום \u0003ארבעה עשר\u0004 בניסן \u0003אסור בעשיית מלאכה\u0004 לנוהגים כן? \u0003ר' אליעזר בן יעקב אומר: משעת האור, ר' יהודה אומר: משעת הנץ החמה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר בן יעקב לר' יהודה: וכי היכן מצינו יום שמקצתו אסור בעשיית מלאכה ומקצתו מותר בעשיית מלאכה?\u0004 והרי לשיטתך שמתחילים את איסור המלאכה ביום ולא בלילה, שהרי היום נחשב מצאת הכוכבים של היום הקודם, נמצא שחלקו הראשון מותר וחלקו האחר אסור! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הוא עצמו יוכיח\u0004 יום ארבעה עשר עצמו יוכיח שיש מקום לחלוקה כזו, שהרי \u0003מקצתו מותר באכילת חמץ\u0004 (בשעות הבוקר המוקדמות עד השעה השישית) \u0003ומקצתו אסור באכילת חמץ.\u0004","ולעניננו נדייק \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003ר' יהודה משעת הנץ החמה, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\"\u0004 ש\u0003אמר ר' אליעזר בן יעקב אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא,\u0004 והרי זו הוכחה נוספת ש\"אור\" משמעו לילה. ודוחים: \u0003לא,\u0004 אין זה הכרחי, \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003\"אור\" — עמוד השחר.\u0004 ולא נחלקו בין ערב ויום, אלא רק אם מתחילים את איסור המלאכה מעמוד השחר בתחילת אור היום או מאוחר יותר מהנץ ההמה, כשהיא עצמה נראית.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003דקאמר ליה\u0004 \u0005[\u0006מה \u0005שאמר לו]\u0006 ר' אליעזר בן יעקב \u0003היכן מצינו יום שמקצתו מותר בעשיית מלאכה ומקצתו אסור בעשיית מלאכה נימא איהו לנפשיה\u0004 \u0005[שיאמר הוא לעצמו\u0006 קושיה זו\u0005]\u0006 \u0003הא איכא\u0004 \u0005[הרי ישנו]\u0006 \u0003לילה דקא שרי\u0004 \u0005[ש\u0006אותו \u0005מתיר]\u0006 \u0003ר' אליעזר בן יעקב,\u0004 ובודאי לא יבוא להקשות על ר' יהודה דבר הקשה לו עצמו באותה מידה!","ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003בשלמא לדידי, אשכחנא דקא פלגי רבנן בין יממא לליליא\u0004 \u0005[נניח לשיטתי, מוצא אני שחילקו חכמים בין יום ללילה\u0006 שלפניו\u0005].\u0006 שכן שנינו ל\u0003גבי תענית ציבור\u0004 מן התעניות הקלות: \u0003עד מתי אוכל ושותה לפני התענית — עד שיעלה עמוד השחר,\u0004 אלו \u0003דברי ר' אליעזר בן יעקב. ר' שמעון אומר: עד קרות הגבר\u0004 שהוא עוד קודם עלות השחר. נמצא שכבר חילקו חכמים בדין בין היום ובין הלילה. \u0003אלא לדידך, היכא אשכחנא יממא גופיה דפלגי ביה רבנן\u0004 \u0005[לשיטתך, היכן מצינו יום עצמו שחילקו בו חכמים]\u0006 שהרי שעת הנץ החמה אינה תחילת היום!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הוא עצמו יוכיח, שמקצתו מותר באכילת חמץ ומקצתו אסור באכילת חמץ.\u0004 ומעירים: \u0003שפיר קאמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' יהודה לר' אליעזר,\u0004 ומה יכול ר' אליעזר בן יעקב להשיב על הוכחה חותכת זו? ועונים: \u0003הכי קאמר ליה\u0004 \u0005[כך יאמר לו]\u0006 \u0003ר' אליעזר: אמינא לך אנא\u0004 \u0005[אומר אני לך]\u0006 לענין \u0003מלאכה\u0004 שהיא איסור \u0003דרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 מענין \u0003חמץ דאורייתא\u0004 \u0005[שמן התורה]?!\u0006 כי בדבר שמן התורה אפשר לומר ש\u0003עד הכא\u0004 \u0005[כאן]\u0006 \u0003אסר רחמנא\u0004 \u0005[הקדוש ברוך הוא],\u0006 \u0003ועד הכא שרי רחמנא\u0004 \u0005[כאן התיר הקדוש ברוך הוא],\u0006 וגזירת הכתוב היא שיהא הדבר כך. אבל דבר שהוא מדברי חכמים, צריך שיהא לפי כללים ברורים ואחידים.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' יהודה, מה משיב הוא על כך? ועונים: שר' יהודה אומר כי \u0003שעות דרבנן\u0004 \u0005[מדברי חכמים],\u0006 כי אף שעיקר החלוקה היא מן התורה, מכל מקום ההבחנה בין שעות שמותרת בהן אכילת חמץ ושעות שמותר רק למכור את החמץ ולא לאכלו, זו מדברי חכמים היא. הרי שאף חכמים מחלקים בתוך היום עצמו.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 ר' אליעזר בן יעקב מה עונה הוא על כך? ומשיבים: \u0003הרחקה\u0004 ושמירה \u0003הוא דעבוד רבנן לדאורייתא\u0004 \u0005[שעשו חכמים לדברי תורה]\u0006 והוא אחד מסייגי חכמים, אבל כאשר מתקנים חכמים תקנה משלהם הריהי ליום שלם. ומכל מקום לעניננו לא הוכחנו מכאן הוכחה חותכת ש\"אור\" משמעו ערב.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]\u0006 שנינו: \u0003אין משיאין משואות\u0004 (מדליקים מדורות) על הרים, להודיע שקבעו (קידשו) את ראש החודש, \u0003אלא על החדש שנראה בזמנו,\u0004 ביום השלושים לחודש הקודם, כדי \u0003לקדשו\u0004 באותו יום. \u0003ואימתי משיאין משואות\u0004 אלה — \u0003לאור עבורו,\u0004 בסוף יום שלושים, ערב יום שלושים ואחד, שפעמים הוא ביום הנוסף המתעבר על החודש. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא!\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 עוד\u0005]\u0006 ממה ששנינו: \u0003היה\u0004 כהן \u0003עומד כל הלילה ומקריב על המזבח\u0004 את אברי הקרבנות, \u0003לאורה טעון קידוש ידים ורגלים דברי רבי.\u0004 שכיון שהתחיל יום חדש, חייב הכהן לרחוץ ידיו ורגליו בכיור כפי שעושים לפני תחילת העבודה, ולעניננו משמע שאור יום הוא! ודוחים: אין מכאן ראיה גמורה כי \u0003\"אורה\" שאני\u0004 \u0005[שונה]\u0006 וביטוי זה אכן משמעו יום, אבל \"אור\" יתכן שמשמעו ערב.","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 \u0003מר זוטרא\u0004"],["\u0003המפלת\u0004 את ולדה \u0003אור לשמונים ואחד\u0004 יום מהיום שילדה בו את ולדה הקודם, ונאמר בתורה כי היולדת חייבת להביא קרבן לידה גם על נפל. ולמדו כי היולדת יכולה להיפטר בקרבן אחד על הלידות וההפלות הסמוכות לתאריך לידתה עד יום שמונים, שעדיין הן קשורות עם הלידה (ועיין ויקרא יב, א-ו). וכאן מדובר במפלת בדיוק באור לשמונים ואחד. \u0003בית שמאי פוטרין מקרבן\u0004 נוסף, וקרבן שמביאה על לידתה פוטרה גם מקרבן להפלתה. \u0003ובית הלל מחייבים.\u0004","\u0003אמרו להן בית הלל לבית שמאי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אור שמנים ואחד מיום שמנים ואחד?\u0004 כי \u0003אם שיוה לו ל\u0004גבי דיני \u0003טומאה\u0004 שהאשה שוב אין לה דם טוהר וחייבת בכל דיני טומאה רגילים — \u0003לא ישוה לו לקרבן?\u0004 ולעניננו אפשר להסיק \u0003מדקאמר\u0004 \u0005[ממה שאמרו]\u0006 \u0003בית הלל לבית שמאי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003אור שמונים ואחד מיום שמונים ואחד, שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא!\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","ועוד, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 להוכיח לענין משמעות \"אור\": \u0003יכול יהא\u0004 זבח השלמים הנאכל לשני ימים \u0003נאכל\u0004 גם \u0003אור\u0004 ליום \u0003השלישי,\u0004 ולכאורה, \u0003דין הוא,\u0004 כלומר ניתן הדבר להילמד בדרך ההגיון. כיצד, \u0003זבחים\u0004 כגון חטאת ושאר קרבנות, \u0003נאכלים ליום אחד, ושלמים נאכלים לשני ימים. מה להלן\u0004 בזבחים שקיצר בזמן אכילתם — \u0003לילה אחר היום,\u0004 והזבח נאכל ביום ובלילה שלאחריו, \u0003אף כאן\u0004 בשלמים — \u0003לילה אחר היום,\u0004 שייאכלו השלמים אף בלילה שלאחר שני הימים!","\u0003תלמוד לומר:\u0004 \"וכי תזבחו זבח שלמים לה' לרצונכם תזבחוהו \u0003ביום זבחכם יאכל וממחרת והנותר עד יום\u0004 השלישי באש ישרף\" (ויקרא יט ה— ו), משמע \u0003בעוד יום הוא נאכל, ואינו נאכל לאור שלישי.\u0004","וממשיכים בדיון, אם כן \u0003יכול ישרף מיד\u0004 לאחר כלות היום, ולכאורה אף בזה \u0003דין הוא,\u0004 שהרי \u0003זבחים\u0004 אחרים \u0003נאכלין ליום ולילה אחד, ושלמים נאכלין לשני ימים ולילה אחד, מה להלן\u0004 זבחים — \u0003תיכף לאכילה שריפה,\u0004 כלומר מיד לאחר גמר היתר אכילת הזבח, בבוקרו של היום השני, צריכים לשרוף את הנותר, \u0003אף כאן\u0004 בשלמים נגיד: \u0003תיכף לאכילה שריפה,\u0004 וישרפום בלילה, מיד לאחר תום שני הימים.","\u0003תלמוד לומר \"והנותר מבשר הזבח ביום השלישי באש ישרף\"\u0004 (ויקרא ז, יז), משמע: \u0003ביום אתה שורף, ואי אתה שורפו בלילה.\u0004 ולעניננו \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 \u0003\"יהא נאכל אור לשלישי\" אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא!\u0004 ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ששנינו: \u0003אור של יום הכפורים, מתפלל\u0004 בתפילת שמונה עשרה \u0003שבע\u0004 ברכות \u0003ומתודה. שחרית, מתפלל שבע\u0004 ברכות \u0003ומתודה. במוסף, מתפלל שבע\u0004 ברכות \u0003ומתודה. במנחה, מתפלל שבע\u0004 ברכות \u0003ומתודה. בערבית, מתפלל מעין שמונה עשר,\u0004 כלומר תפילה קצרה שהיא קיצור תפילת ערבית הרגילה, מפני עייפות הצמים. \u0003ר' חנינא בן גמליאל אומר משום אבותיו: מתפלל שמונה עשר שלימות, מפני שצריך לומר הבדלה ב\"חונן הדעת\",\u0004 ובנוסח הקצר אין מקום להבדלה זו. ולעניננו נסיק, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא!\u0004 ואומרים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, \u0003דתני דבי שמואל\u0004 \u0005[ששנה\u0006 חכם \u0005מבית\u0006 מדרשו \u0005של שמואל]\u0006 במפורש: \u0003לילי ארבעה עשר בודקין את החמץ לאור הנר. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא.\u0004 מכל ההוכחות הרבות הללו ברור ש\"אור ליום\" משמעו הערב שלפני יום זה, וכיצד אפשר שיחלקו אמוראים אם \"אור ליום\" הוא ערב או בוקר?","\u0003אלא\u0004 יש לדחות את כל מה שאמרנו ויש להבין כך: \u0003בין רב הונא ובין רב יהודה דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"אור\" אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא, ולא פליגי\u0004 \u0005[נחלקו]\u0006 באמת בגוף ההלכה, אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה כ\u0006לשון \u0005מקומו וחכם זה כ\u0006לשון \u0005מקומו].\u0006 \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003רב הונא קרו \"נגהי\"\u0004 \u0005[קראו\u0006 לערב \u0005\"אור\"],\u0006 \u0003ובאתריה\u0004 \u0005[ובמקומו]\u0006 של \u0003רב יהודה קרו \"לילי\"\u0004 \u0005[קראו \"לילה\"],\u0006 ושניהם התכוונו לאותו דבר.","ושואלים: \u0003ותנא דידן מאי טעמא לא קתני\u0004 \u0005[והתנא שלנו מה הטעם לא שנה]\u0006 במפורש \u0003\"לילי\"\u0004 ארבעה עשר? ומשיבים: \u0003לישנא מעליא\u0004 \u0005[\u0006ב\u0005לשון מעולה,\u0006 נקיה\u0005]\u0006 \u0003הוא דנקט\u0004 \u0005[שהשתמש],\u0006 ולא רצה להזכיר לילה וחושך, ואמר במקום זאת \"אור\" לארבעה עשר. \u0003וכ\u0004דברי \u0003ר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: לעולם אל יוציא אדם דבר מגונה מפיו, שהרי עקם הכתוב שמונה אותיות, ולא הוציא דבר מגונה מפיו. שנאמר \"מן הבהמה הטהורה ומן הבהמה אשר איננה טהרה\"\u0004 (בראשית ז, ח), ולא אמר \"הבהמה הטמאה\", ונמצא שהוסיף לשם נקיות הלשון שמונה אותיות יתרות.","\u0003רב פפא אמר: תשע\u0004 אותיות עיקם הכתוב, \u0003שנאמר: \"כי יהיה בך איש אשר לא יהיה טהור מקרה לילה\"\u0004 (דברים כג, יא), ולא אמר 'טמא'. \u0003רבינא אמר: עשר\u0004 אותיות הן, כי יש להוסיף את \u0003וי\"ו ד\u0004של \u0003\"טהור\",\u0004 שכאן נכתב \"טהור\" מלא בוי\"ו. \u0003רב אחא בר יעקב אמר: שש עשרה\u0004 אותיות עיקם הכתוב, \u0003שנאמר \"כי אמר מקרה הוא בלתי טהור הוא כי לא טהור\"\u0004 (שמואל א כ, כו) במקום לומר \"טמא\".","ועוד, \u0003תניא דבי ר' ישמעאל\u0004 \u0005[שנויה ברייתא\u0006 מבית מדרשו \u0005של ר' ישמעאל]:\u0006 \u0003לעולם יספר אדם בלשון נקיה\u0004 ככל האפשר. \u0003שהרי\u0004 כאשר דבר הכתוב \u0003ב\u0004טומאת \u0003זב קראו \"מרכב\",\u0004 (\"וכל המרכב אשר ירכב עליו הזב\". ויקרא טו, ט) \u0003ו\u0004כשדיבר \u0003ב\u0004טומאת \u0003אשה\u0004 הזבה, אף שמדובר באותו דבר \u0003קראו \"מושב\"\u0004 (\"וכל הנוגע... אשר תשב עליו\". ויקרא טו, כב), כי לשון רכיבה יש בה שמץ גנאי לגבי אשה, כיון שיש בכך פיסוק רגלים שאינו דרך צניעות, ולכן לא נזכרה רכיבה באשה. \u0003ואומר \"ותבחר לשון ערומים\"\u0004 (איוב טו, ה), משמעו שיש צורך לדבר בלשון מחוכמת, כדי לא לומר דברים מגונים. \u0003ואומר: \"\u0004יושר לבי אמרי \u0003ודעת שפתי ברור מללו\"\u0004 (איוב לג, ג).","ושואלים: \u0003מאי \"ואומר\"?\u0004 כלומר, מדוע מוסיפים עוד ראיות מן הפסוקים, והרי לכאורה הענין ברור לנו כבר! ומשיבים: \u0003וכי תימא: הני מילי\u0004 \u0005[ואם תאמר: דברים אלה]\u0006 נאמרו דווקא \u0003בדאורייתא\u0004 \u0005[בדברי תורה],\u0006 \u0003אבל בדרבנן\u0004 \u0005[בדברי חכמים]\u0006 \u0003לא\u0004 נאמרו. לכן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003ואומר \"ותבחר לשון ערומים\"\u0004 משמעו בכל דבר ודבר. \u0003וכי תימא: הני מילי\u0004 \u0005[ואם תאמר: דברים אלה]\u0006 אמורים \u0003בדרבנן\u0004 \u0005[בדברי חכמים]\u0006 \u0003אבל במילי דעלמא\u0004 \u0005[בדברים סתם\u0006 שמדברים אנשים\u0005]\u0006 \u0003— לא.\u0004 על כן \u0003ואומר \"ודעת שפתי ברור מללו\"\u0004 בכל מקרה.","ושואלים: על דברי התנא מבית מדרשו של ר' ישמעאל \u0003ו\u0004כי \u0003באשה לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 במקרא לשון \u0003\"מרכב\"?! והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ותקם רבקה ונערתיה ותרכבנה על הגמלים\"\u0004 (בראשית כד, סא)! ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003משום ביעתותא דגמלים, אורחא\u0004 \u0005[פחד הגמלים, דרך]\u0006 \u0003הוא.\u0004 מפני שהגמלים גבוהים וגם אשה אינה יכולה לשבת עליהם (כשרגליה לצד אחד) אלא לרכב, ולכן אין גנאי בסיפור דבר זה. ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויקח משה את אשתו ואת בניו וירכבם על החמר\"\u0004 (שמות ד, כ) ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 נקט לשון זה"],["\u0003משום בניו\u0004 שאף הם רכבו \u0003אורחא\u0004 \u0005[דרך]\u0006 \u0003הוא,\u0004 ומותרים הם ברכיבה אף שגם אשתו היתה בין הרוכבים.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 באביגיל \u0003\"ו\u0004 היה \u0003היא רכבת על החמור\u0004 ויורדת בסתר ההר\u0003\"\u0004 (שמואל א כה, כ) משמע שאף באשה נוקט הכתוב בלשון \"רכיבה\"! ומתרצים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003משום ביעתותא דליליא\u0004 \u0005[פחד הלילה] —\u0006 \u0003אורחא\u0004 \u0005[דרך]\u0006 \u0003היא\u0004 לרכב. שהרי הדבר היה בלילה, ואז אין אשה יושבת על החמור אלא רוכבת עליו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 אם \u0003משום ביעתותא דליליא\u0004 \u0005[פחד הלילה] —\u0006 \u0003ליכא\u0004 \u0005[אין]\u0006 לחשוש, \u0003ו\u0004אולם \u0003משום ביעתותא דדוד\u0004 \u0005[פחד דוד] —\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 לחשוש. ומפני אימתו רצתה לשבת היטב דרך רכיבה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 אם משום \u0003ביעתותא דדוד\u0004 \u0005[פחד דוד] —\u0006 \u0003נמי ליכא\u0004 \u0005[גם כן אין]\u0006 לחשוש, ואולם \u0003משום ביעתותא דהר\u0004 \u0005[פחד ההר] —\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 מקום לרכב דוקא.","ושואלים: \u0003ובאורייתא מי לא כתיב\u0004 \u0005[ובתורה האם לא נאמר]\u0006 \u0003\"טמא\"?\u0004 והרי לא הכל בתורה בלשון נקיה נכתב, שהרי פעמים רבות כתוב לשון \"טמא\" בתורה! \u0003אלא\u0004 כך יש לומר: \u0003כל היכא דכי הדדי נינהו\u0004 \u0005[כל מקום\u0006 ששני הדברים \u0005שוים זה לזה]\u0006 באורכם — \u0003משתעי\u0004 \u0005[מדבר]\u0006 \u0003בלשון נקיה, כל היכא דנפישין מילי\u0004 \u0005[כל מקום שמרובים הדברים]\u0006 וצריך להאריך הרבה — \u0003משתעי\u0004 \u0005[מדבר]\u0006 \u0003בלשון קצרה. כ\u0004פי ש\u0003אמר רב הונא\u0004 ש\u0003אמר\u0004 בשם \u0003רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר רב הונא אמר רב משום\u0004 \u0005[משמו]\u0006 של \u0003ר' מאיר: לעולם ישנה אדם לתלמידו דרך קצרה.\u0004","ושואלים: \u0003וכל היכא דכי הדדי נינהו משתעי\u0004 \u0005[וכל מקום ששוים זה לזה\u0006 האם \u0005מדבר]\u0006 הכתוב \u0003בלשון כבוד? והא\u0004 \u0005[והרי]\u0006 \u0003\"רוכבת\" ו\"יושבת\" דכי הדדי נינהו\u0004 \u0005[שוים הם זה לזה\u0006 בגודלם\u0005],\u0006 ובכל זאת \u0003קאמר\u0004 \u0005[אמר]\u0006 בפסוק לשון \u0003\"רוכבת\"!\u0004 ומשיבים: \u0003\"רכבת\" כתיב\u0004 חסר וי\"ו, נמצא שקיצר בלשונו, ולכן לא הקפיד להשתמש בלשון כבוד.","לענין זה של שימוש בלשון נקיה והגונה מסופר: \u0003הנהו תרי תלמידי דהוו יתבי קמיה דרב\u0004 \u0005[אותם שני תלמידים שהיו יושבים לפני רב]\u0006 והיו עייפים מן הלימוד בסוגיה מסובכת. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שויתינן האי שמעתא\u0004 \u0005[עשתה אותי הלכה זו\u0006 שעסקנו בה\u0005]\u0006 \u0003כדבר אחר\u0004 (כינוי לחזיר) \u0003מסנקן\u0004 \u0005[עייף],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שויתינן האי שמעתא\u0004 \u0005[עשתה אותי הלכה זו]\u0006 \u0003כגדי מסנקן\u0004 \u0005[עייף].\u0006 \u0003ולא אישתעי\u0004 \u0005[דיבר\u0006 עוד\u0005]\u0006 \u0003רב בהדי דהאיך\u0004 \u0005[עם זה\u0006 שהזכיר לשון חזיר\u0005].\u0006 שאדם שאין לשונו נקיה, ודאי שיש בו פגם מוסרי.","וכן מסופר: \u0003הנהו תרי תלמידי דהוו יתבי קמיה דהלל, וחד מינייהו\u0004 \u0005[אותם שני תלמידים שהיו יושבים לפני הלל, ואחד מהם]\u0006 \u0003רבן יוחנן בן זכאי\u0004 היה. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שלא כך היה המעשה, אלא \u0003קמיה דרבי\u0004 \u0005[לפני רבי]\u0006 היו יושבים, \u0003וחד מינייהו\u0004 \u0005[ואחד מהם]\u0006 \u0003ר' יוחנן\u0004 האמורא היה. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 בשאלתו: \u0003מפני מה בוצרין בטהרה\u0004 ומקפידים שלא יהיו כלי הבציר טמאים, \u0003ואין מוסקים\u0004 את הזיתים \u0003בטהרה? וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ושאל אותה שאלה בסגנון שונה: \u0003מפני מה בוצרין בטהרה ומוסקין בטומאה? אמר\u0004 רבם: \u0003מובטח אני בזה\u0004 שדיבר בלשון נקיה \u0003ש\u0004עתיד להיות \u0003מורה הוראה בישראל. ו\u0004אכן \u0003לא היה ימים מועטים עד שהורה הוראה בישראל.\u0004","ועוד מסופר: \u0003הנהו תלתא כהני\u0004 \u0005[אותם שלשה כהנים]\u0006 שהיו בבית המקדש, וכל אחד מהם קיבל משהו מלחם הפנים שהיו מחלקים לכהנים, וכיון שרבו הכהנים היה כל אחד מקבל כמות קטנה מאד. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 לחבריו: \u0003הגיעני\u0004 חלק שגודלו \u0003כפול, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: הגיעני כזית, וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הגיעני כזנב הלטאה.\u0004 ו\u0003בדקו אחריו,\u0004 אחרי האחרון שהביא דוגמא משרץ טמא, \u0003ומצאו בו שמץ פסול.\u0004 תחילה הבינו הלומדים כי פסול זה שמצאו היה פסול יוחסין, שהתברר שלא היה כשר לכהונה.","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003אין בודקין מן המזבח ולמעלה!\u0004 שכאשר בודקין ביוחסין ומגיעים לאדם שיודעים ששימש בכהונה על המזבח, שוב אין בודקים ביחוסו, שודאי לא היה פסול שהרי שימש בכהונה. והרי ממעשה זה משמע שאף עבודת המזבח אינה משמשת חזקה!","ודוחים: \u0003לא תימא\u0004 \u0005[תאמר]\u0006 \u0003\"שמץ פסול\"\u0004 בעניני יוחסין, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003\"שחץ פסול\",\u0004 שנמצא שיש בו פסול של גאוה ושאר מידות רעות שהלוקה בהם אינו ראוי לשמש בכהונה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר הסתירה בדרך אחרת: \u0003שאני התם, דאיהו דארע נפשיה\u0004 \u0005[שונה שם, שהוא שקלקל לעצמו].\u0006 שאמנם סתם כהן המשמש בעבודה מניחים אנו שהוא כשר, אבל אותו כהן שדבר בלשון שאינה נקיה קלקל את חזקת כשרותו.","כיון שסופר אודות הבדיקה שבדקו לאותו כהן, מסופר עוד: \u0003ההוא ארמאה דהוה סליק\u0004 \u0005[גוי אחד שהיה עולה\u0006 לארץ ישראל] ואומר שישראל הוא, \u0003ואכיל\u0004 \u0005[ואוכל]\u0006 \u0003פסחים בירושלים\u0004 מקרבנות הפסח. חזר אותו גוי לארצו ו\u0003אמר\u0004 מתוך התפארות כיצד רימה את ישראל: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב \u0003\"\u0004זאת חוקת הפסח \u0003כל בן נכר לא יאכל בו\"\u0004 (שמות יב, מג) וכן נאמר: \u0003\"וכל ערל לא יאכל בו\"\u0004 (שמות יב, מח), \u0003ואנא הא קאכילנא משופרי שופרי\u0004 \u0005[ואני הרי אכלתי מ\u0006החלק \u0005היפה יפה]\u0006 שבקרבן פסח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה בן בתירא\u0004 (שרצה להכשילו): \u0003מי קא ספו לך\u0004 \u0005[האם מאכילים אותך]\u0006 \u0003מאליה?\u0004 כלומר, האם באמת סבור אתה שמאכילים אותך מהחלק הטוב? ואותו גוי לא ידע שאת האליה של קרבן הפסח מקריבים למזבח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הגוי: \u0003לא.\u0004 אמר לו ר' יהודה בן בתירא: אם כן, \u0003כי סלקת להתם אימא להו: ספו לי\u0004 \u0005[כאשר תעלה לשם אמור להם: האכילוני]\u0006 \u0003מאליה.\u0004 לשנה אחרת, \u0003כי סליק\u0004 \u0005[כאשר עלה],\u0006 \u0003אמר להו\u0004 \u0005[להם\u0006 לבני חבורתו\u0005]:\u0006 \u0003מאליה ספו\u0004 \u0005[תנו]\u0006 \u0003לי! אמרו ליה\u0004 \u0005[לו]\u0006 \u0003אליה לגבוה\u0004 (למזבח) \u0003סלקא\u0004 \u0005[עולה].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003אמר לך הכי\u0004 \u0005[כך],\u0006 שתבקש מן האליה? \u0003אמר להו\u0004 \u0005[להם]\u0006 בהתמרמרות: הלא \u0003ר' יהודה בן בתירה\u0004 הוא שאמר. \u0003אמרו: מאי האי דקמן\u0004 \u0005[מהו זה שלפנינו]\u0006 שר' יהודה בן בתירא אמר שיש לאכול את האליה? ודאי יש כאן דבר הראוי לחקירה. \u0003בדקו בתריה\u0004 \u0005[אחריו],\u0006 \u0003ואשכחוהו דארמאה\u0004 \u0005[ומצאו שגוי]\u0006 \u0003הוא וקטלוהו\u0004 \u0005[והרגוהו].\u0006 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003לר' יהודה בן בתירא: שלם\u0004 \u0005[שלום]\u0006 \u0003לך ר' יהודה בן בתירא! דאת\u0004 \u0005[שאתה\u0006 מצוי\u0005]\u0006 \u0003בנציבין\u0004 שבבבל \u0003ומצודתך פרוסה בירושלים,\u0004 שהרי הצלחת ממקומך להביא לתפיסתו של אדם שרימה אותנו.","ועוד בשבח שמירת הלשון מאמירה של גנאי או רעה, מסופר: \u0003רב כהנא חלש\u0004 \u0005[חלה].\u0006 \u0003שדרוה רבנן\u0004 \u0005[שלחוהו חכמים]\u0006 את \u0003ר' יהושע בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003בדוק מאי דיניה\u0004 \u0005[מה דינו,\u0006 מה שלומו\u0005].\u0006 \u0003אתא, אשכחיה דנח נפשיה\u0004 \u0005[בא, מצאו שנחה נפשו,\u0006 נפטר\u0005].\u0006 \u0003קרעיה ללבושיה, ואהדריה לקרעיה לאחוריה, ובכי ואתי\u0004 \u0005[קרע את לבושו, והחזיר את הקרע לאחוריו\u0006 שלא ייראה מיד, \u0005והיה בוכה ובא]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו]\u0006 של רב כהנא? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא קאמינא\u0004 \u0005[אמרתי].\u0006 שהרי כבר נאמר \u0003\"ומוצא דבה הוא כסיל\"\u0004 (משלי י, יח). ומכאן נלמד שאין ראוי לספר מאורעות רעים ואם יש צורך להודיעם — מודיעים בלשון עקיפה.","ועוד בענין לשון נקיה, מסופר: \u0003יוחנן חקוקאה\u0004 \u0005[\u0006מהמקום \u0005חקוק]\u0006 \u0003נפק לקרייתא\u0004 \u0005[יצא לכפרים].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 האם \u0003חיטין נעשו יפות?\u0004 כיון שלא רצה לומר שחיטי השנה לא עלו יפה, \u0003אמר להם\u0004 : \u0003שעורים נעשו יפות\u0004 ויבינו מדעתם מה כוונתו. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בלגלוג: \u0003צא ובשר לסוסים ולחמורים\u0004 בדבר השעורים, שהרי נאמר \u0003\"השערים והתבן לסוסים ולרכש\"\u0004 (מלכים א ה, ח). ותוהים: אם כן, \u0003מאי הוה ליה למימר\u0004 \u0005[מה היה לו לומר]\u0006 אם רצה לדבר בלשון טובה ונקיה? ומשיבים: \u0003הוי ליה למימר\u0004 \u0005[היה לו לומר]\u0006 \u0003אשתקד נעשו חיטין יפות. אי נמי\u0004 \u0005[או גם כן]\u0006 יכול לומר \u0003עדשים\u0004 (שהן מאכל אדם) \u0003נעשו יפות\u0004 השנה."],["מסופר עוד: \u0003רב בר אחוה\u0004 \u0005[בן אחיו]\u0006 של \u0003ר' חייא ובר אחתיה\u0004 \u0005[ו\u0006אף \u0005בן אחותו]\u0006 היה, שנשא אייבו אבי רב שהיה אחי ר' חייא מאב את אחותו החורגת שהיתה אחות ר' חייא מאם. \u0003כי סליק להתם\u0004 \u0005[כאשר עלה\u0006 רב \u0005לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא דודו: האם אביך \u0003אייבו קיים,\u0004 עדיין חי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בשאלה: וכי \u0003אימא\u0004 אחותך \u0003קיימת? אמר ליה\u0004 \u0005[לו]:\u0006 והאם \u0003אימא קיימת? אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003אייבו קיים?\u0004 כיון ששמע ר' חייא כך הבין ששניהם נפטרו אלא שרב לא רצה לומר זאת במפורש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לשמעיה\u0004 \u0005[לשמשו]\u0006 \u0003חלוץ לי מנעלי והוליך כלי אחרי לבית המרחץ.\u0004 ואומרים כי \u0003שמע מינה תלת\u0004 \u0005[למד ממנה,\u0006 ממעשהו של ר' חייא\u0005, שלשה\u0006 דברים בהלכה\u0005];\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]:\u0006 \u0003אבל אסור בנעילת הסנדל,\u0004 ולכן ציוה לשמשו לחלוץ מנעליו. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 \u0003שמועה רחוקה אינה נוהגת אלא יום אחד,\u0004 ששמועה על מותו של קרוב שהגיעה לאחר שלושים יום ממותו שוב אינה מחייבת אבלות שבעה ימים, ודי באבלות יום אחד. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]:\u0006 כי באבלות \u0003מקצת היום ככולו,\u0004 ודיו במקצת אבילות, בשעה קלה זו שחלץ מנעליו, ואחר כך יכול להכנס לבית המרחץ להתרחץ בו (מה שאסור לאבל לעשות כרגיל), שבטלה ממנו חובת האבלות.","אגב הדיון בדקדוקי לשון של בני אדם מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר: דונו דיני.\u0004 שאותו אדם היה רגיל לומר בכל מקרה של ויכוח: הביאו את הדבר לדין ודונו בו. \u0003אמרי\u0004 \u0005[אמרו\u0006 חכמים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מ\u0004שבט \u0003דן קאתי\u0004 \u0005[בא],\u0006 שכן נאמר \u0003\"דן ידין עמו כאחד שבטי ישראל\"\u0004 (בראשית מט, טז) ולכן מתבטא הוא בסגנון זה.","וכן מסופר: \u0003ההוא דהוה קא אזיל ואמר: אכיף ימא אסיסני ביראתא\u0004 \u0005[\u0006אדם \u0005אחד שהיה\u0006 רגיל \u0005ללכת ולומר: על חוף הים\u0006 שיחי \u0005הסנה הם ברושים]\u0006 (גאונים), שכל דבר הסמוך לים יפה הוא יותר מבמקום אחר, ו\u0003בדקו\u0004 אחרי יחוסו \u0003ואשכחוהו\u0004 \u0005[ומצאוהו]\u0006 \u0003דמזבולן קאתי\u0004 \u0005[הוא בא],\u0006 ובזבולון נאמר \u0003\"זבולן לחוף ימים ישכן\"\u0004 (בראשית מט, יג), ומתוך כך חיבתו לדברים הקרובים לים.","ושבים לענין בדיקת חמץ. \u0003והשתא דקיימא לן דלכולי עלמא\u0004 \u0005[ועכשיו שמוחזק בידינו שלדעת הכל]\u0006 \u0003\"אור\u0004 לארבעה עשר \u0003\"\u0004\u0003אורתא\u0004 \u0005[ערב]\u0006 \u0003הוא, מכדי\u0004 \u0005[הרי]\u0006 \u0003בין ל\u0004שיטת \u0003ר' יהודה ובין ל\u0004שיטת \u0003ר' מאיר\u0004 שנחלקו בשעות שקבעו חכמים לביעור החמץ (להלן פסחים יא, ב), הרי \u0003חמץ אינו אסור\u0004 בהנאה מדין תורה \u0003אלא משש שעות\u0004 שביום \u0003ולמעלה\u0004 (ואחריהן), \u0003ו\u0004אם כן \u0003נבדוק בשית\u0004 \u0005[ב\u0006שעה \u0005השישית]\u0006 ביום בתחילתה, ונבער אז את החמץ.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שנוקטים בכלל \u0003זריזין מקדימין למצות,\u0004 בכל זאת דיינו ש\u0003נבדוק מצפרא\u0004 \u0005[מן הבוקר].\u0006 שאת ענין זריזות למצוות למדים ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וביום השמיני ימול בשר ערלתו\"\u0004 (ויקרא יב, ג), \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל היום כולו כשר ל\u0004מצוות \u0003מילה, אלא שזריזין מקדימים למצות\u0004 למול בבוקר, \u0003ש\u0004כן \u0003נאמר\u0004 בעקידה, שכאשר שמע אברהם את ציווי ה' \u0003\"וישכם אברהם בבקר\"\u0004 (בראשית כב, ג), משמע שהזריז לקיים מצוות בוראו, משכים ועושה רצונו.","ומתרצים, \u0003אמר רב נחמן בר יצחק:\u0004 טעמה של הבדיקה בערב — משום שזו \u0003שעה שבני אדם מצויים בבתיהם\u0004 ויש להם פנאי לבדוק. \u0003ו\u0004עוד טעם: \u0003אור הנר יפה לבדיקה\u0004 דווקא בלילה, ולכן מתוך שמצוות הבדיקה דווקא בנר, נכון לבדוק דווקא בלילה.","\u0003אמר אביי: הילכך\u0004 \u0005[לכן]\u0006 לפי מה שהסכמנו, \u0003האי צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003לא לפתח בעידניה באורתא דתליסר דנגהי ארבסר\u0004 \u0005[יפתח בזמנו\u0006 הקבוע לו ללמוד תורה \u0005בערב של שלשה עשר אור לארבעה עשר]\u0006 \u0003דלמא משכא ליה שמעתיה, ואתי לאימנועי\u0004 \u0005[שמא תמשוך אותו\u0006 תעסיק אותו ביותר \u0005ההלכה\u0006 שהוא עוסק בה, \u0005ותביא\u0006 תגרום לו \u0005להמנע]\u0006 \u0003מ\u0004לקיים \u0003מצוה\u0004 זו של בדיקת חמץ\u0005].\u0006","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב נחמן בר יצחק: המשכיר בית לחבירו ב\u0004יום \u0003ארבעה עשר\u0004 בניסן, \u0003על מי\u0004 מהם \u0003לבדוק\u0004 את החמץ? האם \u0003על המשכיר לבדוק\u0004 משום \u0003דחמירא דידיה\u0004 \u0005[שהחמץ שלו]\u0006 \u0003הוא, או דלמא\u0004 \u0005[שמא]\u0006 \u0003על השוכר לבדוק — דאיסורא ברשותיה קאי\u0004 \u0005[שהאיסור ברשותו עומד],\u0006 שהרי הבית יהא ברשותו בפסח, ושם יהא מצוי החמץ? וענו על כך, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה ממה ששנינו: \u0003המשכיר בית לחבירו — על השוכר לעשות לו מזוזה,\u0004 משמע שהדר בפועל בבית הוא החייב במצוות הבית!","ודוחים: \u0003התם, הא\u0004 \u0005[שם, הרי]\u0006 \u0003אמר רב משרשיא: מזוזה חובת הדר היא\u0004 כלומר קביעת המזוזה היא מחובתו של הדר בבית, ואינה מחובתו של בעל הבית, שמצוות קביעת המזווה אינה חלה על בית ריק, ואפילו הבית שייך לו. ואם כן עדיין קיימת השאלה \u0003הכא, מאי\u0004 \u0005[כאן מה\u0006 הדין\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן בר יצחק, תנינא\u0004 \u0005[שנינו]\u0006 פתרון לשאלה זו בברייתא: \u0003המשכיר בית לחבירו, אם עד שלא מסר לו מפתחות\u0004 הבית \u0003חל\u0004 יום \u0003ארבעה עשר — על המשכיר לבדוק, ואם משמסר לו מפתחות חל ארבעה עשר — על השוכר לבדוק.\u0004","ועוד \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב נחמן בר יצחק: המשכיר בית לחבירו בארבעה עשר\u0004 בניסן, האם \u0003חזקתו\u0004 שהוא \u0003בדוק\u0004 כבר \u0003או אין חזקתו\u0004 שהוא \u0003בדוק?\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכך\u0006 למעשה\u0005]?\u0006 \u0003לישייליה\u0004 \u0005[שישאלנו]\u0006 את המשכיר אם בדק! ומשיבים: \u0003דליתיה להאי דלשיוליה\u0004 \u0005[שאיננו לזה\u0006 המשכיר כאן \u0005ש\u0006אפשר \u0005לשאול אותו]\u0006 והבעיה היא \u0003לאטרוחי להאי, מאי\u0004 \u0005[להטריח לזה\u0006 ששכר שיבדוק, \u0005מה\u0006 הדין\u0005]?\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן בר יצחק: תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם]\u0006 כיוצא בזה: \u0003הכל נאמנים על ביעור חמץ, אפילו נשים אפילו עבדים אפילו קטנים,\u0004 אף שכולם אינם כשרים לעדות בכלל, נאמנים הם לומר שביערו את החמץ. והוא מברר: \u0003מאי טעמא מהימני\u0004 \u0005[מה טעם נאמנים הם],\u0006"],["\u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003חזקתו\u0004 של הבית שהוא \u0003בדוק\u0004 כבר, \u0003דקסבר\u0004 \u0005[שסבור הוא]\u0006 תנא זה: \u0003הכל\u0004 ואפילו עמי הארצות \u0003חברים הם\u0004 כלומר נחשבים כאילו היו מוחזקים בכשרות לענין זה והם נאמנים \u0003אצל בדיקת חמץ.\u0004 שכלל בידינו שהחבר כיון שהוא נאמן בדבר, ודאי תיקן את הצריך תיקון, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבר שמת והניח מגורה\u0004 (מחסן) \u0003מליאה פירות, אפילו הן בני יומן\u0004 כלומר, שהביאום ביום מותו — \u0003הרי הן בחזקת מתוקנים,\u0004 שמן הסתם דאג להפריש מהם תרומות כדינם. ואף בבדיקת חמץ נאמר כי הכל בחזקת חברים ונאמנים אצל בדיקת חמץ.","ומקשים: \u0003וממאי\u0004 \u0005[וממה\u0006 ומנין\u0005]\u0006 מגיע אתה להוכחה זו? שמא בכלל יש לומר שבית אין חזקתו בדוק, \u0003דילמא שאני הכא\u0004 \u0005[שמא שונה כאן]\u0006 \u0003משום דקאמרי הני\u0004 \u0005[שאומרים אלה]\u0006 שהם בדקו, ומאחר שאומרים, סומכים על דבריהם. ודוחים: \u0003אטו\u0004 \u0005[האם]\u0006 \u0003אמירה דהני\u0004 \u0005[של אלה]\u0006 \u0003מידי מששא אית ביה\u0004 \u0005[דבר ממש יש בה]?\u0006 הלא פסולים הם לעדות, ואינם נאמנים, ובודאי לא על עדותם אנו סומכים, אלא משום חזקת בדיקה.","ומקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 רוצה אתה לומר — ש\u0003חזקתו בדוק,\u0004 ומטעם זה הכל נאמנים, אם כן \u0003האי\u0004 \u0005[זה]\u0006 הלשון \u0003\"הכל נאמנים\"\u0004 אינה לשון ראויה, אלא, \u0003\"כל הבתים בחזקת בדוקין בארבעה עשר\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שהרי זו הכוונה!","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה שהעיקר הוא \u0003משום אמירה דהני\u0004 \u0005[של אלה]\u0006 ותדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא אמרי הני\u0004 \u0005[אמרו אלה] —\u0006 \u0003לא,\u0004 ואין מניחים שהבית בדוק. אם כן \u0003תפשוט מיניה\u0004 \u0005[תפתור מכאן]\u0006 את הבעיה, שהרי זו הוכחה לצד השני — ש\u0003אין חזקתו בדוק\u0004 מן הסתם, עד שיבוא אדם ויאמר במפורש שנבדק.","אף מסקנה זו דוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 בית בארבעה עשר \u0003חזקתו בדוק, והכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 ש\u0003מוחזק לן\u0004 \u0005[לנו]\u0006 שבעל הבית \u0003לא בדק, וקאמרי הני: בדקיניה\u0004 \u0005[ואמרו אלה\u0006 נשים, עבדים וקטנים: \u0005בדקנוהו],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לא להימנינהו רבנן\u0004 \u0005[יאמינום חכמים]\u0006 כיון שהם פסולים לעדות, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכך: \u0003כיון\u0004 ש\u0003בדיקת חמץ מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003הוא\u0004 בלבד, \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003בביטול בעלמא סגי ליה\u0004 \u0005[בלבד די לו]\u0006 ודיו שמבטל את החמץ לפני זמן איסורו. על כן \u0003הימנוהו רבנן בדרבנן\u0004 \u0005[האמינוהו,\u0006 סמכו עליו\u0005, חכמים ב\u0006דבר \u0005של חכמים].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003המשכיר בית לחבירו\u0004 לפסח \u0003בחזקת\u0004 שהוא \u0003בדוק\u0004 מחמץ, \u0003ומצאו\u0004 השוכר \u0003שאינו בדוק, מהו\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003מי הוי\u0004 \u0005[האם הוא]\u0006 \u0003כמקח טעות\u0004 והאם יכול הקונה לומר: רצוני לבטל אה השכירות, שכן שכרתיו על דעת שהוא בדוק, \u0003או לא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ש\u0003אמר אביי: לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003באתרא\u0004 \u0005[במקום]\u0006 ש\u0003לא יהבי אגרא\u0004 \u0005[נותנים שכר]\u0006 על בדיקת חמץ, \u0003ובדקו\u0004 \u0005[ובודקים]\u0006 הכל בעצמם. שאומרים \u0003דניחא ליה לאיניש לקיומי\u0004 \u0005[שנוח לו לאדם לקיים]\u0006 \u0003מצוה בגופיה\u0004 \u0005[בגופו].\u0006 \u0003אלא אפילו באתרא דיהבי אגרא ובדקו\u0004 \u0005[במקום שנותנים שכר ובודקים]\u0006 את החמץ, על ידי אדם הנשכר לכך, שאז אף הפסיד השוכר כסף על ידי כך — בכל זאת אומרים אנו \u0003דניחא ליה לאיניש לקיומי\u0004 \u0005[שנוח לו לאדם לקיים]\u0006 \u0003מצוה בממוניה\u0004 \u0005[בממונו]\u0006 ואין זה, איפוא, מקח טעות.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]\u0006 (להלן פסחים יא, א) \u0003ר' מאיר אומר: אוכלין\u0004 חמץ ביום ארבעה עשר \u0003כל חמש\u0004 שעות מתחילת היום, \u0003ושורפין\u0004 אותו \u0003בתחלת שש. ר' יהודה אומר: אוכלין כל ארבע\u0004 שעות, \u0003ותולין\u0004 משאירים במקום \u0003כל\u0004 שעה \u0003חמש,\u0004 שבה לא שורפים ולא אוכלים, \u0003ושורפין\u0004 את החמץ \u0003בתחילת שש.\u0004 ושואלים: \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003חמץ משש שעות ולמעלה אסור\u0004 מן התורה, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה?","\u0003אמר אביי: תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים]\u0006 ומתוך השוואתם נלמד דבר זה, \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקרא אחד \u0003\"שבעת ימים שאר לא ימצא בבתיכם\"\u0004 (שמות יב, יט) משמע שבמשך כל שבעת הימים אסור שיהא חמץ מצוי בבית. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכתוב אחר: \u0003\"אך ביום הראשון תשביתו שאר מבתיכם\"\u0004 (שמות יב, טו), משמע שאת החמץ צריכים להשבית ביום הראשון עצמו לאחר כניסתו. \u0003הא כיצד\u0004 ניישב סתירה זו? אלא הכוונה \u0003לרבות\u0004 יום \u0003ארבעה עשר\u0004 עצמו \u0003לביעור.\u0004 שיש להבין כי \"ביום הראשון\" אין משמעו יום חמישה עשר בניסן, תחלת חג הפסח, אלא היום שבו מקריבים את הפסח.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שכוונת הכתוב \u0003לרבות לילי חמשה עשר לביעור,\u0004 שאף בלילה הראשון יש לבער את החמץ. \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 לולא היה מקרא זה כתוב, \u0003\"ימים\" כתיב\u0004 \u0005[נאמר\u0006 במקרא\u0005]\u0006 והיינו יכולים לחשוב כי \u0003ימים — אין\u0004 \u0005[כן]\u0006 חייבים בהם בביעור חמץ ואין צריך לבער את החמץ אלא בתחילת היום החמישה עשר, \u0003לילות — לא.\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 פסוק זה \"ביום הראשון\" ש\u0003אפילו לילות\u0004 חייבים בביעור חמץ! את הקושיה הזו דוחים: \u0003ההוא לא איצטריכא ליה\u0004 \u0005[זה לא נצרך לו]\u0006 ללמוד מדרשת הכתובים, כי הוא נובע ממקור אחר"],["\u0003דהא איתקש\u0004 \u0005[שהרי הושוותה]\u0006 זמן \u0003השבתת שאור\u0004 לזמן \u0003אכילת חמץ,\u0004 שמשעה שנאסרה אכילת חמץ חלה החובה להשבית שאור, \u0003ו\u0004זמן \u0003אכילת חמץ\u0004 לזמן \u0003אכילת מצה,\u0004 שמשעת חובת אכילת מצה נאסרה אכילת חמץ.","ומפרטים; \u0003השבתת שאור\u0004 הושוותה \u0003לאכילת חמץ,\u0004 שכן שתיהן נאמרו בפסוק אחד, דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שבעת ימים שאר לא ימצא בבתיכם כי כל אכל מחמצת ונכרתה\u0004 הנפש ההיא מעדת ישראל\u0003\"\u0004 (שמות יב, יט).","\u0003ואכילת חמץ\u0004 הושוותה \u0003לאכילת מצה,\u0004 שכן שתיהן נאמרו בפסוק אחד, דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל מחמצת לא תאכלו בכל מושבתיכם תאכלו מצות\"\u0004 (שמות יב, כ), \u0003וכתיב ביה\u0004 \u0005[ונאמר בה]\u0006 \u0003במצה: \"\u0004בראשון בארבעה עשר יום לחודש \u0003בערב תאכלו מצת\"\u0004 (שמות יב, יח). ואם כן יודעים אנו דבר זה ממקור אחר, ואין צורך בלימוד הנוסף.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הדבר \u0003לרבות ליל ארבעה עשר לביעור.\u0004 שיש לבער את החמץ מן הבית עוד בליל ארבעה עשר! ודוחים: דבר זה אי אפשר לאומרו שהרי \u0003'ביום' כתיב\u0004 \u0005[נאמר].\u0006","ושואלים: אם כן \u0003ואימא מצפרא\u0004 \u0005[ואמור\u0006 שמיד \u0005מן הבוקר]\u0006 של ארבעה עשר יחוייב לבער! ומשיבים: אין לומר כן שהרי נאמר \"אך ביום הראשון\", \u0003\"אך\" חלק.\u0004 כי מלת \"אך\" לשון מיעוט וצמצום הוא, ומשמעה: לא כל היום אלא חלק מן היום, ולכן מחלקים: חצי היום אינו חייב בביעור, וחציו השני חייב בביעור.","\u0003דבי ר' ישמעאל תנא\u0004 \u0005[חכם מבית\u0006 מדרשו של \u0005ר' ישמעאל שנה]:\u0006 \u0003מצינו\u0004 יום \u0003ארבעה עשר\u0004 עצמו \u0003שנקרא \"ראשון\", ש\u0004הרי \u0003נאמר \"בראשון בארבעה עשר יום לחדש\"\u0004 (שמות יב, יח). \u0003רב נחמן בר יצחק אמר:\u0004 הפסוק עצמו מתפרש לענין ביעור בארבעה עשר, כי \u0003\"ראשון\" — דמעיקרא\u0004 \u0005[\u0006זה \u0005שהיה בתחילה]\u0006 קודם לאחרים \u0003משמע.\u0004 ואף כאן ה\"ראשון\" הוא היום שבתחילה, בערב החג, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"הראשון אדם תולד\u0004 ולפני גבעות חוללת \u0003\"\u0004 (איוב טו, ז), הרי ש\"הראשון\" הוא זה הקודם לאחרים, כפי ההקבלה שבפסוק.","ותוהים: \u0003אלא מעתה\u0004 אם כך נפרש \"הראשון\", אם כן מה שנאמר בסוכות \u0003\"ולקחתם לכם ביום הראשון\u0004 פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל\u0003\"\u0004 (ויקרא כג, מ) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003ראשון דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003משמע,\u0004 והאם חובת נטילת הלולב ביום ארבעה עשר לתשרי!?","ודוחים: \u0003שאני התם, דכתיב\u0004 \u0005[שונה שם, ש\u0006כן \u0005נאמר]\u0006 מיד לאחר מכן \u0003\"ושמחתם לפני ה' אלהיכם שבעת ימים\"\u0004 (ויקרא כג, מ), \u0003מה שביעי\u0004 בשבעת ימים אלה — \u0003שביעי לחג\u0004 עצמו, \u0003אף \"ראשון\" — ראשון לחג\u0004 עצמו, ואין כוונתו לערב החג. ואולם לעניננו כשלא פורש הדבר, הרי \"ראשון\" משמעו היום הקודם.","ומקשים: \u0003הכי נמי כתיב\u0004 \u0005[כך גם כן נאמר]\u0006 בפסח: \u0003\"אך ביום הראשון תשביתו\u0004 שאור מבתיכם \u0003שבעת ימים מצות תאכלו\"\u0004 (שמות יב, טו), וכשם ששביעי שם — שביעי לחג הוא, אף ראשון — ראשון לחג! ומתרצים: \u0003אם כן, נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"ראשון\", \"הראשון\"\u0004 ההדגשה בה\"א הידיעה \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לכדאמרן\u0004 \u0005[לכמו שאמרנו]\u0006 ש\"הראשון\" משמעו — הקודם ליום ראשון.","ומקשים: \u0003אי הכי, התם נמי\u0004 \u0005[אם כך שם\u0006 בסוכות \u0005גם כן]\u0006 \u0003\"הראשון\" למה לי? ותו, התם\u0004 \u0005[ועוד, שם]\u0006 דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום הראשון שבתון וביום השמיני שבתון\"\u0004 (ויקרא כג, לט) \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003\"ראשון\" — דמעיקרא\u0004 \u0005[שמתחילה]\u0006 הקודם לחג, \u0003משמע?\u0004 ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וביום השמיני שבתון\",\u0004 ללמד: \u0003מה \"שמיני\" — שמיני\u0004 ליום ה\u0003חג\u0004 הראשון, \u0003אף \"ראשון\" — ראשון\u0004 של \u0003חג.\u0004","ומה ששאלת לשון \u0003\"הראשון\" למה לי?\u0004 בא הדבר \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003חולו של מועד,\u0004 לומר שאין בו איסור מלאכה וקדושת יום טוב. ותוהים: הלא \u0003חולו של מועד מ\"ראשון\" ו\"שמיני\" נפקא\u0004 \u0005[יוצא],\u0006 שהרי נאמר בכתוב שראשון ושמיני בלבד הם ימי החג, וממילא מובן שהימים שבאמצע אינם כן!","ומתרצים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005].\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל\u0004 ש\u0003כתב רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"וביום השמיני\",\u0004 היינו מבינים לפי הכלל המקובל \u0003וי\"ו מוסיף על ענין ראשון.\u0004 כי כאשר מתחיל פסוק או ענין בוי\"ו משמעו שאין הוא מופרד מן הקודם אלא בא להוסיף עליו. והיינו סבורים ש\u0003אפילו בחולו של מועד\u0004 יש לנהוג קדושת החג כביום השמיני, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק שאין לפרש כך.","ותוהים: אם כן, \u0003ולא לכתוב רחמנא\u0004 \u0005[יכתוב הכתוב]\u0006 \u0003לא וי\"ו\u0004 של \"וביום השמיני\" \u0003ולא ה\"א\u0004 של \"הראשון\", שכפי ההסבר הקודם באו להוציא זו מזו, ולכן לא יצטרכו לתוספות אלה?! \u0003ותו, התם\u0004 \u0005[ועוד, שם]\u0006 דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום הראשון מקרא קדש יהיה לכם\u0004 כל מלאכת עבודה לא תעשו\u0003\"\u0004 (ויקרא כג, ז) סבור אתה כי \u0003\"ראשון\" דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003משמע,\u0004 בערב החג?!","\u0003אלא\u0004 אין מקום לפירושים הקודמים של \"הראשון\" בנושאים אלה, ו\u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה \"ראשון\"\u0004 שנאמרו כאן \u0003מיבעי ליה לכדתני דבי\u0004 \u0005[נצרכו להם לכמו שדרש החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל. דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בשכר שלשה \"ראשון\"\u0004 שנאמרו בעניני החגים שישראל שומרים אותם, \u0003זכו\u0004 ישראל \u0003לשלשה\u0004 דברים שנקראו \u0003\"ראשון\",\u0004 והם: \u0003להכרית זרעו של עשו, לבנין בית המקדש, ולשמו של משיח.\u0004","\u0003להכרית זרעו של עשו, דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"ויצא הראשון אדמוני כלו כאדרת שער\u0004 ויקראו שמו עשו\u0003\"\u0004 (בראשית כה, כה). \u0003ולבנין בית המקדש, דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"כסא כבוד מרום מראשון מקום מקדשנו\"\u0004 (ירמיהו יז, יב). \u0003ו\u0004כן זכו \u0003לשמו של משיח, דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"ראשון לציון הנה הנם\u0004 ולירושלים מבשר אתן\u0003\"\u0004 (ישעיה מא, כז). אבל \"הראשון\" שנאמר בפסח משמעו — זה שלפני ההתחלה, ערב פסח.","\u0003רבא אמר:\u0004 הלכה זו נלמדת \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר \u0003\"לא תשחט על חמץ דם זבחי\u0004 ולא ילין לבוקר זבח חג הפסח\u0003\"\u0004 (שמות לד, כה), כלומר \u0003לא תשחט הפסח ועדיין חמץ קיים.\u0004 ולכן יש לבער את החמץ עוד באותו חלק של יום הארבעה עשר, לפני זמן שחיטת הפסח.","ומקשים: \u0003ואימא: כל חד וחד כי שחיט\u0004 \u0005[ואמור: כל אחד ואחד כאשר הוא שוחט]\u0006 ידאג שלא יהא חמץ מצוי בידו, ואין זמן קבוע לדבר! ומשיבים: \u0003זמן שחיטה\u0004 של הפסח \u0003אמר רחמנא\u0004 \u0005[הכתוב].\u0006 והוא משש שעות ולמעלה כאשר מתחיל זמן זה.","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שבה כמה מן השיטות שהבאנו. \u0003\"אך ביום הראשון תשביתו שאר מבתיכם\"\u0004 (שמות יב, טו) משמעו: \u0003מערב יום טוב, או\u0004 שמא \u0003אינו אלא ביום טוב עצמו? תלמוד לומר: \"לא תשחט על חמץ דם זבחי\"\u0004 (שמות לד, כה), כלומר \u0003לא תשחט את הפסח, ועדיין חמץ קיים,\u0004 אלה \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 להוכחה זו אלא, \u0003הרי הוא אומר: \"אך ביום הראשון תשביתו שאר מבתיכם\", וכתיב\u0004 \u0005[ונאמר]\u0006 \"וביום הראשון מקרא קודש, וביום השביעי מקרא קדש יהיה לכם \u0003כל מלאכה לא יעשה\u0004 בהם\" (שמות ט״ז:כ״ו), \u0003ומצינו\u0004 (להבערה) \u0003להבערה שהיא אב מלאכה,\u0004 ולכן ברור שביום טוב עצמו אי אפשר לשרוף את החמץ משום איסור הבערה שאינה מצורכי היום טוב עצמו, הרי שאין אפשרות לעשות זאת אלא לפני החג.","\u0003ר' יוסי אומר: אינו צריך\u0004 להוכחה בדרך זו, \u0003הרי הוא אומר \"אך ביום הראשון תשביתו שאר מבתיכם\"\u0004 משמעו: \u0003מערב יום טוב, או\u0004 שמא \u0003אינו אלא ביום טוב\u0004 עצמו — \u0003תלמוד לומר \"אך\" — חלק,\u0004 כלומר מקצת היום בביעור, ומקצתו אינו בביעור. \u0003ואי\u0004 \u0005[ואם]\u0006 נאמר ש\u0003ביום טוב\u0004 ראשון \u0003עצמו, מי שרי\u0004 \u0005[האם מותר\u0006 בחמץ\u0005]?\u0006 \u0003הא איתקש\u0004 \u0005[הרי הושוותה]\u0006 בפסוק \u0003השבתת שאר לאכילת חמץ,\u0004 שבזמן חובת השבתת שאור חלה גם חובת ביעור חמץ, \u0003ואכילת חמץ לאכילת מצה! אמר רבא\u0004"],["\u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 \u0003מ\u0004דברי \u0003ר' עקיבא תלת\u0004 \u0005[שלושה\u0006 דברים\u0005]\u0006 בהלכה. \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי לדעתו \u0003אין ביעור חמץ אלא שריפה,\u0004 שהרי טעמו משום איסור הבערה ביום טוב. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 \u0003הבערה\u0004 שנתפרש איסורה במקרא \u0003לחלק יצאת\u0004 (באה) כדי להפריד בין אבות המלאכה השונים, שהעושה כמה מיני אבות מלאכה חייב על כל אב מלאכה לעצמו. ולא כשיטה האחרת שלפיה איסור הבערה הוא איסור לעצמו, הקל מאבות המלאכה האחרים. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003לא אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003הואיל והותרה הבערה לצורך\u0004 שהרי מותר להבעיר אש לבישול ביום טוב, \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך\u0004 אכילה, כגון לשריפת החמץ.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר: \u0003\"שבעת ימים שאר לא ימצא בבתיכם\"\u0004 (שמות יב, יט) ושואלים: \u0003מה תלמוד לומר\u0004 מה מלמדנו כתוב זה? \u0003והלא כבר נאמר \"לא יראה לך שאר ולא יראה לך חמץ בכל גבלך\"\u0004 (שמות יג, ז)!","ומסבירים: \u0003לפי שנאמר \"לא יראה לך שאר\",\u0004 היינו מבינים: שאור \u0003שלך אי\u0004 (אין) \u0003אתה רואה, אבל אתה רואה של אחרים\u0004 (של גויים) \u0003ושל גבוה\u0004 (השייך להקדש). \u0003יכול יטמין\u0004 את החמץ שלו בביתו או \u0003יקבל פקדונות\u0004 של חמץ \u0003מן הגוי — תלמוד לומר \"לא ימצא\"\u0004 משמע שאסור שיהא מצוי בביתו חמץ מכל סוג.","ו\u0003אין לי אלא בגוי שלא כיבשתו, ואין שרוי עמך בחצר. גוי שכיבשתו, ושרוי עמך בחצר מנין\u0004 שגם הוא בכלל? \u0003תלמוד לומר \"לא ימצא בבתיכם\"\u0004 לגמרי, ואף הוא בכלל.","ושואלים: אם נסמוך על הכתוב \"לא ימצא בבתיכם\" נבין ש\u0003אין לי אלא שבבתיכם\u0004 ממש, מה שנמצא \u0003בבורות בשיחין ובמערות\u0004 (מיני בורות) \u0003מנין\u0004 שאף הוא בכלל? \u0003תלמוד לומר \"בכל גבלך\"\u0004 — בכל השייך לך.","\u0003ועדיין אני אומר:\u0004 על חמץ ש\u0003בבתים — עובר משום בל יראה ובל ימצא ובל יטמין ובל יקבל פקדונות מן הגוי.\u0004 אולם \u0003בגבולין\u0004 מחוץ לבית הדירה — \u0003שלך אי אתה רואה, אבל אתה רואה של אחרים\u0004 (של גויים) \u0003ושל גבוה\u0004 (של הקדש). \u0003מנין ליתן את האמור של זה בזה ושל זה בזה\u0004 שהאיסור שווה בשניהם?","\u0003תלמוד לומר: \"שאר\" \"שאר\" לגזירה שוה. נאמר \"שאר\" בבתים — \"שאר לא ימצא בבתיכם\", ונאמר \"שאר\" בגבולין — \"לא יראה לך שאר\",\u0004 ולמדים מכאן להשוות ההלכות: \u0003מה \"שאור\" האמור בבתים — עובר משום בל יראה ובל ימצא ובל יטמין ובל יקבל פקדונות מן הגוים, אף\u0004 לגבי \u0003\"שאור\" האמור בגבולין עובר משום בל יראה ובל ימצא ובל יקבל פקדונות מן הגוים,\u0004","\u0003ומה \"שאור\" האמור בגבולין שלך אי אתה רואה אבל אתה רואה של אחרים ושל גבוה, אף \"שאור\" האמור בבתים — שלך אי אתה רואה אבל אתה רואה של אחרים ושל גבוה.\u0004","לאחר הבאת ברייתא זו דנים בכמה דברים תמוהים ובלתי מובנים שבה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין לי אלא בגוי שלא כיבשתו ואין שרוי עמך בחצר, גוי שכיבשתו ושרוי עמך בחצר מנין? תלמוד לומר \"לא ימצא\".\u0004 ותוהים: מה טיבו של לימוד זה? הרי פשוט יותר הדין לגבי גוי שכיבשתו ושרוי עמך, יותר מגוי שלא כיבשתו ואינו שרוי עמך.","ואם כן, \u0003כלפי לייא\u0004 \u0005[הצד ההפוך]\u0006 הולך דיון זה, ההיפך הוא המסתבר! \u0003אמר אביי: איפוך\u0004 \u0005[הפוך]\u0006 ואמור: אין לי לאסור אלא בגוי שכיבשתו ושרוי עמך בחצר, בגוי שלא כיבשתו ואין שרוי עמך בחצר וכו'.","\u0003רבא אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך]\u0006 את הדברים, אלא יש לשנות את ההבנה בהם, כי לימוד זה אינו המשך של המשפט הקודם, אלא \u0003וארישא קאי\u0004 \u0005[ולראש\u0006 הברייתא \u0005הוא מוסב],\u0006 ולענין היתר. וכך יש לקרוא את המשפט השלם: חמץ \u0003שלך אי אתה רואה, אבל אתה רואה\u0004 חמץ \u0003של אחרים ושל גבוה,\u0004 שחמץ של גוי אין חייבים בביעורו. \u0003אין לי אלא בגוי שלא כיבשתו ואין שרוי עמך בחצר\u0004 שאין לך קשר עמו ועם חמצו, אבל \u0003גוי שכיבשתו ושרוי עמך בחצר מנין\u0004 שאף חמץ שלו אינך חייב בביעורו? \u0003תלמוד לומר \"לא ימצא\".\u0004","ותוהים: אם כן, \u0003והאי תנא מיהדר אהיתירא\u0004 \u0005[ותנא זה מחזר\u0006 למצוא \u0005היתר]\u0006 לחמץ זה של הגוי באשר הוא, \u0003ו\u0004בסוף הדבר \u0003נסיב לה קרא לאיסורא\u0004 \u0005[והביא את הפסוק\u0006 שעניינו \u0005לאסור]\u0006 \"לא ימצא\"?! ומשיבים שלא הביא התנא הוכחה מלשון \"לא ימצא\" אלא מן הביטוי השלם \"לא ימצא לך\", \u0003משום שנאמר \"לך\" \"לך\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 שבא להדגיש: רק חמץ השייך לך, לישראל, הוא האסור.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול יטמין ויקבל פקדונות\u0004 של חמץ \u0003מן הגוים תלמוד לומר \"לא ימצא\".\u0004 ותוהים: \u0003הא אמרת רישא\u0004 \u0005[הרי אמרת בתחילה]\u0006 חמץ \u0003שלך — אי אתה רואה, אבל אתה רואה של אחרים ושל גבוה,\u0004 משמע מכך של גוים מותר שיהא מצוי בביתו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה\u0006 שאסור\u0005] —\u0006 מדובר \u0003דקביל עליה\u0004 \u0005[שקבל עליו]\u0006 \u0003אחריות\u0004 שאם יאבד ישלם מחירו, ונמצא החמץ כאילו היה שלו. \u0003הא\u0004 \u0005[זה\u0006 שמותר\u0005] —\u0006 מדובר ש\u0003לא קביל עליה\u0004 \u0005[קבל עליו]\u0006 \u0003אחריות,\u0004 ונשאר החמץ ממון הגוי לכל דבר.","\u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לבני\u0004 העיר \u0003מחוזא: בעירו חמירא דבני חילא מבתייכו\u0004 \u0005[בערו את החמץ של אנשי הצבא\u0006 הגוים \u0005מבתיכם]\u0006 שהיו אנשי הצבא מביאים עימם קמח, ובני העיר היו חייבים לאפות ממנו לחם עבורם. וטעמו של דבר, \u0003כיון\u0004 ש\u0003אילו מיגנב\u0004 \u0005[יגנב]\u0006 הקמח \u0003ואילו מיתביד\u0004 \u0005[יאבד] —\u0006 \u0003ברשותייכו קאי, ובעיתו לשלומי\u0004 \u0005[ברשותכם הוא עומד, וצריכים אתם לשלם\u0006 עבורו\u0005],\u0006 אם כן, \u0003כדילכון דמי\u0004 \u0005[כשלכם\u0006 הוא \u0005נחשב]\u0006 \u0003ואסור.\u0004","ומקשים: \u0003הניחא למאן\u0004 \u0005[\u0006הסבר \u0005זה נוח ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר דבר הגורם לממון — כממון דמי\u0004 \u0005[נחשב],\u0006 כלומר אפילו דבר שכשלעצמו (או בשעה זו) אינו שווה כסף, אבל אבידתו או גניבתו גורמת התחייבות כספית, הריהו נחשב ככסף ממש. ולשיטה זו אף שהחמץ של החיילים אינו שלו, כיון שחייב באחריותו — הריהו כשלו. \u0003אלא למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 שדבר הגורם לממון \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[הוא נחשב],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 ש\u0003אמר \"לא ימצא\",\u0004 להדגיש: לא ימצא מכל מקום, ואפילו כאשר יש רק קשר קלוש עם הישראל המחזיק את החמץ ברשותו, אף שאינו מתחייב דבר באבידתו או בגניבתו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 זאת להיפך: \u0003הניחא למאן\u0004 \u0005[\u0006הסבר \u0005זה נוח ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר דבר הגורם לממון לאו\u0004 \u0005[לא]\u0006 \u0003כממון דמי\u0004 \u0005[הוא נחשב],\u0006"],["\u0003היינו דאיצטריך\u0004 \u0005[זהו,\u0006 משום כך \u0005שהוצרך]\u0006 לומר \u0003\"לא ימצא\",\u0004 ללמדנו שבכל זאת דין החמץ שונה ונחשב כשלו. \u0003אלא למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר כממון דמי\u0004 \u0005[הוא נחשב]\u0006 — \u0003\"לא ימצא\" למה לי,\u0004 הלא ממילא יודעים שהדבר אסור? ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכי איתיה\u0004 \u0005[וכאשר\u0006 החמץ \u0005ישנו] —\u0006 \u0003הדר בעיניה\u0004 \u0005[חוזר בעינו],\u0006 נתברר למפרע ש\u0003לאו ברשותיה קאי\u0004 \u0005[שלא ברשותו הוא עומד],\u0006 ושמא אינו עובר עליו כשהוא עדיין ברשותו, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת נחשב הדבר כשלו.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרבא\u0004 שאלה זו: \u0003בהמת ארנונא\u0004 כלומר, עדר שיגבו ממנו את חלקו לצורך מיסי המלכות, האם \u0003חייבת בבכורה\u0004 בהמה שילדה בעדר זה, משום שעדיין הבהמות שלו. \u0003או\u0004 שמא \u0003אין חייבת בבכורה,\u0004 כיון שיש כאן שותפות של גויים, וכל שיש יד גוי באמצע — פטור מבכורה? ומגבילים את השאלה: \u0003כל היכא דמצי מסלק ליה בזוזי\u0004 \u0005[כל מקום שיכול לסלק אותו\u0006 את הגובה הגוי \u0005בכסף]\u0006 ולא לתת את הבהמות עצמן — \u0003לא קא מיבעיא לן\u0004 \u0005[מסופק לנו]\u0006 שהוא \u0003חייב\u0004 בבכורה. שנמצא שאין גוף הבהמות קנוי לשלטונות אלא חוב של כספים הוא חייב להם, והבהמה כולה ברשותו.","\u0003כי קא מיבעיא לן\u0004 \u0005[כאשר מסופק לנו] —\u0006 הרי זה \u0003היכא דלא מצי מסלק ליה בזוזי, מאי?\u0004 \u0005[במקום שאינו יכול לסלק אותו\u0006 את הגובה הגוי \u0005בכסף, מה\u0006 דינו\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פטורה. והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חייבת!\u0004 אמר להם: \u0003התם\u0004 \u0005[שם]\u0006 מדובר במקרה \u0003דמצי מסלק ליה\u0004 \u0005[שיכול לסלק אותו\u0006 \u0005]\u0006 את הגובה הגוי, על ידי כסף.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003אמר רבא: בהמת ארנונא פטורה מן הבכורה, ואף על גב דמצי מסלק ליה\u0004 \u0005[ואף על פי שיכול לסלק אותו]\u0006 את הגובה הגוי בכסף. ואילו \u0003עיסת ארנונא\u0004 (עיסה שחלקה ניתן לנציג השלטונות) — \u0003חייבת בחלה,\u0004 אף שכרגיל עיסת גוי פטורה מחלה, \u0003ואף על גב דלא מצי מסלק ליה\u0004 \u0005[ואף על פי שאינו יכול לסלק אותו\u0006 \u0005]\u0006 את הגובה הגוי, על ידי תשלום דמיה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 להבדל זה — \u0003בהמה אית\u0004 \u0005[יש]\u0006 \u0003לה קלא\u0004 \u0005[קול],\u0006 שהכל יודעים שלקחו בהמתו של פלוני כארנונא למלכות, ואין חושדים בו שבזדון נמנע מלתת את הבכור. \u0003עיסה לית\u0004 \u0005[אין]\u0006 \u0003לה קלא\u0004 \u0005[קול],\u0006 ואין הכל יודעים שעיסת גוי היא, ונחשד באכילת עיסה בלא הפרשת חלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גוי שנכנס לחצירו של ישראל ובציקו בידו — אין ישראל זקוק לבער\u0004 על ידי שילוח הגוי על חמצו מרשותו. \u0003הפקידו\u0004 הגוי \u0003אצלו\u0004 וקיבל אחריות עליו — \u0003זקוק לבער. יחד לו\u0004 לגוי \u0003בית\u0004 להניח חמצו — \u0003אין זקוק לבער, שנאמר \"לא ימצא\".\u0004","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 כלומר, איך נבין את העובדה שכראיה לפסק שאינו זקוק לבער מביאים את המקרא \"לא ימצא\"?! \u0003אמר רב פפא: ארישא קאי\u0004 \u0005[על ההתחלה\u0006 של הברייתא \u0005הוא עומד\u0006 מתייחס\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003הפקידו אצלו — זקוק לבער, שנאמר \"לא ימצא\".\u0004","\u0003רב אשי אמר: לעולם\u0004 תפרש \u0003אסיפא קאי\u0004 \u0005[\u0006ש\u0005על סופה\u0006 של הברייתא \u0005הוא עומד\u0006 מתייחס\u0005],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003יחד לו בית\u0004 לגוי כדי להניח שם חמצו — \u0003אין זקוק לבער, שנאמר \"לא ימצא בבתיכם\" — והא לאו דידיה הוא, דגוי כי קא מעייל — לביתא דנפשיה קא מעייל\u0004 \u0005[ו\u0006בית \u0005זה לא שלו הוא, שהגוי כאשר הוא מכניס —\u0006 \u0005לביתו שלו הוא מכניס],\u0006 שהרי ייחד לו מקום מסויים השייך לו.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003שכירות\u0004 עצמה \u0003קניא\u0004 \u0005[קונה]\u0006 קנין גמור, לענין זה שאין למשכיר כל אחריות על הנעשה במקום המושכר?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אף במקום שאמרו\u0004 שמותר לישראל \u0003להשכיר\u0004 בתים לגוים (כגון בסוריה) — \u0003לא\u0004 להשכיר \u0003לבית דירה אמרו\u0004 שמותר, \u0003מפני שמכניסין\u0004 הגוים \u0003לתוכו עבודה זרה. ואי סלקא דעתך דשכירות קניא, כי קא מעייל\u0004 \u0005[ואם עולה על דעתך שהשכירות קונה,\u0006 הרי \u0005כאשר מכניס]\u0006 הגוי עבודה זרה \u0005—\u0006 \u0003לביתיה דנפשיה קא מעייל\u0004 \u0005[לביתו שלו הוא מכניס]\u0006 ומה חשש איסור יש בכך לבעל הבית?","ומתרצים: \u0003שאני הכא, דאפקיה רחמנא\u0004 \u0005[שונה כאן\u0006 בחמץ \u0005שהוציאו הכתוב]\u0006 \u0003בלשון \"לא ימצא\"\u0004 כוונתו — \u0003מי שמצוי בידך, יצא זה שאינו מצוי בידך,\u0004 אבל לגבי שאר איסורים אחריות המשכיר חלה במידה מסויימת גם על המקום שמשכיר לאחרים אף שאינו מצוי ממש בידו.","\u0003אמר רב יהודה אמר רב: המוצא חמץ בביתו ביום טוב — כופה עליו את הכלי,\u0004 וממתין עד למוצאי יום טוב, ושורפו. \u0003אמר רבא: אם\u0004 אותו חמץ \u0003של הקדש הוא — אינו צריך\u0004 לכפות עליו. \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 אנשים \u0003מיבדל בדילי מיניה\u0004 \u0005[בדלים ממנו]\u0006 בין כה וכה מחמת חומרת איסור ההקדש שעליו, ולא יבואו לאוכלו.","\u0003ואמר רב יהודה אמר רב: חמצו של גוי\u0004 שנמצא בבית ישראל — \u0003עושה לו\u0004 סביבו ביום ארבעה עשר \u0003מחיצה\u0004 של \u0003עשרה טפחים משום היכר,\u0004 שלא יטעו בו ויאכלוהו. \u0003ואם\u0004 חמץ \u0003של הקדש הוא — אינו צריך. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003מיבדל בדילי אינשי מיניה\u0004 \u0005[בדלים אנשים ממנו],\u0006 ולא יבואו לאוכלו בשגגה.","\u0003ואמר רב יהודה אמר רב: המפרש\u0004 (מרחיק לים בספינה), \u0003והיוצא בשיירא\u0004 למקום רחוק, \u0003קודם שלשים יום\u0004 לפסח — \u0003אין זקוק לבער\u0004 את החמץ, \u0003תוך שלשים יום — זקוק לבער\u0004 את החמץ. \u0003אמר אביי: הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת תוך שלשים יום זקוק לבער — לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כ\u0003שדעתו לחזור\u0004 סמוך לפסח (ר\"נ), \u0003אבל\u0004 אם \u0003אין דעתו לחזור\u0004 לביתו — \u0003אין זקוק לבער.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ואי\u0004 \u0005[ואם]\u0006 \u0003דעתו לחזור\u0004 לפני החג לביתו, \u0003אפילו\u0004 יצא \u0003מראש השנה, נמי\u0004 \u0005[גם כן]\u0006 צריך לבער, שהרי יבוא לביתו ויהא מצוי חמץ בביתו! \u0003אלא אמר רבא,\u0004 כך יש לומר: \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמרת קודם שלשים יום אין זקוק לבער — לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא\u0004 כ\u0003שאין דעתו לחזור, אבל\u0004 אם \u0003דעתו לחזור — אפילו\u0004 יצא \u0003מראש השנה זקוק לבער.\u0004","\u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא לטעמיה\u0004 \u0005[לטעמו]\u0006 שתוך שלושים יום לחג צריך לבער את החמץ גם אם לא יבוא להשתמש בבית זה בפסח. ש\u0003אמר רבא: העושה ביתו אוצר\u0004 (מחסן של תבואות), ותחת התבואות יש חמץ, \u0003קודם שלשים יום\u0004 לפני הפסח — \u0003אין זקוק לבער.\u0004 מכיון שהוא מכוסה, הריהו נחשב בדיעבד כמבוער. \u0003תוך שלשים יום — זקוק לבער,\u0004 שכן מלכתחילה אינו חשוב ביעור.","\u0003וקודם שלשים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאינו זקוק לבער \u0003אלא\u0004 אם \u0003אין דעתו לפנותו\u0004 את החמץ לפני הפסח, \u0003אבל\u0004 אם \u0003דעתו לפנותו — אפילו קודם שלשים יום נמי\u0004 \u0005[גם כן]\u0006 \u0003זקוק לבער,\u0004 שהרי יתכן שלא יספיקו לבער את החמץ בזמן שיזדקק לכך.","ושואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשים יום\u0004 שדובר בהם, \u0003מאי עבידתייהו\u0004 \u0005[מה מעשיהם,\u0006 עניינם\u0005]\u0006 ומדוע דוקא שלושים? ומשיבים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 \u0003שואלין ודורשין בהלכות הפסח קודם הפסח שלשים יום,\u0004 ו\u0003רבן שמעון בן גמליאל אומר: שתי שבתות.\u0004 ושואלים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006 שיש צורך להקדים שלשים יום —"],["\u0003שהרי משה עומד בפסח ראשון\u0004 בארבעה עשר בניסן, \u0003ומזהיר על\u0004 דיני \u0003הפסח שני\u0004 החל בארבעה עשר באייר, \u0003שנאמר\u0004 למשה בדבר ה': \u0003\"ויעשו בני ישראל את הפסח במועדו\"\u0004 (במדבר ט, ב), ונאמר \"וידבר משה אל בני ישראל לעשות הפסח ויעשו את הפסח בראשון בארבעה עשר יום לחודש בין הערבים במדבר סיני\" (במדבר ט, ד— ה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"ויהי אנשים אשר היו טמאים לנפש אדם\u0004 ולא יכלו לעשות הפסח ביום ההוא ויקרבו לפני משה ולפני אהרן ביום ההוא\u0003\"\u0004 (במדבר ט, ו). ובאותו יום אמר להם משה הלכות הפסח השני. משמע, שמקדימים לדרוש בעניני החג חודש ימים.","ושואלים: \u0003ורבן שמעון בן גמליאל\u0004 כיצד דוחה הוא ראיה זו — \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003איידי דאיירי במילי דפסחא, מסיק להו לכל מילי דפסחא\u0004 \u0005[כיון שעוסק בעניני הפסח, גומר את כל עניני הפסח]\u0006 ובכללם גם דיני פסח שני, ואין ללמוד מכאן הלכה כללית.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל? שהרי משה עומד בראש החדש\u0004 ניסן, \u0003ומזהיר על\u0004 עשיית קרבן \u0003הפסח, שנאמר: \"החדש הזה לכם ראש חדשים\u0004 ראשון הוא לכם לחדשי השנה\u0003\"\u0004 (שמות יב, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"דברו אל כל עדת ישראל לאמר בעשר לחדש הזה, ויקחו להם איש שה לבית אבת\u0004 שה לבית\u0003\"\u0004 (שמות יב, ג), ומוסיף ומסביר דיני הקרבת קרבן הפסח שבארבעה עשר יום לחודש.","ושואלים: אמנם מכאן אפשר ללמוד שדורשים לפני הפסח בהלכות החג, אולם \u0003ממאי דבריש ירחא קאי\u0004 \u0005[ממה\u0006 מסיקים \u0005שבראש חודש\u0006 היה \u0005עומד]\u0006 ואומר דברים אלה? \u0003דילמא בארבעה בירחא או בחמשה בירחא קאי\u0004 \u0005[שמא ברביעי בחודש או בחמישי בחודש\u0006 היה \u0005עומד]?\u0006","\u0003אלא אמר רבה בר שימי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבינא: מהכא\u0004 \u0005[מכאן]\u0006 למדים אנו דבר זה, נאמר: \u0003\"וידבר ה' אל משה במדבר סיני בשנה השנית\u0004 בשנה השנית לצאתם מארץ מצרים \u0003בחדש הראשון\"\u0004 (במדבר ט, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויעשו בני ישראל את הפסח במועדו\"\u0004 (במדבר ט, ב), ואם כן הקדים את ההזהרה והאמירה שבועיים לפני החג. ושואלים: \u0003הכא נמי, ממאי דבריש ירחא קאי? דילמא בארבעה בירחא או בחמשה בירחא קאי\u0004 \u0005[כאן גם כן, מנין שבראש חודש\u0006 היה \u0005עומד? שמא ברביעי בחודש או בחמישי בחודש\u0006 היה \u0005עומד].\u0006","\u0003אמר רב נחמן בר יצחק: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה של המלים \u0003\"מדבר\" \"מדבר\". כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"במדבר סיני\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וידבר ה' אל משה במדבר סיני באהל מועד באחד לחדש השני\"\u0004 (במדבר א, א). \u0003מה להלן בראש חדש — אף כאן\u0004 לגבי קרבן פסח \u0003בראש חדש.\u0004","ושואלים: אם כן, \u0003וניכתוב ברישא\u0004 \u0005[שיכתוב בתחילה]\u0006 את מה שנאמר ב\u0003חדש ראשון, והדר ניכתוב\u0004 \u0005[ואחר כך יכתוב]\u0006 מה שנאמר ב\u0003חדש שני,\u0004 שהרי דברי ה' אל משה בענין הפסח קודמים לדברים שנאמרו בתחלת הספר. \u0003אמר רב מנשיא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: זאת אומרת אין מוקדם ומאוחר בתורה,\u0004 ודברים המוקדמים בזמן, פעמים באים מאוחר יותר בכתוב.","על מה שנאמר שאין מוקדם ומאוחר בתורה \u0003אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 כלל זה \u0003אלא\u0004 כשמדובר \u0003בתרי ענייני\u0004 \u0005[בשני ענינים\u0006 נפרדים\u0005],\u0006 \u0003אבל בחד עניינא\u0004 \u0005[בענין אחד]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003מוקדם — מוקדם, ומאי\u0004 \u0005[ומה]\u0006 ש\u0003מאוחר — מאוחר. דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שיש מוקדם ומאוחר בפסוקיה של פרשה אחת, הרי המידה שדורשים חכמים \u0003\"כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט\"\u0004 מחוייבת רק אם סדר הפסוקים והמלים הוא קבוע, שאם לא כן \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003פרט וכלל הוא\u0004 שהוא מדה שונה לגמרי.","\u0003ותו\u0004 \u0005[ועוד],\u0006 אותה מידה שידועה לנו במדרש הכתובים \u0003\"פרט וכלל — נעשה כלל מוסף על הפרט\"\u0004 וכולל בתוכו הכל גם את שאינו דומה לפרט, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003כלל ופרט הוא,\u0004 משום שאין הסדר מחייב. על כן חייבים לומר שבענין אחד ודאי שיש סדר מוקדם ומאוחר למקרא.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה מביא ראיה מדברי המקראות שאנו דורשים, \u0003אפילו בתרי ענייני נמי\u0004 \u0005[בשני ענינים גם כן]\u0006 תוכל לומר נימוק זה! \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר \u0005זה נוח למי שאומר]\u0006 \u0003\"כלל ופרט המרוחקין זה מזה\u0004 שאינם כתובים ממש זה ליד זה — \u0003אין דנין אותו בכלל ופרט\"\u0004 הרי \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[למי שאומר]\u0006 שכלל ופרט מרוחקים \u0003\"דנין\", מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003אפילו למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003\"דנין\u0004 כלל ופרט המרוחקים \u0003\"\u0004, \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 אמורים\u0005] —\u0006 \u0003בחד עניינא\u0004 \u0005[בענין אחד]\u0006 שאמנם אין הפסוקים קרובים זה לזה אבל עדיין מצויים הם באותו ענין. \u0003אבל\u0004 אם היו \u0003בתרי ענייני\u0004 \u0005[בשני ענינים]\u0006 לחוד — \u0003אין דנין\u0004 אותם בכלל ופרט לדעת הכל, לפי שאין מוקדם ומאוחר בתורה.","\u0003אמר רב יהודה אמר רב: הבודק\u0004 את החמץ \u0003צריך שיבטל\u0004 בלבו ובפיו את החמץ. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005],\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום פירורין שלא מצא — הא לא חשיבי\u0004 \u0005[הרי אינם חשובים],\u0006 ובטלים מעצמם.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003כיון דמינטר להו\u0004 \u0005[שנשמרים הם]\u0006 \u0003אגב ביתיה\u0004 \u0005[\u0006המצאם ב\u0005ביתו]\u0006 שחשובה לו שמירתו, הריהם \u0003חשיבי\u0004 \u0005[חשובים]\u0006 ואינם מתבטלים ממילא, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]\u0006 שאין הדבר כן, שאם הגיע הזמן של \u0003סופי תאנים\u0004 שנגמרה עונת לקיטת התאנים, ואלה המצויות על העץ מעטות וגרועות עד שיש מקום לשער שבעל הבית מפקיר אותן, \u0003ו\u0004אולם הוא עדיין \u0003משמר שדהו מפני ענבים\u0004 שזו עונת הבציר שלהם. וכן אם הגיע זמן של \u0003סופי ענבים, ו\u0004בעל השדה עדיין \u0003משמר שדהו מפני מקשאות\u0004 (גידולי קישואים) \u0003ומפני מדלעות\u0004 (גידולי דלעת),","\u0003בזמן שבעל הבית מקפיד עליהן\u0004 על סופי תאנים וענבים — \u0003אסורין\u0004 לקחתם \u0003משום גזל,\u0004 ואם אכלם ברשות — \u0003חייבין\u0004 להפריש עליהם \u0003מעשר,\u0004 שדינם כשאר פירות העץ. ו\u0003בזמן שאין בעל הבית מקפיד עליהן — מותרין\u0004 הם \u0003משום גזל ופטורין משום מעשר,\u0004 שחשובים הם כהפקר ואין מעשרים על ההפקר. ומכאן נלמד שאם אדם אינו מחשיב דבר, גם אם הוא נשמר מאליו אגב דברים אחרים, אין הוא יכול להחשב כשלעצמו, והוא הדין אף לפירורים שבבית.","\u0003אמר רבא:\u0004 בענין ביטול חמץ \u0003גזירה\u0004 היא \u0003שמא ימצא\u0004 לאחר זמן הבדיקה בין הדברים שלא ביער \u0003גלוסקא\u0004 (עוגה) \u0003יפה ודעתיה עילויה\u0004 \u0005[ודעתו עליה],\u0006 ולא יבערנה מייד מפני חשיבותה, ונמצא עובר. ושואלים: ומה בכך? \u0003וכי משכחת ליה, לבטליה\u0004 \u0005[וכאשר ימצא אותה, יבטלנה]!\u0006","ודוחים: \u0003דילמא משכחת ליה לבתר איסורא, ולאו ברשותיה קיימא, ולא מצי מבטיל\u0004 \u0005[שמא ימצא אותה לאחר\u0006 זמן \u0005איסורה, ו\u0006אז \u0005לא ברשותו\u0006 היא \u0005עומדת, ואינו יכול לבטל]\u0006 חמץ בתוך הפסח עצמו. שכן \u0003אמר ר' אלעזר: שני דברים אינן ברשותו של אדם\u0004 מבחינת דיני ממונות, \u0003ועשאן הכתוב\u0004 לגבי אחריותו עליהן \u0003כאילו\u0004 היו \u0003ברשותו. ואלו הן: בור\u0004 שכורה או פותח אדם \u0003ברשות הרבים\u0004 שהוא חייב בנזקיו, אף שאין לו זכות ממונית עליו. \u0003ו\u0004כן \u0003חמץ\u0004 שנמצא בביתו ביום ארבעה עשר בניסן \u0003משש שעות ולמעלה,\u0004 שאינו שלו, כיון שאינו שווה מאומה (שהרי אסור הוא באכילה ובהנאה), ומכל מקום חייב על מציאותו בביתו.","ומקשים: \u0003ו\u0004אם כן, מדוע לא \u0003ניבטליה\u0004 \u0005[יבטלנו]\u0006 החמץ ביום ארבעה עשר \u0003ב\u0004שעה \u0003ארבע\u0004 ביום\u0003, ו\u0004כן \u0003ניבטליה\u0004 \u0005[יבטלנו]\u0006 \u0003ב\u0004שעה \u0003חמש,\u0004 ומדוע יבטל בזמן הבדיקה שהיא בליל ארבעה עשר? ומשיבים: \u0003כיון\u0004 שזמן זה של ארבע שעות \u0003לאו זמן איסורא\u0004 \u0005[לא זמן האיסור]\u0006 \u0003הוא ולאו זמן ביעורא\u0004 \u0005[ולא זמן הביעור]\u0006 \u0003הוא,\u0004 הרי זו שעה סתם שאין בה שום סימן היכר, ויש לחשוש \u0003דילמא פשע ולא מבטל ליה\u0004 \u0005[שמא יתרשל ולא יבטל אותו]\u0006 וישאר החמץ ברשותו."],["ושואלים: \u0003וניבטליה בשית\u0004 \u0005[ושיבטלנו ב\u0006שעה \u0005שישית]\u0006 עם שריפתו! ומתרצים: \u0003כיון דאיסורא דרבנן עילויה\u0004 \u0005[ש\u0006יש \u0005איסור מדברי חכמים עליה],\u0006 שהרי משעברו חמש שעות אסור הוא בהנאה מדברי חכמים — \u0003כדאורייתא דמיא\u0004 \u0005[כמן התורה\u0006 הוא \u0005נחשב],\u0006 \u0003ו\u0004לכן \u0003לאו ברשותיה קיימא, ולא מצי מבטיל\u0004 \u0005[ולא ברשותו הוא עומד, ואינו יכול לבטל].\u0006","וראיה לדבר שהחמירו חכמים עד כדי כך אף בחמץ מדבריהם ש\u0003אמר רב גידל אמר ר' חייא בר יוסף אמר רב: המקדש\u0004 אשה \u0003מ\u0004תחילת \u0003שש שעות ולמעלה\u0004 בדבר שיש בו חשש חמץ, \u0003אפילו בחיטי קורדניתא\u0004 \u0005[בחיטין מן ההרים]\u0006 שהן קשות ביותר, ולכן אין ודאות שהחמיצו משנפלו עליהן מים, ובכל זאת אומרים אנו שכיון שיתכן שהחמיצו הרי הן כשאר חמץ האסור בהנאה, ולכן אין לו כל ערך, והמקדש בו אשה \u0003אין חוששין לקידושין.\u0004 כי אין הקידושין תופסים אלא אם כן קידש בשוה פרוטה. הרי שעמדו חכמים על דעתם ובטלו לגמרי את הקידושין והתירו חשש אשת איש מן התורה, אף כי חמץ זה אסור מדברי סופרים בלבד.","ושואלים: האם כן הוא \u0003ולבתר איסורא לא מצי מבטיל ליה\u0004 \u0005[ולאחר\u0006 זמן \u0005האיסור אינו יכול לבטל אותו]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה יושב בבית המדרש ונזכר שיש חמץ בתוך ביתו\u0004 — הרי זה \u0003מבטלו בלבו, אחד\u0004 ב\u0003שבת ואחד\u0004 ב\u0003יום טוב.\u0004 ומעתה נברר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שבת, משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שיהא הביטול קודם זמן איסור, \u0003כגון שחל ארבעה עשר\u0004 בניסן \u0003להיות בשבת,\u0004 ונזכר לפני שאיסור חמץ חל עליו. \u0003אלא יום טוב — בתר איסורא\u0004 \u0005[אחר\u0006 זמן \u0005האיסור]\u0006 \u0003הוא,\u0004 שהרי כבר נכנס החג, ושנינו שיכול לבטל!","\u0003אמר רב אחא בר יעקב: הכא\u0004 \u0005[כאן]\u0006 \u0003בתלמיד\u0004 ה\u0003יושב לפני רבו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ונזכר שיש עיסה מגולגלת\u0004 (נילושת) \u0003בתוך ביתו, ומתיירא שמא תחמיץ\u0004 קודם שיחזור לביתו ויספיק להזהיר את בני ביתו. לכן \u0003קדים ומבטיל ליה מיקמי\u0004 \u0005[מקדים ומבטל אותה, לפני]\u0006 ש\u0003תחמיץ.\u0004 וכיון שאין עיסה זו חמץ, לא חל עליה כל איסור, ולכן יכול לבטלה.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך יש להבין, \u0003דקתני\u0004 \u0005[שהרי שנינו]:\u0006 \u0003היה יושב בתוך בית המדרש,\u0004 משמע שמדובר בעיסה שעדיין לא החמיצה, ושורש הבעיה בכך שיושב בבית המדרש ואינו יכול לצאת ולמנוע את חימוצה. אבל אם היתה זו כבר לאחר שהחמיצה, אף אם אינו יושב בבית המדרש, שוב אינו יכול לתקנה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003אמר רבה בר רב הונא אמר רב: הפת שעיפשה\u0004 (שהתעפשה) בתוך כלי המכיל בתוכו כמה מיני פת, ולא ברור למראה העין אם חמץ אם מצה היא. \u0003כיון שרבתה\u0004 בכלי זה מנין ה\u0003מצה\u0004 — פת זו \u0003מותרת.\u0004 ומתחילה מבררים את הענין לגופו; \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא דידע\u0004 \u0005[אם תאמר שיודע]\u0006 \u0003בה\u0004 בפת זו ש\u0003חמץ היא\u0004 — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003רבתה מצה\u0004 על החמץ \u0003מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]\u0006 הלוא חמץ ודאי הוא?","\u0003אלא\u0004 מדובר ש\u0003לא ידעינן\u0004 \u0005[יודעים אנו]\u0006 \u0003בה אי\u0004 \u0005[אם]\u0006 \u0003חמץ הוא אי\u0004 \u0005[אם]\u0006 \u0003מצה הוא\u0004 — אם כן, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע דווקא \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003רבתה מצה? אפילו כי\u0004 \u0005[כאשר]\u0006 \u0003לא רבתה מצה נמי\u0004 \u0005[גם כן]\u0006 מן הסתם מצה היא, כי \u0003ניזיל בתר בתרא\u0004 \u0005[נלך אחר האחרון],\u0006 ואפילו היה הדבר ביום הראשון של פסח, כיון שהפת האחרונה שהניחו שם פת מצה היא, נלך אחר האחרון ונאמר שהיתה זו מצה שנתעפשה.","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 כגון זה: \u0003מעות שנמצאו לפני סוחרי בהמה\u0004 בירושלים — \u0003לעולם מעשר\u0004 הן, כי רוב הבהמות שקונים בירושלים, מכספי מעשר שני הן. בין בשעת הרגל ובין בעונות השנה האחרות, שמשאירים אנשים את כספי המעשר ואוכלים בהם בשר, ומן הסתם הבהמות שקונים — מכספי מעשר נקנים. ואולם אם נמצא הכסף \u0003בהר הבית,\u0004 יש לשער כי \u0003חולין\u0004 הוא, ואפילו בשעת הרגל. שהנכנס להר הבית, מן הסתם כבר קנה את כל הנצרך לו לבית המקדש, ואם רוצה לקנות קרבנות, נקנים כרגיל מן החולין ולא מן המעשר.","ואם נמצא הכסף בשאר מקומות \u0003בירושלים,\u0004 אם היה זה \u0003בשעת הרגל\u0004 שבא המון עם והכל מביאים עימם כספי מעשר, הרי כסף זה \u0003מעשר\u0004 הוא, ואילו \u0003בשאר ימות השנה\u0004 — הכסף \u0003חולין.\u0004","\u0003ואמר רב שמעיה בר זירא: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שבכל ימות השנה כספים אלו חולין הם ודאי, אפילו למחרת החג — \u0003הואיל ושוקי ירושלים עשויין להתכבד\u0004 (להתנקות) \u0003בכל יום,\u0004 ואת כל כספי המעשר כבר מצאום מנקי הרחובות, וכסף הנמצא כעת — הוא מן הכסף החדש. \u0003אלמא: אמרינן קמאי קמאי אזלי ליה, והני אחריני נינהו\u0004 \u0005[מכאן\u0006 ש\u0005אומרים אנו\u0006 בכלל ש\u0005ראשונים ראשונים הלכו להם, ואלה אחרונים הם],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בפת שעיפשה — \u0003נימא: קמא קמא אזיל, והאי דהאידנא\u0004 \u0005[נאמר: ראשון ראשון הלך\u0006 ונאכל\u0005, וזה\u0006 שנמצא \u0005של עכשיו]\u0006 \u0003הוא,\u0004 והרי הוא מצה ודאי.","ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 ש\u0003עיפושה מוכיח עילויה\u0004 \u0005[עליה]\u0006 שהיא חמץ, שאין פת מתעפשת אלא אם כן שהתה זמן רב. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003עיפושה מוכיח עילויה\u0004 \u0005[עליה],\u0006 אם כן, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003רבתה מצה מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]?\u0006 הרי עצם עיפושה הוא הוכחה שמן הלחם הישן היא. \u0003אמר רבה: לא תימא\u0004 \u0005[תאמר]\u0006 \u0003שרבתה מצה\u0004 במובן זה שיש בכלי יותר מצה מחמץ, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003שרבו ימי מצה עילויה\u0004 \u0005[עליה],\u0006 כלומר שעברו ימים אחדים של זמן אכילת מצה, ויתכן שהפת שנתעפשה פת מצה היא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמצה היא ולא חמץ! ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא כש\u0003עיפושה\u0004 של הפת \u0003מרובה, מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון\u0004 ש\u0003עיפושה מרובה — איגליא מילתא\u0004 \u0005[התגלה הדבר]\u0006 ש\u0003ודאי חמץ מעליא\u0004 \u0005[ממש]\u0006 \u0003הוא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין ודאות גמורה בדבר:","\u0003כיון שרבו ימי מצה עילויה\u0004 \u0005[עליה]\u0006 \u0003אמרינן: כל יומא ויומא נהמא חמימא\u0004 \u0005[אומרים אנו: כל יום ויום לחם חם]\u0006 \u0003אפה, ושדא עילויה ועפשא טפי\u0004 \u0005[והניח עליה ונתעפשה ביותר].\u0006 וייתכן שעיפוש מרובה זה, לא מחמת ריבוי זמן בא, אלא מחמת רטיבות וחום שהיו שם.","לעצם העיקרון שואלים: \u0003ומי אזלינן בתר בתרא\u0004 \u0005[והאם\u0006 בכלל \u0005הולכים אנו\u0006 בדברים כגון אלה \u0005אחר\u0006 השימוש \u0005האחרון],\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר יהודה אומר: תיבה שנשתמשו בה\u0004 גם \u0003מעות חולין ו\u0004גם \u0003מעות מעשר, אם\u0004 היה \u0003רוב\u0004 שימושה ב\u0003חולין\u0004 — רואים אנו את הכסף שנמצא בה ככסף \u0003חולין, אם רוב\u0004 שימושה ב\u0003מעשר\u0004 — הכסף שנמצא בה \u0003מעשר\u0004 הוא. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? \u0003ליזיל בתר בתרא\u0004 \u0005[נלך אחר\u0006 השימוש \u0005האחרון]!\u0006","\u0003אמר רב נחמן בר יצחק: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שנשתמשו בה\u0004 גם \u0003מעות חולין ו\u0004גם \u0003מעות מעשר, ואין יודע\u0004 וזוכר ל\u0003איזה מהן\u0004 השתמשו בה \u0003בסוף. רב זביד אמר: כגון שנשתמשו בה ציבורין ציבורין.\u0004 כלומר בחלק אחד מן התיבה השתמשו לצורך מעשר, ובחלקה האחר לצורך חולין, ואין כאן אחרון, ויש ספק שמא מטבע זו זזה ממקום למקום. \u0003רב פפא אמר: כגון דאשתכח\u0004 \u0005[שנמצאה]\u0006 המטבע \u0003בגומא\u0004 \u0005[בחור\u0006 שבתיבה\u0005],\u0006 ולכן יש להסתפק אולי אין מטבע זו מאלה שהשתמשו בהן בסוף, אלא מהקודמים ולא הוציאוה עד כה מפני שנסתרה בגומא.","\u0003אמר רב יהודה: הבודק\u0004 את החמץ \u0003צריך שיברך.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך,\u0004 מה נוסחה המדויק של הברכה? \u0003רב פפי אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 שהמברך \u0003אומר: \"\u0004אשר קדשנו במצותיו וצונו \u0003לבער חמץ\". רב פפא אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: \"על ביעור חמץ\".\u0004 ומנסים להסביר את ההבדל בין לשונות אלה: \u0003ב\"לבער\" — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003ודאי להבא משמע\u0004 שמשמעות הדברים שהוא עומד להתחיל במצוה זו של ביעור חמץ, ונוסח זה ודאי ראוי."],["\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003ב\u0004לשון \u0003\"על ביעור\". מר\u0004 \u0005[חכם זה,\u0006 רב פפי\u0005]\u0006 \u0003סבר: מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע.\u0004 שביטוי זה יש מקום לאומרו בסיומה של הבדיקה, ומשמעו — על ביעור חמץ שנעשה כבר. \u0003ומר\u0004 \u0005[וחכם זה\u0006 רב פפא\u0005]\u0006 \u0003סבר: להבא משמע,\u0004 כי ביטוי זה בעיקרו להבא משמעו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מן הנוסח של ברכת מצות מילה \u0003\"ברוך... אשר קדשנו במצותיו וצונו על המילה\",\u0004 הרי משמע שביטוי זה אפשר להשתמש בו גם לפני מעשה!","ודוחים: מכאן אין ראיה, כי \u0003התם, היכי נימא\u0004 \u0005[שם, איך נאמר]:\u0006 \u0003נימא\u0004 \u0005[\u0006אם \u0005יאמר]\u0006 \u0003\"\u0004אשר קדשנו במצוותיו וצונו \u0003למול\"\u0004 — האם \u0003לא סגיא\u0004 \u0005[לא די,\u0006 לא יתכן\u0005]\u0006 שיקרה \u0003דלאו איהו מהיל\u0004 \u0005[שלא הוא המל]?\u0006 שהרי יש שלא אבי הבן, שהוא המצווה על המילה, הוא עצמו המוהל, אלא אחר. ואותו אדם אחר לא חלה עליו במישרין המצוה למול, ולכן נוסח הברכה הוא כללי \"על המילה\". ומקשים: \u0003אבי הבן,\u0004 אם הוא עצמו מל את בנו, \u0003מאי איכא למימר\u0004 \u0005[מה יש לך לומר]?\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 שאם האב עצמו מל, צריך לברך \"וצונו למול\".","עוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מנוסח ברכת השחיטה: \u0003\"ברוך... אשר קדשנו במצותיו וצונו על השחיטה\",\u0004 הרי שלשון זו ניתנת לשימוש גם לפני מעשה! ודוחים: \u0003התם נמי, היכי נימא?\u0004 \u0005[שם גם כן, איך נאמר]?\u0006 \u0003נימא\u0004 \u0005[\u0006אם \u0005נאמר]\u0006 \u0003\"\u0004וצונו \u0003לשחוט\" —\u0004 וכי \u0003לא סגיא דלאו איהו שחט\u0004 \u0005[די בכך שלא הוא שוחט]?\u0006 שהרי אין מצות עשה המחייבת אותו אדם לשחוט את הבהמה, ואין שחיטה אלא הכשר לצורך אכילת הבהמה. ולכך אף בשחיטה נוסח הברכה כללי \"על השחיטה\".","ומקשים: אם כן, \u0003פסח וקדשים מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי באלה יש באמת מצות עשה של שחיטה! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 שבשחיטת פסח וקדשים צריך הוא לברך \"אשר קדשנו במצוותיו וצונו לשחוט\".","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בתוספתא: \u0003העושה לולב לעצמו מברך \"שהחיינו וקימנו והגיענו לזמן הזה\". נטלו לצאת בו\u0004 ידי חובת מצות לולב \u0003אומר: \"אשר קדשנו במצותיו וצונו על נטילת לולב\"\u0004 ואינו מברך \"ליטול\"! ומשיבים: \u0003שאני התם, דבעידנא דאגבהה נפק ביה\u0004 \u0005[שונה שם, שבזמן שהגביה\u0006 אותו, עוד לפני הברכה, כבר \u0005יצא בו\u0006 ידי חובתו\u0005]\u0006 שמן התורה, ולכן יפה אומר בנוסח \"על נטילת לולב\" שמשמעו על נטילה שעשה כבר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היא הכוונה, הרי לשון זו שבברייתא: \"נטלו \u0003לצאת בו\"\u0004 אינה מדוקדקת, ו\u0003\"\u0004נטל לולב \u0003יצא בו\" מיבעי ליה\u0004 \u0005[צריך לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך גם כן\u0006 צריך היה שיאמר\u0005],\u0006 אלא \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שהוא רוצה לשנות\u0006 ב\u0005סוף\u0006 אותה הלכה]: \u0003\"\u0004הבא \u0003לישב בסוכה\", תנא רישא נמי\u0004 \u0005[שנה בתחילה גם כן]\u0006 \u0003\"לצאת בו\".\u0004 שנמשך אחרי לשון זו, אבל אין זה כדקדוקה של ההלכה.","\u0003דקתני סיפא\u0004 \u0005[ששנינו\u0006 ב\u0005סוף\u0006 הלכה זו\u0005]:\u0006 \u0003העושה סוכה לעצמו, אומר \"ברוך אתה ה'... שהחיינו וקימנו והגיענו לזמן הזה\". נכנס לישב בה, אומר: \"ברוך... אשר קדשנו במצותיו וצונו לישב בסוכה\".\u0004 בסופו של דבר לא נמצאה הוכחה גמורה לצד זה או אחר, אבל להלכה מסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 שיש לברך: \u0003\"על ביעור חמץ\"\u0004 לפי שיש בה אף משמעות לשון עתיד.","ומתוך המשא והמתן שעסקנו בו אפשר היה להסיק כי \u0003דכולי עלמא מיהא, מעיקרא בעינן לברוכי, מנלן\u0004 \u0005[לדעת הכל על כל פנים, מתחילה\u0006 לפני המצוה \u0005צריכים אנו לברך, מנין לנו]\u0006 הלכה זו? ומשיבים: ש\u0003אמר רב יהודה אמר שמואל: כל המצות מברך עליהן עובר לעשייתן.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 מהיכן\u0005]\u0006 \u0003משמע דהאי\u0004 \u0005[שזה]\u0006 הלשון \u0003\"עובר\" לישנא דאקדומי\u0004 \u0005[לשון קדימה\u0006 לפני מעשה\u0005]\u0006 \u0003הוא? אמר רב נחמן בר יצחק:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וירץ אחימעץ דרך הככר ויעבר את הכושי\"\u0004 (שמואל ב יח, כג), כלומר: השיגו ובא לפניו. \u0003אביי אמר: מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]:\u0006 \u0003\"והוא עבר לפניהם\"\u0004 (בראשית לג, ג). \u0003ואי בעית אימא, מהכא\u0004 \u0005[ואם תרצה אמור\u0006 יש להוכיח \u0005מכאן]\u0006 \u0003\"ויעבר מלכם לפניהם וה' בראשם\"\u0004 (מיכה ב, יג).","\u0003בי רב אמרי\u0004 \u0005[\u0006חכמים ב\u0005בית\u0006 מדרשו של \u0005רב אמרו]:\u0006 כל המצוות מברך לפניהן, \u0003חוץ מן הטבילה\u0004 לטהרת קרי ותקיעת \u0003שופר.\u0004 ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ב\u0003טבילה\u0004 שאינו מברך לפניה — משום \u0003דאכתי גברא\u0004 \u0005[שעדיין האיש]\u0006 הטובל \u0003לא חזי\u0004 \u0005[ראוי]\u0006 לברכה, שטמא הוא קודם הטבילה. \u0003אלא שופר מאי טעמא\u0004 \u0005[מה הטעם]\u0006 אינו מברך לפני התקיעה? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003משום\u0004 החשש \u0003דילמא מיקלקלא\u0004 \u0005[שמא תתקלקל]\u0006 ה\u0003תקיעה\u0004 ולא יצליח לתקוע כראוי, ותהא זו ברכה לבטלה. \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו שחיטה ומילה נמי\u0004 \u0005[גם כן]\u0006 לא יברך אלא לבסוף, שמא לא יעלה המעשה יפה בידו!","\u0003אלא אמר רב חסדא: חוץ מן הטבילה בלבד איתמר\u0004 \u0005[נאמר],\u0006 מפני הטעם שאמרנו. ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003טבל\u0004 לקריו \u0003ועלה, בעלייתו אומר: \"ברוך... אשר קדשנו במצותיו וצונו על הטבילה\".\u0004 משמע שבטבילה מברך לאחר מעשה הטבילה.","במשנה נאמר \u0003\"בודקין את החמץ לאור הנר\".\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שיש לבדוק לאור הנר דוקא? \u0003אמר רב חסדא: למדנו\u0004 בדרך של מדרש היקש וגזירה שווה, ובאופן זה: \u0003מציאה ממציאה, ומציאה מ\u0004המלה \u0003חיפוש\u0004 הסמוכה לה בכתוב, \u0003וחיפוש מחיפוש\u0004 בגזירה שווה, \u0003וחיפוש מנרות\u0004 שבאותו כתוב, \u0003ונרות מנר.\u0004","ומפרטים: \u0003מציאה ממציאה\u0004 בגזירה שווה — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"שבעת ימים שאר לא ימצא בבתיכם\"\u0004 (שמות יב, יט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם],\u0006 במקרא: \u0003\"ויחפש בגדול החל ובקטן כלה וימצא\u0004 הגביע באמתחת בנימין\u0003\"\u0004 (בראשית מד, יב). \u0003ו\u0004ענין \u0003מציאה מחיפוש דידיה\u0004 \u0005[שלו],\u0006 שהרי בפסוק זה נאמר \"ויחפש\" \"וימצא\".","\u0003וחיפוש\u0004 לומדים אנו מכתוב אחר \u0003מנרות,\u0004 דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004והיה \u0003בעת ההיא אחפש את ירושלים בנרות\"\u0004 (צפניה א, יב), \u0003ונרות\u0004 למדנו \u0003מנר\u0004 דכ \u0003תיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נר ה' נשמת אדם חפש כל חדרי בטן\"\u0004 (משלי כ, כז).","ובדומה לכך \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: לילי ארבעה עשר בודקים את החמץ לאור הנר. אף על פי שאין ראיה לדבר\u0004 שלאור הנר דוקא, \u0003זכר לדבר\u0004 ממדרש כתובים, \u0003שנאמר: \"שבעת ימים שאר לא ימצא\", ואומר: \"ויחפש בגדול החל ובקטן כלה\", ואומר: \"בעת ההיא אחפש את ירושלים בנרות\", ואומר: \"נר ה' נשמת אדם חפש\u0004 כל חדרי בטן\u0003\".\u0004","ושואלים לגופו של דבר: \u0003מאי\u0004 \u0005[מהו]\u0006 מה טעמו של \u0003\"ואומר\"\u0004 האחרון, כלומר לשם מה צריך פסוק אחרון זה, ולא די לנו בראיה מן הכתוב \"אחפש את ירושלים בנרות\" שנלמד משם שחיפוש יפה לו שייעשה בנרות?","ומשיבים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003האי\u0004 \u0005[אותו]\u0006 דבר שנאמר על \u0003\"בעת ההיא\" — קולא\u0004 \u0005[להקלה]\u0006 \u0003הוא דקאמר רחמנא\u0004 \u0005[שאמר ה']:\u0006 \u0003לא בדיקנא לה בירושלים בנהורא דאבוקה, דנפיש נהורא טובא\u0004 \u0005[אבדוק את ירושלים באור האבוקה, שמרובה אורה הרבה]\u0006 ומוצאים לאורה כל חטא ועון, \u0003אלא בנהורא דשרגא, דזוטר נהורא טפי, דעון רבה משתכח ועון זוטר לא משתכח\u0004 \u0005[באור הנר\u0006 אבדוק, \u0005שקטן אורו הרבה, שעוון גדול נמצא\u0006 על ידו, \u0005ועוון קטן אינו נמצא],\u0006 על כן: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003\"נר ה' נשמת אדם\u0004 חופש כל חדרי בטן\" שמשמע מכאן להיפך: שכל דבר נמצא על ידי הנר, והוא היפה לבדיקה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין בודקין\u0004 את החמץ \u0003לא לאור החמה, ולא לאור הלבנה, ולא לאור האבוקה, אלא לאור הנר,\u0004"],["\u0003מפני שאור הנר יפה לבדיקה, ואף על פי שאין ראיה לדבר — זכר לדבר, שנאמר \"שבעת ימים שאר לא ימצא בבתיכם\"\u0004 (שמות יב, יט), \u0003ואומר \"ויחפש בגדול החל\u0004 ובקטן כלה וימצא הגביע באמתחת בנימין\u0003\"\u0004 (בראשית מד, יב), \u0003ואומר \"בעת ההיא אחפש את ירושלים בנרות\"\u0004 (צפניה א, יב), \u0003ואומר: \"נר ה' נשמת אדם חפש כל חדרי בטן\"\u0004 (משלי כ, כז).","ושואלים: \u0003האי\u0004 \u0005[זה]\u0006 \u0003אור החמה\u0004 שאסרנו לבדוק בו \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 שהיה \u0003בחצר, האמר\u0004 \u0005[הרי אמר\u0006 כבר\u0005]\u0006 \u0003רבא: חצר אינה צריכה בדיקה, מפני שהעורבין\u0004 ושאר עופות בר \u0003מצויין שם,\u0004 ובודאי אכלו את כל החמץ שבחצר. \u0003אלא\u0004 תאמר שהיה הדבר \u0003באכסדרה\u0004 (מרפסת פתוחה שיש לה גג) שאין העורבים נכנסים לשם, ו\u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא: אכסדרה לאורה נבדקת,\u0004 שאינה צריכה נר, ודי באור שיש בה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003לארובה\u0004 (חלון) המצוי ב\u0003חדר.\u0004 ושואלים: \u0003ודהיכא\u0004 \u0005[ושל היכן]?\u0006 בבדיקת איזה מקום מדובר? \u0003אי לבהדי\u0004 \u0005[אם שכנגד]\u0006 \u0003ארובה\u0004 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו \u0003אכסדרה,\u0004 שאור החמה מרובה בה ומספיק לבדיקה. \u0003אלא\u0004 הכוונה \u0003לצדדין\u0004 של החדר, שאין לסמוך על אור החמה הבא מן הארובה אלא יש להביא נר ולבדוק.","ועוד שואלים: \u0003ואבוקה לא,\u0004 האם אין אורה מספיק כדי לבדוק בה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ונגה כאור תהיה קרנים מידו לו ושם חביון עזה\"\u0004 (חבקוק ג, ד) ופירשו שהקדוש ברוך הוא מעניק קרני הוד (\"קרנים מידו לו\") לצדיקים לעתיד לבוא, משל \u0003למה צדיקים דומין בפני שכינה — כנר בפני האבוקה.\u0004 ומכאן ראיה לעניננו שאור האבוקה רב ועדיף מאור הנר! \u0003ו\u0004כן \u0003אמר רבא: אבוקה להבדלה\u0004 כאשר מברך על המאורות \u0003מצוה מן המובחר,\u0004 משמע שאור האבוקה מאיר ביותר!","\u0003אמר רב נחמן בר יצחק:\u0004 לא משום שאבוקה אינה מאירה דיה, אלא הטעם הוא כי \u0003זה\u0004 הנר — \u0003יכול להכניסו לחורין ולסדקין\u0004 מפני שהוא קטן, \u0003וזה\u0004 האבוקה — \u0003אינו יכול להכניסו לחורין ולסדקין\u0004 מפני גודלה. \u0003רב זביד אמר\u0004 טעם אחר: \u0003זה\u0004 הנר — \u0003אורו לפניו\u0004 ואין האש מאירה אחורנית, \u0003וזה\u0004 האבוקה — \u0003אורו\u0004 נמשך \u0003לאחריו,\u0004 ובמקום להאיר במקום הבדיקה שלפניו היא מטילה אורה על הבודק עצמו. \u0003רב פפא אמר:\u0004 הטעם הוא, \u0003האי\u0004 \u0005[זה]\u0006 באבוקה — \u0003בעית\u0004 \u0005[מפחד]\u0006 שמא יגרום לשריפה, \u0003והאי\u0004 \u0005[וזה]\u0006 בנר — \u0003לא בעית\u0004 \u0005[מפחד].\u0006 \u0003רבינא אמר: האי\u0004 \u0005[זה]\u0006 הנר \u0005—\u0006 \u0003משך נהורא\u0004 \u0005[נמשך האור]\u0006 ודולק ביציבות, \u0003והאי מיקטף\u0004 \u0005[וזו]\u0006 האבוקה — \u0003איקטופי\u0004 \u0005[מקפץ]\u0006 אורה והולך, ואף שאורה גדול משל נר איננו נוח לבדוק בו.","במשנה נאמר ש \u0003\"כל מקום שאין מכניסין\u0004 בו חמץ אינו צריך בדיקה \u0003\"\u0004. ושואלים: \u0003\"כל מקום\"\u0004 שנאמר כאן, \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף\u0005, מה]\u0006 על הפרטים שהבאנו? ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא\u0006 להוסיף דבר \u0005זה ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003חורי\u0004 כתלי ה\u0003בית העליונים\u0004 מדי \u0003והתחתונים\u0004 מדי, שאינם נוחים לשימוש, \u0003ו\u0004כן \u0003גג היציע\u0004 (גג משופע של בנין נספח לבית), \u0003וגג המגדל\u0004 (ארון), \u0003ורפת בקר, ולולין\u0004 לתרנגולים, \u0003ומתבן\u0004 (מחסן התבן), \u0003ואוצרות יין ואוצרות שמן — אין צריכין בדיקה. רבן שמעון בן גמליאל אומר: מטה החולקת בתוך הבית ומפסקת\u0004 בין חלק אחד של הבית לחבירו — \u0003צריכה בדיקה\u0004 שמא יש תחתיה חמץ.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על ברייתא זו ממקור אחר: \u0003חור שבין\u0004 דירת \u0003אדם ל\u0004דירת \u0003חבירו\u0004 באמצע הכותל — \u0003זה בודק עד מקום שידו מגעת, וזה בודק עד מקום שידו מגעת, והשאר\u0004 מה שבאמצע \u0003מבטלו\u0004 כל אחד \u0003בלבו. רבן שמעון בן גמליאל אומר: מטה החולקת בתוך הבית, ועצים ואבנים סדורים תחתיה, ומפסקת — אינה צריכה בדיקה.\u0004","\u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003מטה\u0004 על ענין \u0003מטה,\u0004 כי במקום אחד אמר רבן שמעון בן גמליאל שצריכה בדיקה, ובמקום אחר אמר שאינה צריכה, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מ\u0003חורין\u0004 על \u0003חורין,\u0004 שקודם אמרנו שאין חורי הבית צריכים בדיקה, ובברייתא אחרונה זו למדנו שצריכים!","ומתרצים: מענין \u0003חורין\u0004 על ענין \u0003חורין לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאין צריך בדיקה — \u0003ב\u0004חורים \u0003עילאי ובתתאי\u0004 \u0005[עליונים ותחתונים]\u0006 שהם גבוהים או נמוכים מכדי שאפשר להשתמש בהם, \u0003והא\u0004 \u0005[וזה]\u0006 שצריך בדיקה — \u0003במיצעי\u0004 \u0005[באמצעיים].\u0006 מענין \u0003מטה\u0004 על ענין \u0003מטה לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שצריכה בדיקה — \u0003דמידליא\u0004 \u0005[שמוגבהת]\u0006 מן הקרקע, \u0003הא\u0004 \u0005[זו]\u0006 שאינה צריכה — \u0003דמיתתאי\u0004 \u0005[שנמוכה],\u0006 שאין שימוש בחלל שתחתיה, ואין לשער שיבואו להניח שם חמץ.","כיון שהובאה ברייתא זו שואלים: \u0003והאמנם אוצרות יין אין צריך בדיקה?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אוצרות יין — צריך בדיקה, אוצרות שמן — אין צריך בדיקה!\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003במסתפק\u0004 (במשתמש) ביין שבמחסן. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר באוצר שמשתמש ממנו לאספקה\u0005,\u0006 \u0003שמן נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש מחמץ!","ומשיבים: \u0003שמן — יש קבע לאכילה\u0004 בשיעור מסויים, ויודע אדם לפני האוכל באיזו כמות שמן ישתמש לאכילה זו, והנכנס קודם אכילה ליטול שמן אין חמץ מצוי בידו. ואילו ב\u0003יין\u0004 — \u0003אין קבע לשתיה\u0004 ואין לה שיעור ידוע, וייתכן שבאמצע הסעודה יצטרכו ליין נוסף והשמש ייכנס למחסן ופרוסת לחם בידו ליטול משם יין.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: עשו אוצרות שכר בבבל כאוצרות יין בארץ ישראל,\u0004 שאם \u0003מסתפק\u0004 מהם צריך לבודקם.","\u0003אמר רב חסדא: בי\u0004 \u0005[בית,\u0006 מחסן\u0005]\u0006 \u0003דגים אין צריך בדיקה.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003צריכין בדיקה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003ברברבי\u0004 \u0005[בגדולים],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בזוטרי\u0004 \u0005[בקטנים].\u0006 שבקטנים אינו יודע בדיוק כמה הם, ושמא יצטרך להוסיף ולהביא דגים באמצע הסעודה.","\u0003אמר רבה בר רב הונא: בי מילחי ובי קירי\u0004 \u0005[בית\u0006 מקום \u0005המלח, ובית\u0006 מקום \u0005השעוה\u0006 לנרות\u0005]\u0006 \u0003צריך בדיקה,\u0004 שמא יצטרך להם באמצע הסעודה. \u0003אמר רב פפא: בי ציבי ובי תמרי\u0004 \u0005[בית העצים ובית התמרים]\u0006 \u0003צריך בדיקה\u0004 מאותו טעם.","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אין מחייבין אותו להכניס ידו לחורין ולסדקין לבדוק — מפני הסכנה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003סכנה\u0004 זו שמדובר בה? \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 \u0003מפני סכנת עקרב\u0004 העלול להיות בחור — אם כן \u0003כי\u0004 \u0005[כאשר]\u0006 הוא \u0003משתמש\u0004 בחור זה, \u0003היכי\u0004 \u0005[איך]\u0006 הוא \u0003אישתמש\u0004 \u0005[משתמש]\u0006 אם יש בו סכנת עקרב? וחור כזה מן הדין שלא יהיה זקוק כלל לבדיקה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003נפל\u0004 החמץ לשם, אבל באמת אין זה מקום לשימוש קבוע.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בש \u0003נפל, למה לי בדיקה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חמץ שנפלה עליו מפולת — הרי הוא כמבוער!\u0004 ואף כאן, כשנפל לחור, הרי זה כאילו נתבער! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שאמרנו שחמץ זה כמבוער מדובר שהיתה מפולת \u0003שאין הכלב יכול לחפש אחריו, הכא\u0004 \u0005[כאן]\u0006 מדובר בחור שאינו עמוק \u0003כשהכלב יכול לחפש אחריו\u0004 ולהוציאו.","על אותה תוספתא מקשים מצד אחר: מדוע נחשוש מפני הסכנה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: שלוחי מצוה אינן ניזוקין\u0004 שאין לחשוש מסכנה שמא תבוא לו תוך עשיית מצוה? \u0003אמר רב אשי:\u0004 כאן חוששים אנו \u0003שמא תאבד לו\u0004 גם \u0003מחט\u0004 באותו מקום, \u0003ואתי לעיוני בתרה\u0004 \u0005[ויבוא לחפש אחריה]\u0006 בשעה שבודק את החמץ, ונמצא שבדיקתו אינה לצורך מצוה בלבד, ואין זכות המצוה מגינה עליו עוד.","ושואלים: \u0003וכהאי גוונא לאו\u0004 \u0005[ו\u0006האם במקרה \u0005כגון זה לא]\u0006 \u0003מצוה הוא?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"סלע זו\u0004 אני נותן \u0003לצדקה בשביל שיחיה בני\" או\u0004 בשביל \u0003\"שאהיה בן העולם הבא\"\u0004"],["\u0003הרי זה צדיק גמור\u0004 לענין זה. הרי שאף כשהיתה לו כוונה של קבלת גמול ושכר, אין היא גורעת מערך המצווה! ומשיבים: \u0003דילמא, בתר דבדק אתי לעיוני בתרה\u0004 \u0005[שמא, לאחר שבדק יבוא לחפש אחריה].\u0006 וכיון שגמר כבר את המצוה, שוב אין זכות זו מגינה עליו בשעת החיפוש אחר המחט.","\u0003רב נחמן בר יצחק אמר:\u0004 \"מפני הסכנה\" שאמרו היתה הכוונה \u0003משום סכנת הגוים. ו\u0004לשיטת התנא \u0003פלימו היא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חור שבין יהודי לארמאי\u0004 \u0005[לגוי]\u0006 — \u0003בודק עד מקום שידו מגעת, והשאר מבטלו בלבו. פלימו אמר: כל עצמו\u0004 של החור \u0003אינו בודק\u0004 כלל \u0003מפני הסכנה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 טיבה של אותה \u0003סכנה, אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003סכנת כשפים\u0004 שיחשוד בו הגוי שמא כשפים הוא עושה לו, ויבוא לידי איבה וסכנה. ושואלים: אם כן, אם הגוי חושדו בכשפים שהוא עושה לו אגב בדיקת החור, \u0003כי אישתמיש היכי אישתמיש\u0004 \u0005[כאשר השתמש\u0006 בחור והניח בו חמץ \u0005כיצד השתמש\u0006 בו\u0005]?\u0006 וחור שאין משתמשים בו אינו צריך בדיקה! ומשיבים: \u0003התם כי אישתמיש\u0004 \u0005[שם, כאשר השתמש] —\u0006 היה זה \u0003יממא ונהורא\u0004 \u0005[יום, ואור],\u0006 \u0003ולא מסיק אדעתיה\u0004 \u0005[העלה על דעתו]\u0006 לחשוב על כשפים. \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003ליליא ושרגא\u0004 \u0005[לילה ונר]\u0006 \u0003הוא, ומסיק אדעתיה\u0004 \u0005[ומעלה על דעתו].\u0006","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: שלוחי מצוה אינן ניזוקין,\u0004 והעושה לצורך מצוה אינו צריך איפוא לחשוש מפני נזק! ודוחים: \u0003היכא דשכיח היזיקא שאני\u0004 \u0005[במקום שמצוי ההיזק שונה\u0006 הדבר\u0005],\u0006 שאין לסמוך על הנס. \u0003שנאמר\u0004 כיוצא בזה בשמואל הנביא, לאחר שציווהו ה' ללכת ולמשוח את דוד למלך במקומו של שאול: \u0003\"ויאמר שמואל איך אלך ושמע שאול והרגני ויאמר ה' עגלת בקר תקח בידך\u0004 ואמרת לזבוח לה' באתי\u0003\"\u0004 (שמואל א טז, ב), הרי שאף כשיש ציווי מאת הקדוש ברוך הוא, יש לחשוש מנזק שכיח ומצוי.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב: הני בני בי רב דדיירי בבאגא\u0004 \u0005[אותם בני בית\u0006 מדרשו של \u0005הרב הדרים בשדות]\u0006 הרחוקים מן העיר, \u0003מהו למיתי קדמא וחשוכא לבי רב\u0004 \u0005[שיבואו בהשכמה ובערב לבית\u0006 מדרשו של \u0005הרב],\u0006 היש להם לחשוש מפני השודדים? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ניתו\u0004 \u0005[שיבואו]\u0006 והאחריות \u0003עלי ועל צוארי.\u0004 ושאלוהו: \u0003ניזיל מאי\u0004 \u0005[וללכת\u0006 חזרה לביתם \u0005מה\u0006 דעתך\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא ידענא\u0004 \u0005[איני יודע]\u0006 אם אף בהליכה חזרה אפשר לסמוך על זכות המצוה.","\u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003אמר ר' אלעזר: שלוחי מצוה אינן ניזוקין לא בהליכתן ולא בחזירתן.\u0004 ומעירים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר דבריו,","\u0003כי האי תנא דתניא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003איסי בן יהודה אומר: כלפי שאמרה תורה \"ולא יחמד איש את ארצך\u0004 בעלותך ליראות את פני ה' אלוהיך שלש פעמים בשנה\u0003\"\u0004 (שמות לד, כד), \u0003מלמד שתהא פרתך רועה באפר\u0004 (באחו) \u0003ואין חיה מזיקתה, תרנגולתך מנקרת באשפה ואין חולדה מזיקתה.\u0004 אף כי הכל עלו לרגל, ואין שומרים כראוי על המשק.","\u0003והלא דברים קל וחומר; ומה אלו שדרכן לזוק\u0004 כרגיל בכל מיני נזקים — \u0003אינן ניזוקין\u0004 בזכות המצווה, \u0003בני אדם\u0004 העולים לרגל שכרגיל \u0003שאין דרכן לזוק\u0004 שהם שומרים עצמם מפני הסכנה — \u0003על אחת כמה וכמה\u0004 שאין ניזוקים בשעת עשיית המצוה. \u0003אין לי אלא\u0004 שלא ינזקו \u0003בהליכה, בחזרה\u0004 מן המקדש \u0003מנין? תלמוד לומר: \"\u0004ובשלת ואכלת במקום אשר יבחר ה' אלהיך בו \u0003ופנית בבקר והלכת לאהליך\"\u0004 (דברים טז, ז), \u0003מלמד שתלך ותמצא אהלך\u0004 (ביתך) \u0003בשלום.\u0004","ושואלים: \u0003וכי מאחר\u0004 ש\u0003אפילו בחזירה\u0004 למדו שזכות המצווה מגינה \u0003בהליכה, למה לי\u0004 לומר זאת? נדע את הדבר מקל וחומר! ומשיבים: באמת בא הפסוק הראשון ללמדנו \u0003כ\u0004שיטת \u0003ר' אמי,\u0004 ש\u0003אמר ר' אמי: כל אדם שיש לו קרקע\u0004 חייב להיות \u0003עולה לרגל, ושאין לו קרקע — אין\u0004 חייב להיות \u0003עולה לרגל,\u0004 שהרי הוזכרה \"ארצך\" בענין \"בעלותך ליראות\".","ואגב הזכרת עליה לרגל ומצוה שיש בה כוונה אחרת, מביאים מה ש\u0003אמר ר' אבין בר רב אדא אמר ר' יצחק: מפני מה אין פירות גינוסר\u0004 המשובחים מאוד \u0003בירושלים,\u0004 ולא נשתבחה ירושלים אף במעלה זו? \u0003כדי שלא יהו עולי רגלים אומרים: אלמלא לא עלינו\u0004 לרגל \u0003אלא\u0004 כדי \u0003לאכול פירות גינוסר בירושלים — דיינו. נמצאת עליה\u0004 לרגל \u0003שלא לשמה.\u0004","\u0003כיוצא בו אמר ר' דוסתאי בר' ינאי: מפני מה אין חמי טבריא בירושלים — כדי שלא יהו עולי רגלים אומרים: אלמלא לא עלינו\u0004 לרגל \u0003אלא\u0004 כדי \u0003לרחוץ בחמי טבריא — דיינו, ונמצאת עלייה\u0004 לרגל \u0003שלא לשמה.\u0004","במשנה שנינו: \u0003\"ובמה אמרו\u0004 שחייבים לבדוק חמץ ב\u0003שתי שורות\u0004 במרתף \u0003\"\u0004. ותוהים: \u0003מרתף מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמו]?\u0006 הרי בכלל לא הוזכר קודם המרתף, ומדוע באים עתה לדון בו?","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש להבין את המשפט השלם: \u0003כל מקום שאין מכניסין בו חמץ — אין צריך בדיקה, ואוצרות יין ואוצרות שמן נמי\u0004 \u0005[גם כן]\u0006 \u0003אין צריך בדיקה, ובמה אמרו שתי שורות במרתף — ב\u0004\u0003מקום שמכניסין בו חמץ,\u0004 שמדובר \u0003במסתפק\u0004 (משתמש) מן הדבר שבאוצר ושבמרתף לצורך סעודתו.","במשנה שנינו: \u0003\"בית שמאי אומרים: שתי שורות\u0004 על פני כל המרתף \u0003\"\u0004. \u0003אמר רב יהודה: שתי שורות שאמרו\u0004 משמען השורות בצד הקדמי של החביות, שתי שורות שלמות \u0003מן הארץ ועד שמי קורה,\u0004 כלומר עד גובה התקרה. \u0003ור' יוחנן אמר:\u0004 הכוונה בשתי שורות היא \u0003שורה אחת\u0004 בזוית ישרה \u0003כמין גאם,\u0004 כלומר גם השורה הקדמית ביותר לכל רחבה וגובהה, וגם השורה העליונה ביותר לאורכה ולרוחבה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יהודה, תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ר' יוחנן. תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב יהודה, בית שמאי אומרים: שתי שורות על פני כל המרתף, ושתי שורות שאמרו\u0004 משמען — \u0003מן הארץ ועד שמי קורה. תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003ר' יוחנן: שתי שורות על פני כל המרתף\u0004 משמען — שורה \u0003חיצונה\u0004 זו ש\u0003רואה את הפתח, ועליונה\u0004 היא השורה ה\u0003רואה את הקורה,\u0004 שורה \u0003שלפנים הימנה,\u0004 מן החיצונה, \u0003ושלמטה הימנה,\u0004 מן העליונה — \u0003אין צריך בדיקה.\u0004","במשנה שנינו: \u0003\"בית הלל אומרים:\u0004 די שיבדוק \u0003שתי שורות החיצונות שהן העליונות\".\u0004 אף במשמעות דבר זה נחלקו: \u0003אמר רב\u0004 שהכוונה היא שורת חביות \u0003עליונה\u0004 קדמית \u0003ו\u0004השורה \u0003שלמטה הימנה. ושמואל אמר\u0004 שהכוונה היא לשורה \u0003העליונה\u0004 הקדמית \u0003ו\u0004זו \u0003שלפנים הימנה\u0004 לעבר המרתף. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב — דייק\u0004 מן הלשון שאמרו \u0003\"חיצונות\",\u0004 משמע ששתי השורות הללו פונות כלפי חוץ. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 גם \u0003\"עליונות\" קתני\u0004 \u0005[שנינו]\u0006 ששתיהן בגובה המרתף! ומשיבים: שהוא מפרש שלשון זו באה רק \u0003למעוטי תתאי דתתייתא\u0004 \u0005[למעט\u0006 את \u0005התחתונה שבתחתונות],\u0006 שהמשנה למדתנו שאין יורדים משתי שורות.","\u0003ושמואל אמר: עליונה ושלפנים הימנה. מאי טעמא\u0004 \u0005[מה טעמו]\u0006 — \u0003דייק\u0004 מהלשון \u0003\"עליונות\",\u0004 משמע שלוקחים רק שתי שורות משכבת החביות העליונה, ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"חיצונה\" קתני\u0004 \u0005[שנינו]!\u0006 ומשיבים שדבר זה בא \u0003למעוטי גוייאתא דגוייאתא\u0004 \u0005[פנימיות שבפנימיות]\u0006 שאין ממשיכים לבדוק יותר משתי שורות. ומעירים: \u0003ר' חייא תני כוותיה\u0004 \u0005[שנה\u0006 בברייתא \u0005כשיטת]\u0006 \u0003רב, ו\u0004אולם \u0003כולהו תנאי תנו כוותיה\u0004 \u0005[וכל התנאים\u0006 האחרים במשניותיהם \u0005שנו כשיטת]\u0006 \u0003שמואל.\u0004 ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטת]\u0006 \u0003שמואל.\u0004"],["\u0003אין חוששין\u0004 לאחר בדיקה \u0003שמא גיררה חולדה\u0004 חמץ \u0003מבית לבית וממקום למקום\u0004 והחזירה את החמץ למקום שנבדק, ש\u0003אם כן\u0004 אתה חושש — יש גם לחשוש שמא גררה \u0003מחצר לחצר ומעיר לעיר,\u0004 ואם כן — \u0003אין לדבר סוף,\u0004 ואין איפוא אפשרות לסמוך על כל בדיקה שהיא.","מדברי המשנה בענין חולדה מדייקים בגמרא: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דוקא משום ש\u0003לא חזינא דשקל\u0004 \u0005[ראינו שלקח]\u0006 העכבר, \u0003הא\u0004 \u0005[הרי]\u0006 שאם \u0003חזינא דשקל\u0004 \u0005[ראינו שלקח] —\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו],\u0006 \u0003ובעי\u0004 \u0005[וצריך]\u0006 \u0003בדיקה\u0004 נוספת שמא הכניס בו העכבר דבר מה.","ועל מסקנה זו מקשים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003נימא אכלתיה\u0004 \u0005[נאמר\u0006 שהחולדה \u0005אכלתו]\u0006 את הלחם שלקחה! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בדומה לזה: \u0003מדורות\u0004 (דירות) \u0003הגוים טמאים,\u0004 וטעמו של דבר שמא הפילה אשתו של הגוי נפל, והגוים קוברים את הנפלים בבתיהם, ונמצא הבית טמא טומאת מת מחמת הנפל. \u0003וכמה ישהה\u0004 גוי \u0003במדור, ויהא המדור צריך בדיקה — ארבעים יום.\u0004 שנפל בן פחות מארבעים יום אינו כלום, שכן זה הוא זמן יצירת הוולד.","\u0003ואף על פי שאין לו\u0004 לגוי \u0003אשה\u0004 גוזרים טומאה, לפי שלא חלקו חכמים בגזירותיהם שלא יבואו הבריות לטעות ולהכשל (מאירי). \u0003וכל מקום שחולדה וחזיר יכולין להלוך\u0004 בו בלי הפרעה — \u0003אינו צריך בדיקה\u0004 לנפל, כי אנו מניחים שודאי אם היה קבור שם, אכלו אלה אותו. ולמדנו מכאן לפי דרכנו שחכמים סבורים שהחולדות אוכלות את כל מה שהן מוצאות. ואם כן אף לענין חמץ, גם אם ראינו שנטל העכבר את החמץ נאמר שמן הסתם כבר אכלו, ואין צורך בבדיקה חוזרת!","\u0003אמר ר' זירא: לא קשיא\u0004 \u0005[קשה]\u0006 ויש לחלק בין הדברים; \u0003הא\u0004 \u0005[זה]\u0006 שהתרנו — \u0003בבשר, והא\u0004 \u0005[וזה]\u0006 שאמרנו שיש לחשוש — \u0003בלחם.\u0004 והסבר הדברים: \u0003בבשר — לא משיירא\u0004 \u0005[משיירת]\u0006 החולדה, ולכן אומרים שודאי נאכל הנפל כולו. \u0003בלחם — משיירא\u0004 \u0005[משיירת]\u0006 היא פירורים, והם המצריכים בדיקה חוזרת.","\u0003אמר רבא: האי מאי\u0004 \u0005[זה מהו]?\u0006 כלומר מה מקום לקושיה זו, שמתחילה לא היה לה בסיס, \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בנפל — \u0003אימור הוה, אימור לא הוה\u0004 \u0005[אמור\u0006 ש\u0005היה\u0006 נפל, \u0005אמור\u0006 ש\u0005לא היה].\u0006 שהרי אין זה וודאי. \u0003ואם תמצא לומר הוה\u0004 \u0005[היה]\u0006 — \u0003אימור אכלתיה\u0004 \u0005[אמור\u0006 ש\u0005אכלתו],\u0006 שהרי עצם קיומו של הנפל היה רק השערה ולא יותר. ואפילו אם היה, ישנה סבירות גבוהה שנאכל. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 ש\u0003ודאי דחזינא דשקל\u0004 \u0005[שראינו שלקח]\u0006 לחם — \u0003מי יימר דאכלתיה\u0004 \u0005[מי יאמר שאכלתו]?\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ספק וודאי, ו\u0004כלל בידינו בכל התחומים: ש\u0003אין ספק מוציא מידי ודאי,\u0004 ולכן אין ספק־אכילה של החולדה מוציא מידי ודאי מציאותו של החמץ.","על כלל זה מקשים: \u0003ו\u0004כי \u0003אין ספק מוציא מידי ודאי?! והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבר\u0004 שאנו סומכים עליו שהוא מדקדק בהפרשת מעשרות, \u0003שמת, והניח מגורה\u0004 (מחסן) \u0003מליאה פירות, ואפילו הן בני יומן\u0004 כלומר שקנה אותן באותו יום עצמו שמת — \u0003הרי הן בחזקת מתוקנין,\u0004 וסומכים עליו שמן הסתם עישרם בעצמו או שציווה לאחר לעשרם. \u0003והא הכא\u0004 \u0005[והרי כאן],\u0006 ש\u0003ודאי טבילי הני פירי\u0004 \u0005[טבל הן אותן הפירות],\u0006 שהרי פירות שלא הפרישו מהם מעשר טבל הם, \u0003וספק מעושרין\u0004 על ידי החבר \u0003וספק לא מעושרין,\u0004 ובכל זאת \u0003קאתי\u0004 \u0005[בא]\u0006 \u0003ספק\u0004 שמעושרים \u0003ומוציא מידי ודאי\u0004 טבל!","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003ודאי וודאי הוא,\u0004 ש\u0003ודאי\u0004 הפירות \u0003מעשרי\u0004 \u0005[מעושרים],\u0006 ואפשר לסמוך בכך על דברי \u0003ר' חנינא חוזאה.\u0004 ש\u0003אמר ר' חנינא חוזאה: חזקה על חבר שאין מוציא מתחת ידו דבר שאינו מתוקן\u0004 (מעושר). ולכן יש לראות בכך וודאות, שוודאי כבר עישר החבר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ואפשר לתרץ בדרך אחרת: גם שם, לגבי הפירות, \u0003ספק וספק הוא, דילמא מעיקרא אימור דלא טבילי\u0004 \u0005[שמא מתחילה אמור שלא נעשו טבל],\u0006 שיש אפשרות שפירות אף שלא עושרו לא יחשבו כטבל, וכדברי \u0003ר' אושעיא.\u0004","ש\u0003אמר ר' אושעיא: מערים אדם על תבואתו\u0004 שלא להפריש ממנה מעשרות מדין תורה, \u0003ומכניסה במוץ שלה\u0004 אל חצירו לפני שהוא דש וזורה, \u0003כדי שתהא בהמתו אוכלת\u0004 ממנה \u0003ופטורה\u0004 בכך \u0003מן המעשר.\u0004 שחובת המעשר על פירות גמורים חלה גם על סוג הפירות הניתן למאכל בהמה, ואולם תבואה או פירות שלא נגמרה המלאכה בהם, יכול לתת לבהמתו בעודם טבל. ולפי הלכה זו הלא יתכן שהפירות שהכניס אותו חבר עדיין לא התחייבו במעשרות ואינם טבל, ולהלכה רק ספק וספק הוא.","ומקשים עוד על רבא: \u0003ו\u0004כי \u0003אין ספק מוציא מידי ודאי?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר ר' יהודה: מעשה בשפחתו של\u0004 ישראל \u0003מציק\u0004 (אדם תקיף) \u0003אחד ב\u0004עיירה \u0003רימון, שהטילה נפל לבור\u0004"],["\u0003ובא כהן והציץ בו\u0004 כדי \u0003לידע\u0004 בנפל זה \u0003אם זכר הוא אם נקבה היא,\u0004 שיש הבדל בטומאת יולדת בין יולדת זכר ונקבה (ויקרא פרק יב). \u0003ובא מעשה לפני חכמים\u0004 לדון האם טמא הכהן משום מאהיל על המת, \u0003וטיהרוהו. מפני שחולדה וברדלס\u0004 (חיה טורפת קטנה) \u0003מצויין שם,\u0004 ומן הסתם כבר נאכל הנפל על ידיהם קודם לכן.","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003ודאי הטילה\u0004 נפל, \u0003וספק גררוהו\u0004 חולדה וברדלס \u0003וספק לא גררוהו ההיא שעתא\u0004 \u0005[\u0006ב\u0005אותה שעה],\u0006 \u0003ו\u0004בכל זאת פסקו כי \u0003קאתי\u0004 \u0005[ובא]\u0006 \u0003ספק ומוציא מידי ודאי!\u0004 ודוחים: \u0003לא תימא\u0004 \u0005[תאמר\u0006 בברייתא\u0005]\u0006 \u0003\"שהטילה\u0004 ודאי \u0003נפל לבור\"\u0004 שהיה ברור כן מתחילה\u0003, אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003\"שהפילה כמין נפל לבור\",\u0004 ושמא לא היה זה נפל כלל אלא חתיכת דם קרוש שאין בה טומאת מת כלל, \u0003והוי\u0004 \u0005[והריהו]\u0006 \u0003ספק וספק,\u0004 ספק היה דבר המטמא וספק אכלוהו חולדות.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"לידע אם זכר הוא אם נקבה היא\" קתני\u0004 \u0005[שנינו]!\u0006 ומשמע מכאן שרק בדבר זה היה הספק, ומכל מקום ודאי נפל היה! ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 שרצה הכהן \u0003לידע אם רוח\u0004 (דבר שאינו ולד) \u0003הפילה אם נפל הפילה, ואם תמצא לומר נפל הפילה — לידע אם זכר הוא ואם נקבה היא.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003התם\u0004 \u0005[שם]\u0006 אין זה ודאי וספק אלא \u0003ודאי וודאי הוא, כיון\u0004 ש\u0003חולדה וברדלס מצויין שם — ודאי גררוהו בההיא שעתא\u0004 \u0005[באותה שעה].\u0006 \u0003נהי דשיורי משיירא\u0004 \u0005[אף על פי שמשיירת]\u0006 החולדה ממאכלה — \u0003מיגרר מיהת\u0004 \u0005[ואולם לגרור]\u0006 המאכל לחורם \u0003ודאי גררום בההיא שעתא\u0004 \u0005[באותה שעה].\u0006 \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בתירוץ זה: \u0003נהי\u0004 \u0005[אף על פי]\u0006 ש\u0003ודאי אכלום לא אמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003ודאי גררוהו לחורייהו\u0004 \u0005[גררוהו לחורם] —\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואין מכאן ביטול לסברה הכללית שאין ספק מוציא מידי ודאי.","ומעתה דנים בצד יסודי יותר של ההלכה במשנה. \u0003ומי אמרינן\u0004 \u0005[והאם אנו אומרים]\u0006 \u0003אין חוששין שמא גררה חולדה? והא קתני סיפא\u0004 \u0005[והרי שנינו\u0006 ב\u0005סוף\u0006 המשנה הבאה\u0005]:\u0006 \u0003מה שמשייר\u0004 לאחר הבדיקה \u0003יניחנו בצנעה, שלא יהא צריך בדיקה אחריו.\u0004 הרי שבכל זאת חוששים לחולדה שמא תבוא ותקח מהחמץ שנותר שם!","\u0003אמר אביי: לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בארבעה עשר\u0004 צריך בדיקה, \u0003והא\u0004 \u0005[זה]\u0006 — \u0003בשלשה עשר\u0004 אין צריך בדיקה. והסבר הדברים: \u0003בשלשה עשר\u0004 בניסן \u0003דשכיח ריפתא בכולהו בתי\u0004 \u0005[ש\u0006עוד \u0005מצוי לחם בכל הבתים] —\u0006 \u0003לא מצנעא\u0004 \u0005[מצניעה]\u0006 אותו חולדה, ואין חוששים שגררה והטמינה. \u0003בארבעה עשר\u0004 בניסן ש\u0003לא שכיחא ריפתא בכולהו בתי\u0004 \u0005[מצויה הפת בכל הבתים] —\u0006 \u0003מצנעא\u0004 \u0005[מצניעה\u0006 אותו\u0005].\u0006","\u0003אמר רבא\u0004 בתמיהה: \u0003וכי חולדה נביאה היא! דידעא דהאידנא ארביסר, ולא אפי עד לאורתא, ומשיירא ומטמרא\u0004 \u0005[שהיא יודעת שעכשיו ארבעה עשר\u0006 בניסן הוא\u0005, ולא יאפה עד הערב, ומשיירת\u0006 החולדה \u0005ומטמינה]\u0006 בחורה?! \u0003אלא,\u0004 יש לדחות דברים אלה וכך יש לומר, \u0003אמר רבא: מה שמשייר\u0004 מן הבדיקה — \u0003יניחנו בצנעה, שמא תטול חולדה בפנינו, ויהא צריך בדיקה אחריו.\u0004 וכדי להימנע מכך נתנה המשנה עצה טובה להיזהר ולהצניע את החמץ הבדוק.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רבא: הרוצה לאכול חמץ אחר בדיקה כיצד יעשה? מה שמשייר — יניחנו בצנעה, שלא תבוא חולדה ותיטול בפנינו, ויהא צריך בדיקה אחריו.\u0004","\u0003רב מרי אמר:\u0004 אפילו כשלא ראינו חולדה שנטלה בפנינו ממש, בכל זאת יש להצניע, \u0003גזירה שמא יניח עשר\u0004 פרוסות לחם \u0003וימצא תשע.\u0004 ואז כיון שברור שמישהו לקח את הפרוסה העשירית, יצטרך לחזור ולבדוק.","בהמשך לדיון בענין חמץ שנטל העכבר ממנו, מביאים פסקי הלכה ובעיות הלכתיות הנוגעות לפרטי דינים אלה. \u0003תשע ציבורין\u0004 (ערימות) \u0003של מצה ואחד של חמץ, ואתא\u0004 \u0005[ובא]\u0006 \u0003עכבר\u0004 בפנינו \u0003ושקל\u0004 \u0005[ולקח]\u0006 מציבור אחד. \u0003ולא ידעינן\u0004 \u0005[יודעים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מצה שקל\u0004 \u0005[לקח]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003חמץ שקל\u0004 \u0005[לקח] —\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 דומה להלכה של \u0003תשע חנויות\u0004 שתובא להלן. אם \u0003פירש\u0004 (יצא, נחלק משהו) מאחד הציבורים, ואיננו יודעים אם היה זה מן המצה או החמץ, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003עכבר\u0004 בפנינו \u0003ושקל\u0004 \u0005[ולקח]\u0006 — \u0003היינו סיפא\u0004 \u0005[הרי זה\u0006 דומה להלכה האחרת ב\u0005סופה\u0006 של אותה משנה\u0005],\u0006","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 היו בעיר \u0003תשע חנויות, כולן מוכרין בשר שחוטה\u0004 שהוא בשר כשר, ועוד חנות \u0003אחת\u0004 ה\u0003מוכרת בשר נבלה. ולקח\u0004 בשר \u0003מאחת מהן, ואינו יודע מאיזה מהן לקח — ספיקו אסור\u0004 באכילה, שמא נבילה היא. מתוך ההנחה ההלכתית ש\"כל קבוע (כלומר שניטל ממקום קבוע) כמחצה על מחצה\" והרי זה ספק שקול.","\u0003ובנמצא\u0004 אם נמצאה חתיכת בשר ברחובה של העיר — \u0003הלך אחר הרוב.\u0004 שאם רוב חנויות העיר מוכרות בשר שחוטה אפשר לסמוך שהבשר כשר, על סמך ההנחה שכל הפורש — מן הרוב הוא פורש, ואם רוב החנויות מוכרות בשר נבילה — אסור. והוא הדין אם כן לציבורי המצה והחמץ.","מקרה אחר: היו \u0003שני ציבורין, אחד של מצה ואחד של חמץ. ולפניהם שני בתים, אחד בדוק\u0004 מן החמץ \u0003ואחד שאינו בדוק. ואתו\u0004 \u0005[ובאו]\u0006 \u0003שני עכברים, אחד שקל\u0004 \u0005[לקח]\u0006 בפנינו \u0003מצה, ואחד שקל\u0004 \u0005[לקח]\u0006 בפנינו \u0003חמץ. ולא ידעינן הי להאי עייל והי להאי עייל\u0004 \u0005[ואין אנו יודעים איזה לכאן נכנס ואיזה לכאן נכנס],\u0006 והשאלה היא אם נכנס העכבר המכניס את החמץ לבית הבדוק או לשאינו בדוק, \u0003היינו\u0004 \u0005[הרי זה]\u0006 דומה להלכה ב\u0003שתי קופות\u0004 (סלים).","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 היו \u0003שתי קופות, אחת של חולין ואחת של תרומה. ולפניהן שני סאין\u0004 (כלים גדולים), \u0003אחד של חולין ואחד של תרומה. ונפלו אלו לתוך אלו,\u0004 ויש אפשרות שנפלה התרומה לתוך החולין, והרי זה מדומע ואסור לזרים מספק — בכל זאת \u0003מותרין. שאני אומר\u0004 (כלומר, מניח) ש\u0003חולין לתוך חולין נפלו, ותרומה לתוך תרומה נפלה.\u0004 ואף לענין חמץ כן, אפשר להניח שהעכבר הכניס את החמץ לבית שאינו בדוק ואין צריך לבדוק שנית.","את ההשוואה הזאת דוחים: \u0003אימור דאמרינן\u0004 \u0005[אמור שאנו אומרים]\u0006 ומקבלים את העקרון \u0003\"שאני אומר\"\u0004 וסומכים על הנחה זו שהכל היה בדרך היתר,"],["\u0003בתרומה\u0004 שחייבת בזמן הזה \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 שחובת הפרשת תרומה בטלה מן התורה סמוך לחורבן בית ראשון. אולם \u0003בחמץ\u0004 שאיסורו \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]?!\u0006 ומקשים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בדיקת חמץ\u0004 עצמה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 היא? הלא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא!\u0004 שהרי כפי שכבר נאמר \u0003מדאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003בביטול בעלמא סגי ליה\u0004 \u0005[בלבד די לה].\u0006 ולכן כיון שאיננו דנים כאן באיסור חמץ עצמו אלא בחובת בדיקתו שמדברי סופרים, יש מקום להשוותה לדין קופות התרומה.","מקרה אחר: \u0003צבור אחד של חמץ, ולפניו שני בתים בדוקין, ואתא\u0004 \u0005[ובא]\u0006 \u0003עכבר ושקל\u0004 \u0005[ולקח]\u0006 לפנינו, \u0003ולא ידעינן אי להאי על, אי להאי על\u0004 \u0005[ואין אנו יודעים אם ל\u0006בית \u0005זה נכנס, אם ל\u0006בית \u0005זה נכנס]\u0006 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 דומה להלכה של \u0003שני שבילין, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שני שבילין, אחד טמא\u0004 לפי שהיתה טומאה מן המת טמונה תחתיו, \u0003ואחד טהור. והלך באחד מהן,\u0004 ואינו זוכר באיזה מהם הלך. \u0003ועשה\u0004 אחר כך \u0003טהרות,\u0004 כלומר טיפל בידיו בתרומה או קדשים הצריכים טהרה. \u0003ובא חבירו והלך\u0004 בשביל \u0003השני,\u0004 ואף הוא אינו זוכר איזה שביל היה זה, \u0003ועשה\u0004 אף הוא \u0003טהרות.\u0004","\u0003ר' יהודה אומר: אם נשאלו\u0004 לחכמים \u0003זה בפני עצמו וזה בפני עצמו — טהורין,\u0004 שהרי לגבי כל אחד קיים רק ספק שמא נטמא, ומספק מעמידים אותם על חזקת טהרה ומטהרים אותם. ואולם אם באו \u0003שניהן בבת אחת — טמאין,\u0004 שכיון שוודאי לנו שאחד מן השואלים העומדים עתה לפני בית הדין טמא הוא, אף שאיננו יודעים מי הוא, שניהם נחשבים טמאים מספק זה. \u0003ר' יוסי אומר: בין כך ובין כך טמאין.\u0004","\u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן:\u0004 אם באו \u0003בבת אחת\u0004 ממש — \u0003דברי הכל טמאין,\u0004 שאף ר' יהודה מודה בכך. אם באו \u0003בזה אחר זה\u0004 ממש בלא קשר זה לזה — \u0003דברי הכל טהורין. לא נחלקו אלא\u0004 באדם אחד ה\u0003בא להשאל עליו ועל חבירו\u0004 שהלך בשביל האחר. \u0003ר' יוסי מדמי ליה\u0004 \u0005[מדמה אותו\u0006 את המקרה\u0005]\u0006 למקרה שבאו \u0003בבת אחת, ור' יהודה מדמי ליה\u0004 \u0005[מדמה אותו]\u0006 \u0003לזה אחר זה.\u0004","מקרה נוסף: ראה עכבר שנטל חמץ לפנינו ו\u0003ספק על\u0004 \u0005[נכנס]\u0006 העכבר לבית שנבדק כבר, \u0003ספק לא על\u0004 \u0005[נכנס]\u0006 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 דומה להלכה של טומאה ב\u0003בקעה, ובפלוגתא\u0004 \u0005[ובמחלוקתם]\u0006 של \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנכנס לבקעה\u0004 (למישור) \u0003בימות הגשמים,\u0004 שכבר מתחילים הזרעים לצמוח ואין אז רשות לבריות להלך בשדה, שלא יזיקו לזרעים בדריסת רגליהם. דינה של הבקעה כרשות היחיד, וכלל הוא כי ספק טומאה ברשות היחיד — טמא. \u0003ו\u0004היתה \u0003טומאה בשדה פלונית\u0004 הידועה לנו, \u0003ואמר אחד: הלכתי במקום הלז\u0004 באותה בקעה, \u0003ואיני יודע אם נכנסתי באותה שדה ואם לא נכנסתי. ר' אליעזר מטהר, וחכמים מטמאין.\u0004","\u0003שהיה ר' אליעזר אומר: ספק ביאה — טהור\u0004 שאם ספק בידו אם נכנס למקום הטומאה — הריהו טהור, אבל \u0003ספק מגע טומאה\u0004 — הרי זה \u0003טמא,\u0004 ולענין זה נקבע הכלל שספק טומאה ברשות היחיד טמא. ואילו חכמים אומרים שאין לחלק בין ספק לספק, והריהו טמא מספק. ויש להשוות דבר זה לגבי בדיקת חמץ כשלא ברור אם הוכנס חמץ לבית.","מקרה נוסף: אם \u0003על\u0004 \u0005[נכנס]\u0006 העכבר לפנינו למקום וחמץ בפיו, \u0003ובדק\u0004 אדם אחריו \u0003ולא אשכח\u0004 \u0005[ולא מצא]\u0006 את החמץ — הרי זו כעין \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003היה ר' מאיר אומר: כל דבר שבחזקת טומאה,\u0004 שמוחזק בידינו שיש טומאה טמונה במקום מסויים. וחפרו באותו מקום, ולא מצאו דבר. בכל זאת \u0003לעולם הוא\u0004 נשאר \u0003בטומאתו, עד שיודע לך הטומאה היכן היא.\u0004 ואף אם לא מצא, חוששים אנו שמא לא חפש כהוגן.","\u0003וחכמים אומרים\u0004 בענין זה: \u0003בודק\u0004 והולך \u0003עד שמגיע לסלע,\u0004 שודאי אין תחתיו טומאה, \u0003או לקרקע בתולה\u0004 שלא עובדה מעולם. ואם לא מצא, משמע שאין להחזיק עוד טומאה שם, וכן לענין חמץ.","מקרה נוסף: אם \u0003על\u0004 \u0005[נכנס]\u0006 העכבר לפנינו וחמץ בפיו, \u0003ובדק\u0004 אדם אחריו \u0003ואשכח\u0004 \u0005[ומצא]\u0006 פירור חמץ, ויש להסתפק אם זהו הפירור שהיה בפי העכבר — הרי זה דומה ל\u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003רבי ורבן שמעון בן גמליאל;\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שדה שנאבד בה קבר\u0004 ויודעים שהיה קבר בשדה אבל נשכח מקומו — \u0003הנכנס לתוכה טמא,\u0004 שמא במקום שדרך שם היה הקבר. \u0003נמצא בה קבר\u0004 לאחר זמן וצוין — \u0003הנכנס לתוכה\u0004 בשאר מקומות \u0003טהור, שאני אומר: קבר שאבד\u0004 קודם \u0003הוא קבר שנמצא\u0004 עכשיו, וכל השאר — טהור, אלו \u0003דברי רבי.\u0004 ו\u0003רבן שמעון בן גמליאל אומר: תיבדק כל השדה כולה\u0004 שמא הקבר שנמצא עתה אינו זה שאבד קודם, ועדיין חשש טומאה במקום, וכן לענין חמץ.","מקרה אחר: \u0003הניח תשע\u0004 פירורים של חמץ \u0003ומצא עשר,\u0004 שברור לנו שעכברים גררו והחביאו פירור נוסף, אחד לפחות — הרי זה דומה ל\u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003רבי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הניח מנה\u0004 (מאה דינרים) מכספי מעשר שני, \u0003ומצא מאתים\u0004 שברור לנו לפחות שבא מישהו לכאן והניח באותו מקום מנה נוסף, ואיננו יודעים מה טיבו, אומרים אנו כי \u0003חולין ומעשר שני מעורבין זה בזה\u0004 — שמן הסתם מנה נוסף מנה של חולין הוא אף שאין ידיעה איזהו של חולין ואיזה של מעשר, אלו \u0003דברי רבי.\u0004","\u0003וחכמים אומרים: הכל חולין.\u0004 שכיון שברור שהיה שם אדם אחר, שמא לקח אותו אדם את המנה והניח מאתים אחרים, ואין למאתים שנמצאו כל קשר עם המנה שאבד. ואף לענין חמץ יש לומר כי כיון שברור שעכברים היו במקום, שמא גררו העכברים את הפירורים שהיו למקומות אחרים באותו בית והביאו עשרה פירורים ממקום אחר, וצריך כל הבית בדיקה שנית.","מקרה נוסף: \u0003הניח עשר ומצא תשע — היינו סיפא\u0004 \u0005[הרי זו סופה]\u0006 של אותה ברייתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הניח מאתים ומצא מנה\u0004 — הרי \u0003מנה מונח,\u0004 כלומר מנה אחד שהיה שם מן השנים נשאר במקומו, \u0003ומנה\u0004 אחר מן המאתיים \u0003מוטל\u0004 ומצוי במקום אחר. אלו \u0003דברי רבי.\u0004","\u0003וחכמים אומרים\u0004 לשיטתם: \u0003הכל חולין,\u0004 שיש לומר שהלוקח לקח את הכל והמנה שנמצא אחר כך — מנה אחר הוא, והרי הוא כספי חולין. וכן לענין חמץ שנוסף או נגרע מן הפירורים הידועים."],["מקרה נוסף: \u0003הניח חמץ בזוית זו ומצא\u0004 אותו \u0003בזוית אחרת\u0004 — הרי זה כענין \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003קרדום שאבד בבית\u0004 ואין יודעים כיצד אבד — \u0003הבית טמא. שאני אומר: אדם טמא נכנס לשם ונטלו\u0004 לקרדום, ותוך כדי כך נגע בשאר חפצים, וכולם טמאים מספק. \u0003רבן שמעון בן גמליאל אומר: הבית טהור, שאני אומר: השאילו לאחר ושכח, או שנטלו\u0004 הוא עצמו \u0003מזוית זו והניח בזוית האחרת ושכח.\u0004","על דברי רבן שמעון בן גמליאל תוהים: \u0003זוית מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמה]?\u0006 שהרי כאן מדובר על קרדום שאבד ולא על קרדום שנמצא בזוית אחרת, ונמצא שאין הדברים דומים זה לזה!","ומשיבים: אכן \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003קרדום שאבד בבית — הבית טמא, שאני אומר: אדם טמא נכנס לשם ונטלו. או שהניחו\u0004 בעל הבית \u0003בזוית זו ומצאו\u0004 לאחר מכן \u0003בזוית אחרת — הבית טמא, שאני אומר: אדם טמא נכנס לשם ונטלו מזוית זו והניחו בזוית אחרת. רבן שמעון בן גמליאל אומר: הבית טהור, שאני אומר: השאילו לאחר ושכח, או ש\u0004הוא עצמו \u0003נטלו מזוית זו והניח בזוית זו ושכח.\u0004 ולפי העמדת הדברים באופן זה נמצאה השאלה בענין החמץ מקבילה למחלוקת רבן שמעון בן גמליאל וחכמים.","\u0003אמר רבא: עכבר נכנס\u0004 לבית, וראה אדם ש\u0003ככר\u0004 חמץ \u0003בפיו\u0004 של העכבר, \u0003ונכנס אחריו ומצא פירורין — צריך בדיקה\u0004 נוספת אחר הככר, \u0003מפני שאין דרכו של עכבר לפרר,\u0004 ולכן אין אומרים שזהו פירור מן הככר שהכניס העכבר ואכלו. \u0003ואמר רבא:\u0004 ראה \u0003תינוק נכנס וככר בידו, ונכנס אחריו ומצא פירורין — אין צריך בדיקה\u0004 נוספת היכן הככר, \u0003מפני שדרכו של תינוק לפרר,\u0004 ומן הסתם מן הככר הם הפירורים. דברים אלה היו ברורים לרבא.","אולם \u0003בעי רבא:\u0004 ראה \u0003עכבר נכנס וככר בפיו, ועכבר יוצא וככר בפיו, מהו\u0004 \u0005[מה יהא\u0006 הדין\u0005]\u0006 אז? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 במקרה זה: \u0003היינו האי דעל, והיינו האי דנפק\u0004 \u0005[זהו זה שנכנס, וזהו זה שיצא],\u0006 כלומר אותו עכבר שנכנס עם הככר הוא זה שיצא עימה, ואין עוד חמץ בבית. \u0003או דילמא, אחרינא\u0004 \u0005[שמא, אחר]\u0006 \u0003הוא.\u0004","ו\u0003אם תמצא לומר\u0004 אם אמנם תקבל את המסקנה ש\u0003היינו האי דעל והיינו האי דנפק\u0004 \u0005[זהו זה שנכנס, וזהו זה שיצא],\u0006 נעמיד את השאלה במצב אחר: אם ראה \u0003עכבר לבן נכנס וככר בפיו, ועכבר שחור יוצא וככר בפיו מהו? האי\u0004 \u0005[זה]\u0006 \u0003ודאי\u0004 עכבר \u0003אחרינא\u0004 \u0005[אחר]\u0006 \u0003הוא, או דילמא ארמויי ארמיה מיניה\u0004 \u0005[שמא נטלו והשליכו ממנו]?\u0006 שנטל העכבר השחור מן העכבר הלבן את ככרו.","\u0003ואם תמצא לומר\u0004 ותגיע למסקנה כי \u0003עכברים לא שקלי מהדדי\u0004 \u0005[נוטלים זה מזה],\u0006 שאין עכבר אחד גדול וחזק כל כך מחביריו. אם כן מה יהא הדין אם ראה \u0003עכבר נכנס וככר בפיו, וחולדה יוצאה וככר בפיה מהו?\u0004 האם יש לומר ש\u0003חולדה ודאי מעכבר שקלתיה\u0004 \u0005[לקחתו],\u0006 שהיא גדולה ממנו, ולוקחת מן העכבר. \u0003או דילמא, אחרינא\u0004 \u0005[שמא, אחר]\u0006 \u0003הוא.\u0004 והטעם בדבר ש\u0003אם איתא\u0004 \u0005[אמנם]\u0006 ש\u0003מעכבר שקלתיה\u0004 \u0005[לקחתו] —\u0006 \u0003עכבר בפיה הוה משתכח\u0004 \u0005[היה נמצא].\u0006 שהרי מן הסתם היתה החולדה חוטפת לא רק את הככר אלא גם את העכבר עצמו.","\u0003ואם תמצא לומר\u0004 ותקבל את ההנחה ש\u0003אם איתא\u0004 \u0005[אמנם]\u0006 ש\u0003מעכבר שקלתיה\u0004 \u0005[לקחתו],\u0006 \u0003עכבר בפיה הוה משתכח\u0004 \u0005[היה נמצא],\u0006 אם ראה \u0003עכבר נכנס וככר בפיו, וחולדה יוצאה וככר ועכבר בפי חולדה מהו? הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי איהו הוא\u0004 \u0005[זה הוא],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 אפשר להטיל עדיין ספק בכך: \u0003אם איתא דאיהו ניהו\u0004 \u0005[אמנם שזה הוא]\u0006 אותו עכבר — ה\u0003ככר, בפי עכבר משתכח הוה בעי אישתכוחי\u0004 \u0005[היה צריך להמצא],\u0006 ולא בפי החולדה, וככר אחר הוא זה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 אפשר לומר \u0003משום ביעתותא\u0004 \u0005[פחד]\u0006 \u0003הוא נפל\u0004 הככר מפי העכבר, \u0003ושקלתיה\u0004 \u0005[ונטלתו\u0006 החולדה\u0005]\u0006 לחוד. שאלות אלו לא נמצא להן מענה מסויים, ולכן הושארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה אחרת: היתה \u0003ככר בשמי קורה\u0004 כלומר על גבי קורה שבתקרת הבית. האם \u0003צריך\u0004 לטפס ב\u0003סולם\u0004 כדי \u0003להורידה או אין צריך? מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כולי האי\u0004 \u0005[כל כך]\u0006 \u0003לא אטרחוהו רבנן\u0004 \u0005[הטריחוהו חכמים]\u0006 בבדיקה, \u0003כיון דלא נחית מנפשיה\u0004 \u0005[יורדת\u0006 הככר \u0005מעצמה] —\u0006 \u0003לא אתי למיכלה\u0004 \u0005[יבוא לאוכלה],\u0006 ויכול להשאירה שם. \u0003או דילמא, זימנין דנפל ואתי למיכלה\u0004 \u0005[שמא\u0006 אמור\u0005: פעמים\u0006 עשויה \u0005שתיפול ויבוא לאוכלה],\u0006 שהרי דבר הנמצא בגובה עשוי ליפול.","\u0003ואם תמצי לומר\u0004 כי \u0003זימנין דנפל ואתי למיכלה\u0004 \u0005[פעמים שנופלת\u0006 הככר \u0005ויבוא לאוכלה]\u0006 אם היתה ה\u0003ככר בבור, צריך סולם להעלותה או אין צריך?\u0004 וצדדי השאלה; \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי\u0004 ש\u0003לא עבידא דסלקא מנפשה\u0004 \u0005[עשויה שתעלה\u0006 הככר \u0005מעצמה]\u0006 ויכול להשאירה במקומה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 תאמר שעדיין יש חשש: \u0003זימנין דנחית למעבד צורכיה, ואתי למיכליה\u0004 \u0005[פעמים ש\u0006הוא \u0005יורד\u0006 לבור \u0005לעשות\u0006 איזה מ\u0005צרכיו\u0006 בו, \u0005ויבוא לאוכלה].\u0006","ו\u0003אם תמצא לומר: זימנין דנחית לצורכיה ואתי למיכלה\u0004 \u0005[פעמים שהוא יורד לצרכיו ויבוא לאוכלה],\u0006 אם היה \u0003ככר בפי נחש\u0004 האם \u0003צריך\u0004 להביא \u0003חבר,\u0004 כלומר אדם היודע לטפל בנחשים, \u0003להוציא\u0004 את הככר מפי הנחש \u0003או אין צריך?\u0004","וצדדי השאלה: \u0003בגופיה אטרחוהו רבנן\u0004 \u0005[בגופו הטריחוהו חכמים]\u0006 שיבדוק ככל האפשר, אולם \u0003בממוניה\u0004 \u0005[בממונו]\u0006 \u0003לא אטרחוהו רבנן\u0004 \u0005[הטריחוהו חכמים],\u0006 ואינו חייב להוציא ממונו כדי לבער את החמץ. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה],\u0006 ומחובתו לבער את החמץ מכל מקום שימצאנו בכל דרך שהיא. אף סדרת שאלות זו לא נמצאה לה תשובה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה.","\u0003ר' יהודה אומר: בודקין\u0004 את החמץ \u0003אור\u0004 ל\u0003ארבעה עשר\u0004 בניסן, \u0003ובארבעה עשר שחרית, ובשעת הביעור. וחכמים אומרים:\u0004 לא כך, אלא \u0003לא בדק אור\u0004 ל\u0003ארבעה עשר, יבדוק בארבעה עשר\u0004 עצמו.","אף אם \u0003לא בדק בארבעה עשר — יבדוק בתוך המועד\u0004 בפסח (תוספות). ואם \u0003לא בדק בתוך המועד — יבדוק לאחר המועד,\u0004 שהרי החמץ הוא חמץ שעבר עליו הפסח ואסור בהנאה וצריך לבערו. ובכלל אמרו: \u0003ומה שמשייר\u0004 מן החמץ לצורכו לאחר הבדיקה, \u0003יניחנו בצינעא\u0004 במקום שאינו עלול להינטל משם, \u0003כדי שלא יהא צריך בדיקה\u0004 נוספת \u0003אחריו\u0004 אם לא ימצאנו במקומו.","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שמצריך שלוש בדיקות? ואומרים: \u0003רב חסדא ורבה בר רב הונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שהדבר הוא \u0003כנגד שלש השבתות\u0004 חמץ שנאמרו \u0003בתורה.\u0004 כיצד, \"מצות יאכל את שבעת הימים \u0003ולא יראה לך חמץ ולא יראה לך שאר\u0004 בכל גבלך\" (שמות יג, ז), ופסוק נוסף \u0003\"שבעת ימים שאר לא ימצא בבתיכם\"\u0004 (שמות יב, יט), ופסוק נוסף \u0003\"\u0004שבעת ימים מצות תאכלו \u0003אך ביום הראשון תשביתו שאר מבתיכם\"\u0004 (שמות יב, טו).","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב יוסף\u0004 ורוצה להוכיח כי אף ר' יהודה לא נתכוון להצריך שלוש בדיקות חמץ אלא רק קבע זמנים לבדיקה. ששנויה ברייתא, \u0003ר' יהודה אומר: כל שלא בדק בשלשה פרקים הללו — שוב אינו בודק, אלמא\u0004 \u0005[מכאן]\u0006 מדברים אלה של ר' יהודה נלמד כי לא בשאלה אם בודקים שלוש פעמים נחלקו אלא \u0003במכאן ואילך\u0004 בשאלה אם אפשר לבדוק לאחר שעברו תאריכים אלו והלאה \u0003הוא דפליגי\u0004 \u0005[שנחלקו],\u0006 שחכמים אומרים שממשיכים לבדוק אף לאחר שעת הביעור, ור' יהודה אינו מודה בכך.","\u0003מר זוטרא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את דברי רב יוסף: \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף, ר' יהודה אומר: כל שלא בדק באחד משלשה פרקים הללו — שוב אינו בודק, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003בשוב אינו בודק הוא דפליגי\u0004 \u0005[שנחלקו].\u0006","\u0003אלא\u0004 יש לחזור מן ההסבר הקודם ולומר כי \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003אם לא בדק קאמר\u0004 \u0005[אמר],\u0006 שאף הוא לא הצריך שלוש בדיקות, וכוונתו היתה שאם לא בדק את החמץ בזמן בדיקה ראשון יבדקנו בזמן שני, ולא יותר משלושה אלה,","\u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006בעיה \u0005זו נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: מקמי איסורא\u0004 \u0005[לפני\u0006 זמן \u0005האיסור] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003בתר איסורא\u0004 \u0005[לאחר\u0006 זמן \u0005האיסור] —\u0006 \u0003לא\u0004 יבדוק, \u0003גזירה דילמא אתי למיכל מיניה\u0004 \u0005[שמא יבוא לאכול ממנו]\u0006 בתוך כדי בדיקה, ולכן מוטב שלא יבדוק ולא יבוא להכשל באיסור זה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סוברים]:\u0006 \u0003לא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 שמא יבוא לאכול, ולכן יכול לבדוק אף לאחר שנכנס זמן איסורו.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003גזר ר' יהודה\u0004 כיוצא בזה \u0003דילמא אתי למיכל מיניה\u0004 \u0005[שמא יבוא לאכול ממנו]\u0006 מן הדבר שעוסק בו? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אף על פי שאסור מן התורה לאכול מן התבואה החדשה לפני שקרב קרבן העומר, מכל מקום שנינו: \u0003משקרב העומר יוצאין ומוצאין שוקי ירושלים שהם מלאים קמח וקלי\u0004 (מאכל עשוי משבולים שלא נגמר בישולן ונצלו בתנור) מן התבואה החדשה, ובודאי שנקצרה תבואה זו והתעסקו בה עוד קודם זמן היתרה."],["ודבר זה \u0003שלא ברצון חכמים הן עושין,\u0004 אלו \u0003דברי ר' מאיר,\u0004 שיש לחשוש שמא מתוך שמתעסקים בה יבוא לאכול מן התבואה לפני זמן היתרה. \u0003ר' יהודה אומר: ברצון חכמים היו עושין\u0004 את הדבר, ולא גזרו חכמים בזה. משמע מכאן כי \u0003לא קא גזר\u0004 \u0005[היה גוזר]\u0006 \u0003ר' יהודה דילמא אתי למיכל מיניה\u0004 \u0005[שמא יבוא לאכול ממנה].\u0006 ומדוע בחמץ גוזר הוא? \u0003אמר רבא:\u0004 אפשר לדחות את הקושיה: \u0003שאני\u0004 \u0005[שונה]\u0006 איסור היבול ה\u0003חדש\u0004 שלפני העומר, \u0003מתוך שלא התרת לו\u0004 לקצור כדרכו לפני העומר \u0003אלא על ידי קטוף\u0004 בידיים בלבד, שאסרו חכמים קצירה כדרכה לפני העומר, \u0003הוא זכור\u0004 שיש איסור בדבר ולא יבוא לאכול ממנו, מה שאין כן בחמץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: תינח\u0004 \u0005[נניח]\u0006 שהבנו את שיטת ר' יהודה \u0003בשעת קטיפה\u0004 שעושה בשינוי, ואולם \u0003טחינה והרקדה\u0004 (ניפוי הקמח) \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי מלאכות אלה הוא עושה כדרכן, ומדוע אין ר' יהודה גוזר שמא יבוא לאכול? ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי אף \u0003טחינה\u0004 עושה הוא בשינוי, שטוחן לפני העומר \u0003ברחיא דיד\u0004 \u0005[ברחיים של יד],\u0006 ולא כרגיל ברחיים המונעים על ידי בהמה או כוח המים, וכן \u0003הרקדה\u0004 עושים לא כרגיל בתוך הנפה אלא \u0003על גבי נפה,\u0004 ומשום שעושים שינוי אין לחשוש שיבואו להכשל באכילת איסור.","ומקשים עוד: \u0003אלא הא דתנן\u0004 \u0005[\u0006דבר \u0005זה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003קוצרין בית השלחים\u0004 (מקומות המושקים במים) \u0003ו\u0004שדות \u0003שבעמקים,\u0004 שזמן הבשלתם קודם הרבה לזמן העומר, \u0003אבל לא גודשין\u0004 את התבואה. \u0003ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו\u0005]\u0006 הלכה זו \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ולפי הסבר זה \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 שהרי נאמר שתבואה זו קוצרים — משמע קוצרים כדרכה ולא על ידי קיטוף!","\u0003אלא אמר אביי:\u0004 לא זהו טעם ההבדל, ויש להסביר באופן אחר. תבואה מן היבול ה\u0003חדש —\u0004 הריהו \u0003בדיל מיניה\u0004 \u0005[פורש ממנה]\u0006 שהרי אינו רשאי לאוכלה כל הזמן עד לעומר, ואילו \u0003חמץ — לא בדיל מיניה\u0004 \u0005[איננו פורש ממנו]\u0006 כל השנה כולה, ולכן עשוי לשכוח ולאכול ממנו.","\u0003אמר רבא:\u0004 וכי מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה קשיא\u0004 \u0005[קשה],\u0006 \u0003דרבנן אדרבנן\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים]\u0006 \u0003לא קשיא\u0004 \u0005[קשה]?\u0006 ויש צורך לתרץ גם את שיטת חכמים שבחדש הם גוזרים ואילו לענין בדיקת חמץ אינם גוזרים.","וכך יש לתרץ: שמדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כדשנינן\u0004 \u0005[כפי שתרצנו].\u0006 \u0003דרבנן אדרבנן נמי לא קשיא\u0004 \u0005[\u0006מדברי \u0005חכמים על\u0006 דברי \u0005חכמים גם כן אינו קשה]\u0006 שלדעתם בבדיקת חמץ אין מקום לגזור משום ש\u0003הוא עצמו מחזר עליו לשורפו, מיכל קאכיל מיניה\u0004 \u0005[יבוא לאכול ממנו]?!\u0006 מה שאין כן בחדש, שכיון שהוא טוחנו ומרקידו ומתקנו לאכילה, חוששים שמא מתוך כך יבוא לאוכלו.","\u0003רב אשי אמר:\u0004 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[קשה]\u0006 ואפשר לתרץ את הסתירה באופן אחר: כי באותה משנה \u0003\"קמח וקלי\" תנן\u0004 \u0005[שנינו],\u0006 ואותם מותר להביא קודם לעומר, שכיון שאי אפשר לאוכלם כמות שהם, ממילא אין לחשוש.","ודוחים: \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של \u0003רב אשי בדותא\u0004 \u0005[הבאי,\u0006 דבר שאינו מבוסס\u0005]\u0006 \u0003היא,\u0004 כי אפשר לדחות: \u0003התינח\u0004 \u0005[נניח]\u0006 \u0003מקלי ואילך\u0004 נקבל תירוץ זה שאת הקמח או הקלי עצמם אין אנשים אוכלים, ואולם \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003עד קלי מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 הלוא עד שנעשו גרעיני החיטה קלי יש זמן שאפשר לאכול מן המלילות והקליות שהן ראויות לאכילה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהוא מבחין בדבר משום שאינן נלקטות אלא \u0003על ידי קיטוף כ\u0004דברי \u0003רבא,\u0004 ואולם כיצד יתרץ מה שהקשינו על רבא עצמו \u0003קוצרין בית השלחים ושבעמקים\u0004 ומשמע כדרכן, \u0003ואוקימנא\u0004 \u0005[והעמדנו\u0006 את הדבר\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ואם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003אלא\u0004 יש לדחות את ההסבר ולומר כי הלכה זו של \u0003רב אשי בדותא\u0004 \u0005[הבאי]\u0006 \u0003היא\u0004\u0005.\u0006","מסקנת הדברים עד כה היתה כי ר' יהודה מחלק בין דברים שאנשים בדלים מהם, שאינו גוזר שמא יבואו לאוכלם, ודברים שאין בדלים מהם. ושואלים: \u0003וכל היכא\u0004 \u0005[מקום]\u0006 ש\u0003לא בדיל מיניה, מי\u0004 \u0005[נבדל ממנו, האם]\u0006 \u0003גזר ר' יהודה\u0004 שמא יבוא לאכול?","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003לא יקוב אדם שפופרת של ביצה וימלאנה שמן ויתננה בצד הנר בשביל שתהא מנטפת\u0004 שמן אל תוך הנר, ובכך יארך זמן בערתו. \u0003ואפילו היא,\u0004 אותה שפופרת, של \u0003חרס,\u0004 שאנשים מואסים לשתות ממנה. שחוששים שמא ישכח ויקח את השפופרת וישתמש בשמנה לצורך אחר ונמצא מכבה בשבת.","\u0003ור' יהודה מתיר,\u0004 שאינו חושש לנטילת השפופרת. הרי שאף בדבר שאין בדלים ממנו, כגון שמן, אין ר' יהודה גוזר! ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003משום חומרא\u0004 של \u0003שבת מבדל בדילי\u0004 \u0005[בדלים]\u0006 אנשים ונזהרים שלא לנגוע בנר ובסמוך אליו.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מענין הלכה זו של \u0003שבת\u0004 על הלכה אחרת של \u0003שבת, דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבל דלי שנפסק\u0004 (נקרע) וצריך לדלות מן הבאר, \u0003לא יהא קושרו,\u0004 כיון שעשיית קשר היא מלאכה האסורה בשבת מן התורה, \u0003אלא עונבו.\u0004 ואילו \u0003ר' יהודה אומר: כורך עליו פונדא\u0004 \u0005[חגורה כפולה]\u0006 \u0003או פסקיא\u0004 \u0005[חגורה רחבה],\u0006 \u0003ובלבד שלא יענבנו,\u0004 שמא יבוא לקושרו.","והרי \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה,\u0004 שכאן הוא גוזר שמא יבוא לקשור. \u0003קשיא דרבנן אדרבנן\u0004 \u0005[קשה מדברי חכמים על דברי חכמים],\u0006 שבשפופרת שמן אסרו וכאן התירו!","ומתרצים: \u0003דרבנן אדרבנן לא קשיא\u0004 \u0005[מדברי חכמים על דברי חכמים אינו קשה]\u0006 \u0003שמן בשמן — מיחלף\u0004 \u0005[מתחלף],\u0006 שכיון שמותר שימוש בשמן בכלל יבוא אף להשתמש בשמן שבשפופרת זו. ואילו \u0003עניבה בקשירה\u0004 שאינן דומות זו לזו — \u0003לא מיחלף\u0004 \u0005[מתחלף]\u0006 ואין לדעתם מקום לגזור.","ואף מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה לא קשיא\u0004 \u0005[קשה],\u0006 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה לאו\u0004 \u0005[לא]\u0006 \u0003משום\u0004 ש\u0003גזר\u0004 איסור על \u0003עניבה אטו\u0004 \u0005[בגלל,\u0006 משום\u0005]\u0006 דמיונה למלאכת \u0003קשירה, אלא\u0004 טעם יסודי יותר, \u0003משום דקסבר\u0004 \u0005[שסבור]\u0006 ר' \u0003יהודה: עניבה גופה\u0004 \u0005[עצמה]\u0006 \u0003קשירה היא,\u0004 שלדעתו אף עשיית עניבה כלולה בתוך האיסור לעשות קשר בשבת.","\u0003ורמי רבנן אדרבנן\u0004 \u0005[ומשליכים,\u0006 מראים סתירה \u0005מדברי חכמים על דברי חכמים]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003קושרין דלי בפסקיא\u0004 \u0005[חגורה עבה]\u0006 כדי שאפשר יהא לדלות מן הבאר, \u0003אבל לא בחבל, ור' יהודה מתיר.\u0004 לפני שבאים לדון בדברים יש להעיר על תמיהה בעצם לשון המשנה; אותו חבל שדובר בו \u0003חבל דמאי\u0004 \u0005[של מה]\u0006 איזה סוג של חבל הוא? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003חבל דעלמא\u0004 \u0005[סתם],\u0006 אזי יש לתמוה \u0003\"ור' יהודה מתיר\"? קשר של קיימא\u0004 \u0005[הוא]\u0006 \u0003הוא,\u0004 שב\u0003ודאי אתי לבטולי\u0004 \u0005[יבוא לבטל]\u0006 את החבל לדלי בקשירתו אליו, ונמצא שעשו קשר של קיימא שהוא מלאכה האסורה מן התורה!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן בחבל \u0003דגרדי\u0004 \u0005[של אורג],\u0006 שהוא משתמש בו למלאכתו. שחבל כזה ודאי לא ישאירו אותו קשור בדלי, ואינו בטל לדלי.","ואולם \u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 ב\u0003חבל דגרדי אטו\u0004 \u0005[של אורג משום]\u0006 \u0003חבל דעלמא\u0004 \u0005[סתם],\u0006 וכיצד יתכן שבדבר זה גזרו איסור, ובכל זאת לא גזרו על עניבה משום דמיונה לקשירה? ודוחים: \u0003אין\u0004 \u0005[כן]\u0006 יתכן הדבר, כי \u0003חבל בחבל — מיחלף\u0004 \u0005[מתחלף]\u0006 וטועים אנשים בכך ויבואו לקשר בחבל אחר, אבל \u0003עניבה בקשירה לא מיחלפא\u0004 \u0005[מתחלפת]\u0006 לטעות.","ושוב שואלים: \u0003וכל היכא דבדיל מיניה\u0004 \u0005[מקום ש\u0006הוא \u0005בדל ממנו\u0006 מן הדבר\u0005]\u0006 \u0003לא גזר ר' יהודה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בכור\u0004 בהמה טהורה \u0003שאחזו דם\u0004 וחלה, ואין לו רפואה אלא שיקיזו את דמו, ואולם כיון שהבכור קודש הוא אסור להטיל בו מום, ואם כן מה יעשו בו? אמרו: \u0003אפילו הוא מת\u0004 מתוך המחלה — \u0003אין מקיזין לו דם\u0004 כלל, אלו \u0003דברי ר' יהודה.\u0004","\u0003וחכמים אומרים: יקיז\u0004 דמו, \u0003ובלבד שלא יטיל בו מום\u0004 כלומר שיקיז את הדם במקום ובאופן כזה שלא יגרום הדבר למום בבכור. משמע מכאן שר' יהודה גוזר בבכור אף שכל שימוש בבכור אסור והכל בדלים ממנו. ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 בבכור, \u0003מתוך שאדם בהול\u0004 ולהוט"],["\u0003על ממונו\u0004 שהכהן השומר על הבכור רוצה שלא ימות, שהרי אז אינו ראוי לאכילה. \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003אי שרית ליה\u0004 \u0005[אם אתה מתיר לו]\u0006 להקיז \u0003במקום שאין עושין בו מום — אתי למעבד\u0004 \u0005[יבוא לעשות]\u0006 \u0003במקום שעושין בו מום\u0004 ובלבד שיצילו.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]?\u0006 לדעתם \u0003כל שכן,\u0004 שיש להתיר באופן שאינו עושה מום, מחמת נימוק זה עצמו. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא שרית ליה\u0004 \u0005[תתיר לו]\u0006 \u0003כלל — אתי למעבד\u0004 \u0005[יבוא לעשות]\u0006 באיסור, ויטיל בו מום משום רדיפת הממון. ואולם אם תתיר לו לעשות בהיתר — לא יבוא לעבור בכך.","על הסבר זה מקשים: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה אדם בהול על ממונו? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: אין מקדרין\u0004 (מסרקים) במסרק ששיניו דקות את \u0003הבהמה ביום טוב — מפני שהוא עושה\u0004 בה \u0003חבורה\u0004 על ידי כך, וחבלה היא מלאכה אסורה. \u0003אבל מקרצפין\u0004 במסרק ששיניו גסות, ואינו עושה חבורה. \u0003וחכמים אומרים: אין מקדרין, אף אין מקרצפין.\u0004 שאם תתיר לו לקרצף, יבוא אף לקדר.","\u0003ותניא\u0004 \u0005[ושנינו\u0006 בתוספתא\u0005]\u0006 ביאור לכך: \u0003איזהו קידור ואיזהו קרצוף? קידור\u0004 — במסרק שיש לו שיניים \u0003קטנים, ועושים חבורה. קרצוף\u0004 — בשיניים \u0003גדולים, ואין עושין חבורה.\u0004 משמע שר' יהודה אינו גוזר שמא יבוא לקדר אחר שהתירו לו לקרצף, אף שבהול על ממונו!","ודוחים: \u0003התם, דאי שביק ליה\u0004 \u0005[שם,\u0006 בבכור \u0005שאם יניח אותו]\u0006 ולא יעשה בו דבר \u0005—\u0006 \u0003מיית\u0004 \u0005[ימות]\u0006 הבכור, \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003אדם בהול על ממונו.\u0004 ומחמת הבהילות לא יבחין בפרטי איסור והיתר, ויעבור. \u0003הכא, אי שביק ליה\u0004 \u0005[כאן אם יניח אותו]\u0006 את בהמתו ולא יקרצף \u0005—\u0006 \u0003צערא בעלמא\u0004 \u0005[צער בלבד]\u0006 \u0003הוא\u0004 מפני הרמשים העוקצים. ובמקרה זה \u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003אדם בהול על ממונו\u0004 עד כדי כך.","\u0003ו\u0004שואלים: אם כן \u0003ר' יהודה, מאי שנא גבי\u0004 \u0005[\u0006מדוע\u0005, מה שונה אצל]\u0006 \u0003חמץ\u0004 ש\u0003גזר\u0004 שמא יבואו לעשות איסור? \u0003ומאי שנא\u0004 ל\u0003גבי\u0004 \u0005[ומה שונה אצל]\u0006 \u0003קרצוף\u0004 ש\u0003לא גזר?\u0004 ומשיבים: שר' יהודה סבר כי \u0003לחם בלחם — מיחלף\u0004 \u0005[מתחלף],\u0006 ואינו נזכר באותה שעה להבחין בין חמץ למצה. \u0003קידור בקרצוף — לא מיחלף\u0004 \u0005[מתחלף],\u0006 שהרי יש להביא כלי אחר לצורך זה, ואין אדם טועה עד כדי כך.","בזמן אכילתו וביעורו של החמץ בערב פסח נחלקו תנאים. \u0003ר' מאיר אומר: אוכלים\u0004 את החמץ \u0003כל חמש\u0004 (שעה חמישית) של יום ארבעה עשר בניסן, \u0003ושורפין\u0004 מיד לאחר כך — \u0003בתחלת שש. ר' יהודה אומר: אוכלין כל ארבע\u0004 (שעה רביעית) — \u0003ותולין,\u0004 כלומר משאירים את החמץ במקומו בלא לעשות בו דבר \u0003כל חמש\u0004, \u0003ושורפין בתחלת שש.\u0004","\u0003ועוד אמר ר' יהודה: שתי חלות של\u0004 קרבן \u0003תודה\u0004 שהן חמץ שהיו \u0003פסולות\u0004 מפני טעם כלשהו, היו \u0003מונחות\u0004 לסימן \u0003על גב האיצטבא\u0004 שמסביב לבית המקדש. שהיו שם שדרות עמודים ועליהן גג, ועליו הניחו את החלות. \u0003כל זמן ש\u0004החלות \u0003מונחות — כל העם אוכלין\u0004 עדיין חמץ. \u0003ניטלה אחת\u0004 מהן — יודעים שהגיע זמן להיות \u0003תולין,\u0004 כלומר: \u0003לא אוכלין ולא שורפין. ניטלו שתיהן — התחילו כל העם שורפין.\u0004","\u0003רבן גמליאל אומר\u0004 חלוקה אחרת בזמני הביעור: \u0003חולין נאכלין כל ארבע\u0004, \u0003ותרומה\u0004 נאכלת \u0003כל חמש,\u0004 שהרי מצוה לאוכלה, ואסור להביא לידי שריפתה שאף היא קודש, \u0003ושורפין\u0004 כל חמץ שהוא ואפילו תרומה \u0003בתחלת שש.\u0004","הגמרא רוצה להשוות את מחלוקת ר' יהודה ור' מאיר לענין חמץ למחלוקת אחרת שלהם במקום אחר. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 בהלכות עדות: עד \u0003אחד אומר\u0004 ומעיד שהיה הדבר עליו הוא מעיד \u0003בשנים בחדש, ואחד אומר\u0004 שהיה \u0003בשלשה\u0004 בחודש, במקרה כגון זה \u0003עדותם קיימת\u0004 ואינה נפסלת משום סתירה זו שבעדותם,","כי \u0003זה\u0004 אחד מהם \u0003יודע בעבורו של חדש,\u0004 ויודע שעיברו את החודש הקודם והיו בו שלושים יום, ולכן יום זה הוא רק שני בחודש. \u0003וזה אינו יודע בעבורו של חדש\u0004 קודם, וסבור שכבר יום שלישי בחודש הוא.","ואולם אם \u0003אחד אומר בשלשה, ואחד אומר בחמשה — עדותן בטלה,\u0004 משום שאין במה לתלות את הסתירה בדבריהם. וכן אם \u0003אחד אומר\u0004 שאותו מעשה היה \u0003בשתי שעות\u0004 (בשעה השנית) ביום, \u0003ואחד אומר בשלש שעות\u0004 (בשעה השלישית) ביום — \u0003עדותן קיימת\u0004 שהבדל כעין זה יתכן שהוא תוצאה של חוסר דיוק, ואולם אם \u0003אחד אומר בשלש\u0004 שעות \u0003ואחד אומר בחמש — עדותן בטלה,\u0004 אלו \u0003דברי ר' מאיר,\u0004","\u0003ר' יהודה אומר:\u0004 במקרה זה \u0003עדותם קיימת,\u0004 שמא טעה אחד מהם מעט. אם \u0003אחד אומר בחמש ואחד אומר בשבע — עדותן בטלה,\u0004 משום שזוהי סתירה ברורה ואין מקום לטעות בכגון זה, \u0003ש\u0004הרי \u0003ב\u0004שעה \u0003חמש\u0004 של היום \u0003חמה\u0004 עדיין \u0003במזרח, ובשבע חמה\u0004 כבר \u0003במערב,\u0004 ואין אפשרות לטעות בין שעה חמישית ושביעית.","\u0003אמר אביי: כשתמצא לומר\u0004 ותמצה את השיטות, \u0003לדברי ר' מאיר — אין אדם טועה ולא כלום,\u0004 ואנו מניחים שאדם יודע את השעה בדיוק. ואילו \u0003לדברי ר' יהודה — אדם טועה חצי שעה.\u0004 ומפרט את דבריו: \u0003לדברי ר' מאיר אין אדם טועה ולא כלום,\u0004 אלא \u0003מעשה כי הוה\u0004 \u0005[כאשר היה],\u0006 היה זה \u0003במיפק תרתי ומעייל תלת\u0004 \u0005[ביציאת\u0006 שעה \u0005שניה וכניסת\u0006 שעה \u0005שלישית],\u0006 \u0003והא דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003שתים — בסוף שתים\u0004 התכוון, וזה ש\u0003אמר שלש — בתחלת שלש,\u0004 ושניהם דייקו בעדותם.","ואילו \u0003לדברי ר' יהודה אדם טועה חצי שעה, מעשה כי הוה\u0004 \u0005[כאשר היה],\u0006 היה זה \u0003בפלגא דארבע הוה\u0004 \u0005[בחצי של הרביעית\u0006 בשלוש וחצי \u0005היה],\u0006 \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003שלש — בסוף שלש\u0004 התכוון, \u0003וקטעי פלגא דשעתא לקמיה\u0004 \u0005[וטעה חצי שעה לפניו],\u0006 כלומר שהקדים את הזמנים, שהרי הדבר לא היה בשלוש אלא בשלוש וחצי. \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003חמש\u0004 שעות — \u0003בתחלת חמש,\u0004 כלומר לסוף שעה רביעית התכוון, \u0003וקטעי פלגא דשעתא לאחוריה\u0004 \u0005[וחצי שעה לאחוריו],\u0006 שאיחר בעדותו את זמן המאורע, ולכך אפשר לצרף את עדותם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן אחר, \u0003אמר אביי: כשתמצא לומר לדברי ר' מאיר אדם טועה משהו. לדברי ר' יהודה אדם טועה שעה ומשהו.\u0004 ומפרטים: \u0003לדברי רבי מאיר אדם טועה משהו — מעשה כי הוה\u0004 \u0005[כאשר היה]\u0006 \u0003או בסוף שתים הוה\u0004 \u0005[היה]\u0006 \u0003או בתחלת שלש\u0004 היה, \u0003וחד מינייהו\u0004 \u0005[ואחד מהם]\u0006 \u0003טועה משהו. לדברי ר' יהודה: אדם טועה שעה ומשהו\u0004 בלבד, \u0003מעשה כי הוה\u0004 \u0005[כאשר היה]\u0006 — \u0003או בסוף שלש או בתחלת חמש\u0004 היה"],["\u0003וחד מינייהו קטעי\u0004 \u0005[ואחד מהם היה טועה]\u0006 ב\u0003שעה ומשהו.\u0004","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה אמרה לשמעתתא\u0004 \u0005[את השמועה]\u0006 הזו של אביי \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא, אמר\u0004 לו רבא: אין מקום לסברה זו. כי \u0003ומה\u0004 היה \u0003אילו דייקינן בהני סהדי\u0004 \u0005[מדייקים היינו ב\u0006דבריהם של \u0005עדים אלה]\u0006 ושואלים אותם לאיזו שעה ולאיזה חלק מן השעה נתכוונו בדיוק, ומוצאים \u0003דהאי דקאמר\u0004 \u0005[שזה שאמר]\u0006 \u0003שלש\u0004 שעות — על דבר שהיה \u0003בתחלת שלש\u0004 הוא מעיד, \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003חמש — בסוף חמש\u0004 נתכוון, \u0003ו\u0004אם כן, \u0003הויא\u0004 \u0005[והריהי\u0006 איפוא\u0005]\u0006 \u0003עדות מוכחשת\u0004 שהרי יש סתירה בין העדים, \u0003ולא קטלינן\u0004 \u0005[הורגים אנו]\u0006 את הנאשם, \u0003ואנן ניקום ונקטיל מספיקא\u0004 \u0005[ואנחנו נעמוד ונהרוג מספק]?!\u0006 שכיון שלא בררנו את העדות כל צורכה אין רואים זאת כסתירה אלא כטעותם של העדים, \u0003ו\u0004הלוא \u0003רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003אמר\u0004 \u0005:\u0006 \u0003\"ושפטו העדה\" \"והצילו העדה\"\u0004 (במדבר לה, כד-כה) ולמדו מכאן שחובת הדיינים היא לפעול להצלת הנאשם כשם שפועלים לשופטו.","\u0003אלא אמר רבא:\u0004 לא כך יש להבין, אלא \u0003לדברי ר' מאיר אדם טועה\u0004 אפילו \u0003שתי שעות חסר משהו, לדברי ר' יהודה אדם טועה שלש שעות חסר משהו.\u0004 ומפרטים את הדברים: \u0003לדברי ר' מאיר אדם טועה שתי שעות חסר משהו,\u0004 כיצד — \u0003מעשה כי הוה\u0004 \u0005[אשר היה]\u0006 \u0003או בתחלת שתים או בסוף שלש\u0004 היה. \u0003וחד מינייהו קטעי\u0004 \u0005[ואחד מהם טעה]\u0006 \u0003שתי שעות חסר משהו.\u0004 שעשוי שיטעה אדם עד כדי כך.","\u0003לדברי ר' יהודה אדם טועה שלש שעות חסר משהו,\u0004 כיצד — \u0003מעשה כי הוה\u0004 \u0005[אשר היה]\u0006 \u0003או בתחלת שלש\u0004 שעות \u0003או בסוף חמש, וחד מינייהו\u0004 \u0005[ואחד מהם]\u0006 שאמר זמן שונה מחבירו \u0003קטעי\u0004 \u0005[טעה]\u0006 \u0003שלש שעות חסר משהו.\u0004 ולדעתו אף זה בגדר טעות המתקבלת על הדעת.","בהמשך הדברים הקודמים מביאים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003היו בודקין אותו\u0004 את העד \u0003בשבע חקירות: באיזו שבוע\u0004 (באיזו שמיטה, שבע שנים, משבע מחזורי השמיטה בשנות היובל), \u0003באיזו שנה\u0004 משנות השמיטה, \u0003באיזה חדש\u0004 בשנה, \u0003בכמה בחדש, באיזה יום\u0004 בשבוע, \u0003באיזו שעה, באיזה מקום\u0004 היה מעשה. \u0003ו\u0004עוד \u0003תניא\u0004 \u0005[שנינו]\u0006 שם: \u0003מה בין חקירות לבדיקות?\u0004 בתשובות ל\u0003חקירות,\u0004 אם \u0003אמר אחד מהן: איני יודע\u0004 מתי בדיוק או היכן היה הדבר — \u0003עדותן בטילה,\u0004 ואילו לגבי \u0003בדיקות, אפילו שניהם אומרים \"אין אנו יודעים\" — עדותן קיימת,\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בשאלה זו: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונות]\u0006 \u0003חקירות ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונות]\u0006 \u0003בדיקות?\u0004 שאם אינם יודעים לענות על שאלות החקירות, עדותן מתבטלת. ואילו אם אינם יודעים להשיב על שאלות הבדיקות, אין עדותן מתבטלת.","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בתשובה: \u0003חקירות,\u0004 אם \u0003אמר אחד מהן איני יודע עדותן בטילה,\u0004 טעמו של דבר \u0003דהויא\u0004 \u0005[שנעשית]\u0006 \u0003לה עדות שאי\u0004 (שאין) \u0003אתה יכול להזימה,\u0004 שהזמת העד נעשית על ידי שבאים עדים אחרים ואומרים לו: כיצד מעיד אתה על מאורע מסויים, והרי באותו זמן היית עמנו במקום אחר ולא יכולת לראות מאומה. ואולם כאשר העד אומר שאינו יודע מתי אירע הדבר, ממילא אי אפשר להזימו. ועדות שאין אפשרות מתחילה להזימה, גזירת הכתוב היא שלא לקבל אותה.","ואילו \u0003בדיקות\u0004 גם אם אינו זוכר פרטים שונים, מכל מקום \u0003עדות שאתה יכול להזימה היא,\u0004 כי אין הזמה אלא באמירת העדים המזימים \"עימנו הייתם באותו זמן במקום פלוני\", ולא בהכחשת פרט אחר מפרטי העדות.","\u0003ואי אמרת טעי איניש כולי האי\u0004 \u0005[ואם אומר אתה\u0006 ש\u0005טועה אדם כל כך],\u0006 הרי \u0003חקירות\u0004 של \u0003\"איזו שעה\" נמי\u0004 \u0005[גם כן]\u0006 \u0003עדות שאי אתה יכול להזימה היא, דאמרי: \"מטעי קטעינן\"\u0004 \u0005[שאומרים\u0006 העדים: \u0005\"טעינו\"]\u0006 ולא בשעה זו אלא בשעה אחרת היה הדבר, ולכן אין אפשרות להזימם.","ומשיבים: \u0003דיהבינן להו כולי טעותייהו\u0004 \u0005[שנותנים אנו להם\u0006 את \u0005כל\u0006 משך זמן \u0005טעותם],\u0006 כלומר שצריכים המזימים להעיד שהיו העדים עימם במשך זמן ממושך יותר מכפי שאפשר לעדים לטעות. \u0003ל\u0004שיטת \u0003ר' מאיר יהבינן להו\u0004 \u0005[נותנים אנו להם\u0006 לעדים\u0005]\u0006 זמן \u0003מתחילת שעה ראשונה עד סוף חמש,\u0004 שאם העידו שהיה הדבר בשעה שניה או שלישית יש להביא בחשבון טעות של שעתיים ויש להוסיף לזמנים עוד שעתיים לכל צד.","\u0003ובדין\u0004 (וראוי) \u0003הוא דניתיב להו מעיקרא טפי\u0004 \u0005[שניתן להם מתחילה\u0006 זמן \u0005יתר],\u0006 שהרי לשיטה זו טועה אדם שתי שעות חסר משהו, ואם העידו העדים על שעה שניה שמא טעו בשעתיים והיה הדבר שעה לפני הזריחה, \u0003אלא בין יממא לליליא לא טעו אינשי\u0004 \u0005[יום ללילה אין אנשים טועים],\u0006 וכיון שהעדים העידו שהיה המעשה בשעה השלישית ביום, הרי לא ייתכן שטעו והיה זה בשעות הלילה.","\u0003ולר' יהודה יהבינן להו\u0004 \u0005[נותנים אנו להם]\u0006 זמן של ספק \u0003מתחילת שעה ראשונה ועד סוף ששית. ובדין הוא דניתיב להו מעיקרא טפי\u0004 \u0005[שניתן להם מתחילה יותר],\u0006 שהרי לדעתו טעות בזמן יכולה להיות עד שלוש שעות, וצריך היה להיות הבדל גדול יותר."],["\u0003אלא בין יממא לליליא לא טעו אינשי\u0004 \u0005[יום ללילה אין אנשים טועים]\u0006 ואין לחשוש שמא טעו בכך. \u0003ו\u0004כן \u0003בדין הוא דניתיב לקמיה טפי\u0004 \u0005[שניתן לפניהם,\u0006 כלומר לשעות אחר הצהריים\u0005, יותר]\u0006 \u0003אלא\u0004 שאף כאן אין מקום לטעות כיון \u0003שב\u0004שעה \u0003חמש חמה\u0004 עדיין \u0003במזרח, ובשבע חמה במערב.\u0004 ואין אדם טועה בין שעות שלפני ושלאחרי הצהריים.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' מאיר אומר: אוכלין\u0004 חמץ \u0003כל חמש\u0004 שעות של יום ארבעה עשר בניסן, \u0003ושורפין בתחילת שש. ר' יהודה אומר: אוכלין כל ארבע, ותולין\u0004 לא אוכלים ולא שורפים \u0003כל חמש, ושורפין בתחילת שש.\u0004","ומעתה דנים \u0003ל\u0004שיטת \u0003אביי אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' מאיר,\u0004 ש\u0003אמר: אין אדם טועה ולא כלום — ניכול כולה שית\u0004 \u0005[שיאכל כל\u0006 השעה \u0005השישית]\u0006 שהרי מן התורה מותר לו לאכול עד סופה שהוא חצי היום, וגזרו חכמים שלא יאכל כבר מתחילתה כדי שלא יבוא לאכול בטעות לאחריה, ולדבריו הרי אין אדם טועה כלל. \u0003ולהך לישנא נמי\u0004 \u0005[ולפי אותה לשון גם כן]\u0006 ש\u0003אמר: אדם טועה משהו\u0004 אף כאן — \u0003ניכול\u0004 \u0005[שיאכל]\u0006 \u0003עד סוף\u0004 שעה \u0003שית\u0004 \u0005[שש],\u0006 כלומר שיאכל עד לזמן קצר סמוך לסוף השעה השישית.","\u0003ו\u0004ל\u0003אביי אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר: אדם טועה חצי שעה — ניכול\u0004 \u0005[שיאכל]\u0006 \u0003עד פלגא דשית\u0004 \u0005[מחצית\u0006 השעה \u0005השישית]\u0006 \u0003ולהך לישנא נמי דאמרת\u0004 \u0005[וללשון זו גם כן שאומרת]\u0006 \u0003אדם טועה שעה ומשהו\u0004 אם כן \u0003ניכול\u0004 \u0005[שיאכל]\u0006 \u0003עד\u0004 זמן קצר סמוך ל\u0003סוף חמש.\u0004 וכיון שלא פסקו כך משמע שאין הסברים אלה — כמה שעות אדם עשוי לטעות — נכונים, וקשה לאביי.","\u0003אלא אמר אביי:\u0004 יש להבדיל בין הנושאים כי \u0003עדות מסורה לזריזים,\u0004 שהרי אין אדם בא להעיד אלא אם כן דקדק יפה בבדיקת הדבר ולכך אינו טועה כל כך בזמן. ואילו \u0003חמץ\u0004 ואכילתו \u0003לכל מסור,\u0004 ורוב העולם אינו מדקדק דיו בהערכת הזמן, ומשום כך ר' מאיר ור' יהודה מוסיפים כל אחד לשיטתו זמן נוסף, שמא יטעו בכך.","ומקשים: ול\u0003רבא אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' מאיר,\u0004 ש\u0003אמר: אדם טועה שתי שעות חסר משהו\u0004 — אם כן, \u0003מתחילת\u0004 שעה \u0003חמש לא ניכול\u0004 \u0005[יאכל],\u0006 הלוא ייתכן שיטעה בין חמישית ושביעית האסורה מן התורה באכילת חמץ! ומתרצים: מאחר שבשעה \u0003חמש — חמה במזרח, ו\u0004אילו ב\u0003שבע — חמה במערב,\u0004 לכן אין כל מקום לטעות בכך.","ומקשים: \u0003אי הכי, בשית נמי ניכול\u0004 \u0005[אם כך, ב\u0006שעה \u0005שישית גם כן יאכל]\u0006 שהרי קיים היכר אף בין השעה השישית לשביעית בכך שבשעה השישית עדיין לא נוטה השמש למערב כמו בשביעית?! \u0003אמר רב אדא בר אהבה: שית, יומא בקרנתא קאי\u0004 \u0005[\u0006בשעה \u0005שישית, היום,\u0006 השמש\u0005, בפינות היא עומדת]\u0006 ואין הדבר נראה בבירור לעין כל אם נוטה היא למזרח או למערב. ולכן אפשר לטעות בכך.","ושואלים: ול\u0003רבא אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה\u0004 ש\u0003אמר: אדם טועה שלש שעות חסר משהו\u0004 — אם כן, \u0003מתחילת\u0004 שעה \u0003רביעית לא ניכול\u0004 \u0005[יאכל]!\u0006 ומשיבים כי במקרה זה אין מקום לטעות כי הלוא בשעה \u0003חמש — חמה במזרח, ושבע — חמה במערב. וכל שכן\u0004 שאין לטעות בשעה \u0003רביעית,\u0004 שודאי חמה במזרח. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין חוששים לטעות בשעות כשהחמה במזרח או במערב \u0003בחמש נמי ניכול\u0004 \u0005[גם כן יאכל]\u0006 על פי שיטת ר' יהודה וכהסברו של רבא!","\u0003תרגמה\u0004 \u0005[הסבירה]\u0006 \u0003אביי אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003רבא\u0004 שיש לחלק: \u0003עדות מסורה לזריזים\u0004 ואין העד טועה כל כך בשעות, אבל \u0003חמץ לכל מסור,\u0004 ומתוך שרוב האנשים עשויים לטעות, לכן החמירו בו יותר מבדין עדות.","\u0003ורבא אמר: לאו היינו טעמא\u0004 \u0005[אין זה הטעם]\u0006 של \u0003ר' יהודה\u0004 שמוסיף שעה יתירה מחמת חשש לטעות. \u0003אלא ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אין ביעור חמץ אלא שריפה, ו\u0004לכן \u0003יהבו ליה רבנן\u0004 \u0005[נתנו לו חכמים]\u0006 \u0003שעה אחת\u0004 יתירה \u0003ללקוט בה עצים,\u0004 שהרי אינו יכול לבערו אלא בדרך זו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 ממה ששנינו: \u0003אמר ר' יהודה: אימתי\u0004 אמרתי שאין ביעור חמץ אלא שריפה — \u0003שלא בשעת ביעורו\u0004 אלא לפניו, שאז עדיין יש לו שהות לברור לו את הדרך הטובה לביעור ולדאוג לדרכי ביצועה. \u0003אבל בשעת ביעורו\u0004 שאין לו שהות כלל — \u0003השבתתו בכל דבר!\u0004 והרי כאשר הגיעה שעה שביעית, זמן ביעורו הוא ואינו צריך עצים דוקא, ומדוע איפוא הגבילו את זמן ביעורו?","\u0003אלא אמר רבא,\u0004 וחזר בו מדברים שאמר, וביאר באופן אחר: \u0003גזירה משום יום המעונן\u0004 שבו אין רואים את מקומה המדוייק של השמש, ועשויים לטעות. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו בארבע שעות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניכול\u0004 \u0005[יאכל],\u0006 שהרי לשיטת ר' יהודה אדם טועה אף שלוש שעות! \u0003אמר רב פפא:\u0004 שעה \u0003רביעית זמן סעודה לכל היא,\u0004 שכיון שהכל סועדים בה לא יטעו בכך, שהכל אוכלים בשעה זו ושמים לב שהגיעה השעה.","כיון שהוזכרו דברי רב פפא מביאים עוד בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האוכל ב\u0003שעה ראשונה\u0004 — הרי זה \u0003מאכל לודים\u0004 (לודרים) הנאבקים זה בזה בזירה, וצריכים להרבות באכילה. שעה \u0003שניה — מאכל ליסטין\u0004 (גנבים) שכל הלילה עסוקים בגניבה, ולכן ישנים בשעה הראשונה של היום ואוכלים בשניה. \u0003שלישית — מאכל יורשין,\u0004 שכיון שלא יגעו בהשגת פרנסתם ואף אינם זקוקים לעמול כעת, יכולים הם להקדים ולאכול. \u0003רביעית — מאכל פועלים. חמישית — מאכל תלמידי חכמים. ששית — מאכל כל אדם.\u0004","ומקשים: והרי \u0003אמר רב פפא:\u0004 שעה \u0003רביעית — זמן סעודה לכל היא! אלא איפוך\u0004 \u0005[הפוך]\u0006 ואמור כך: שעה \u0003רביעית — מאכל כל אדם, חמישית — מאכל פועלים, ששית מאכל תלמידי חכמים.\u0004","האוכל \u0003מכאן ואילך\u0004 אינו מועיל לו, והריהו \u0003כזורק אבן לחמת\u0004 (נאד), כלומר שאינו מביא כל תועלת בשעה זו. \u0003אמר אביי: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כש\u0003לא טעים מידי בצפרא\u0004 \u0005[טעם דבר בבוקר],\u0006 ואם אוכל בצהרים בלבד אינו מועיל לו. \u0003אבל\u0004 אם \u0003טעים מידי בצפרא\u0004 \u0005[טעם דבר בבוקר] —\u0006 \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 נזק, ויכול הוא לאכול אף בשעה מאוחרת.","\u0003אמר רב אשי: כמחלוקת\u0004 ר' מאיר ור' יהודה \u0003בעדות, כך מחלוקת\u0004 על אותו עקרון \u0003בחמץ.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003היינו הך דאמרינן\u0004 \u0005[\u0006הרי \u0005זה\u0006 מה \u0005שאמרנו\u0006 עד עכשיו\u0005]!\u0006 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 \u0003שינויי דשנינן\u0004 \u0005[תירוצים שתירצנו] —\u0006 \u0003שינויא\u0004 \u0005[תירוץ]\u0006 של ממש \u0003הוא, ולא תימא\u0004 \u0005[תאמר]\u0006 שמחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא,\u0004 ותירצנו תירוצים מדומים בלבד.","\u0003אמר רב שימי בר אשי: לא שנו\u0004 שאין מבטלים עדות בגלל הבדל זמן בין העדויות \u0003אלא\u0004 כשההבדל \u0003בשעות, אבל\u0004 אם עד \u0003אחד אומר קודם הנץ החמה\u0004 היה, \u0003ואחד אומר אחר הנץ החמה\u0004 — ודאי ש\u0003עדותן בטילה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהרי זו סתירה גלויה, שהרי ההבדל ביניהם ניכר לכל ואין אפשרות לטעות בו!","\u0003אלא\u0004 כך יש לומר: עד \u0003אחד אומר קודם הנץ החמה, ואחד אומר בתוך הנץ החמה — עדותן בטילה.\u0004 ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט\u0006 ומובן\u0005]\u0006 שהרי גם דבר זה ניכר לעין! ומשיבים: \u0003מהו דתימא תרוייהו חדא מילתא קאמרי\u0004 \u0005[שתאמר שניהם דבר אחד\u0006 בעצם התכוונו \u0005לומר]\u0006 \u0003והא דקאמר\u0004 \u0005[וזה שאמר]\u0006 אחד מהם"],["\u0003בתוך הנץ החמה — בגילוייא הוה קאי\u0004 \u0005[ב\u0006מקום \u0005מגולה היה עומד]\u0006 \u0003וזהרורי בעלמא\u0004 \u0005[וזהרורים בלבד]\u0006 \u0003הוא דחזא\u0004 \u0005[שראה]\u0006 ונדמה לו שכבר הנצה החמה, אבל באמת לאותו זמן ממש נתכוונו. על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לכך.","\u0003אמר רב נחמן אמר רב: הלכה כר' יהודה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: ונימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 \u0003הלכה כר' מאיר\u0004 שאוכלים כל חמש, שהרי \u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא כוותיה\u0004 \u0005[כשיטתו],\u0006 כלומר שהמשנה שנויה סתם, ומשמע שהיא הלכה פסוקה כשיטתו.","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל שעה שמותר לאכול בעצמו — מאכיל\u0004 לבהמתו, ולכאורה משמע מכאן שאין זמן ביניים שבו אסור לאכול ומותר להאכיל. וכדברי ר' מאיר, שהרי לדברי ר' יהודה הוא עצמו אינו אוכל בשעה חמישית אבל מאכיל לבהמתו!","ודוחים: \u0003ההיא לאו סתמא\u0004 \u0005[אותה\u0006 משנה \u0005אינה סתם]\u0006 כלומר אי אפשר לסמוך עליה, \u0003משום דקשיא\u0004 \u0005[שקשה]\u0006 כאן במלה \u0003\"מותר\",\u0004 שראוי היה לומר \"שעה שאוכל — מאכיל\", ובשל \"מותר\" זה כבר דקדקנו שהמשנה היא כשיטת רבן גמליאל ולא כר' מאיר.","והקשה לו עוד: \u0003ונימא מר\u0004 \u0005[ושיאמר אדוני]\u0006 \u0003הלכה כרבן גמליאל, דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003מכריע,\u0004 כלומר ממוצע בין השיטות החולקות, וכלל הוא בפסק שכאשר יש שיטות קיצוניות ושיטה אחת המכרעת ביניהן, פוסקים הלכה כמותה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבן גמליאל לאו\u0004 \u0005[לא]\u0006 \u0003מכריע הוא, טעם דנפשיה קאמר\u0004 \u0005[של\u0006 שיטת \u0005עצמו אמר].\u0006 כי ר' מאיר ור' יהודה לא נחלקו אלא לענין זמנה של אכילת כל סוג שהוא של חמץ, ולא הזכירו במפורש חילוק כלשהו בין תרומה וחולין. ואילו רבן גמליאל, המחלק בין אכילת תרומה לזמן אכילת חולין, אינו מצרף את שתי השיטות כאחת להכרעה ביניהן, אלא היא שיטה עצמאית משלו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003רב\u0004 ש\u0003אמר\u0004 ופסק הלכה כר' יהודה דעתו \u0003כי האי תנא\u0004 \u0005[כמו תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ארבעה עשר\u0004 בניסן \u0003שחל להיות בשבת,\u0004 שאי אפשר לבער את החמץ בערב פסח — \u0003מבערין את הכל מלפני השבת. ושורפין תרומות טמאות,\u0004 וכן ה\u0003תלויות\u0004 (ספק טמאות, ספק טהורות) ואף \u0003טהורות,\u0004 שהן יותר מכדי צורכו לסעודותיו. \u0003ומשיירין מן הטהורות מזון שתי סעודות\u0004 (סעודת הלילה והבוקר), \u0003כדי לאכול עד ארבע שעות\u0004 ביום השבת, אלו \u0003דברי ר' אלעזר בן יהודה איש ברתותא, שאמר משום\u0004 (משמו של) \u0003ר' יהושע.\u0004","\u0003אמרו לו:\u0004 תרומות \u0003טהורות לא ישרפו שמא ימצאו להן אוכלין\u0004 בתוך יום השבת, ונמצא למפרע ששרף תרומה טהורה שלא לצורך ועבר על דברי תורה. אלא יניחם, ואם יוותרו למחר — יאכילם לכלבים, או יבטלם בליבו. ו\u0003אמר להן: כבר בקשו\u0004 אוכלים לתרומה הטהורה \u0003ולא מצאו,\u0004 שאין בעיר עוד כהנים ומשפחותיהם המותרים באכילת תרומה. \u0003אמרו לו: שמא\u0004 אותם כהנים שמותר להם לאכול מן התרומה באותה שבת מ\u0003חוץ לחומה לנו,\u0004 וביום השבת יכנסו אל תוך העיר ויוכלו לאוכלן?","\u0003אמר להם: לדבריכם\u0004 שאתם מביאים בחשבון אפשרות שאינה מוכחת, \u0003אף\u0004 תרומות \u0003תלויות לא ישרפו — שמא יבא אליהו\u0004 בשבת זו, שהרי יכול הוא לומר בכוח נבואתו שלא נטמאו \u0003ויטהרם. אמרו לו:\u0004 לכך אין לחשוש כי \u0003כבר מובטח להן לישראל שאין אליהו בא לא בערבי שבתות ולא בערבי ימים טובים, מפני הטורח\u0004 שישראל עסוקים בהכנותיהם לשבת וליום טוב. ובודאי לא יבוא לא בערב שבת זו ואף לא בשבת עצמה שהיא ערב פסח.","\u0003אמרו: לא זזו משם עד ש\u0004עמדו החכמים למנין דעות ו\u0003קבעו הלכה כר' אלעזר בן יהודה איש ברתותא שאמר משום ר' יהושע.\u0004","ונמשיך לעניננו: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 שפסקו הלכה כמותו \u0003אפילו\u0004 לענין \u0003לאכול?\u0004 שבתוך דבריו אמר שמותר לאכול את החמץ עד ארבע שעות ביום, וכדברי ר' יהודה? \u0003אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא,\u0004 אפשר לדחות ולומר כי הפסק היה לענין \u0003לבער\u0004 בלבד, שהסכימו רק לדבריו שמותר לבער בערב שבת גם את התרומות הטהורות שאין להן אוכלים.","ומעירים: \u0003ואף רבי סבר להא\u0004 \u0005[לזו]\u0006 השיטה של \u0003רב נחמן\u0004 ופסק הלכה כר' יהודה. ש\u0003אמר רבין בר רב אדא: מעשה באדם אחד שהפקיד דיסקיא\u0004 (שק כפול שטוענים על החמור) \u0003מלאה חמץ אצל יוחנן חקוקאה, ונקבוה עכברים\u0004 את החבילה הזו \u0003והיה חמץ מבצבץ ויוצא, ובא לפני רבי\u0004 בערב פסח לשאול מה לעשות. \u0003שעה ראשונה\u0004 ביום \u0003אמר לו: המתן,\u0004 שמא יחזור המפקיד ויטול מידיך ויאכלנו. \u0003שניה, אמר לו: המתן, שלישית — אמר לו: המתן, רביעית — אמר לו: המתן, חמישית\u0004 שראה שאין האיש בא — \u0003אמר לו: צא ומוכרה בשוק.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 שימכור את החמץ הזה \u0003לגוים, כ\u0004שיטת \u0003ר' יהודה\u0004 שלישראל אסורה אכילת חמץ כבר בשעה החמישית? \u0003אמר רב יוסף\u0004 אפשר לדחות: \u0003לא,\u0004 הכוונה היא שימכור \u0003לישראל,\u0004 והוא \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 שאף בשעה החמישית מותר החמץ באכילה. וכוונתו היתה שיזדרז למוכרו בשעה זו לפני שתיכנס השעה השישית ויהא אסור באכילה לישראל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי\u0004 \u0005[אם]\u0006 \u0003לישראל\u0004 מותר לאכול חמץ \u0005—\u0006 \u0003נישקליה לנפשיה\u0004 \u0005[שיקחנו לעצמו]\u0006 ויחזיר למפקיד את הדמים, ולמה לו לטרוח למכרו לאחר?","ודוחים: דבר זה אין עושים \u0003משום חשדא\u0004 \u0005[החשד],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 כעין זה: \u0003גבאי צדקה שאין להם עניים לחלק\u0004 להם צדקה — \u0003פורטין\u0004 את הכסף שנצטבר בידם \u0003לאחרים, ואין פורטין לעצמן.\u0004","וכן \u0003גבאי תמחוי\u0004 שאוספים ומביאים את האוכל בקערות גדולות למאכל עניים, והתברר \u0003שאין להם עניים לחלק\u0004 להם מזון — \u0003מוכרין\u0004 את המזון \u0003לאחרים, ואין מוכרין לעצמן, משום שנאמר \"והייתם נקים מה' ומישראל\"\u0004 (במדבר לב, כב), ומשמעו שלא די לאדם שיהיה נקי בעיני ה' אלא צריך להיות גם נקי בעיני ישראל, שלא יבואו לחושדו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לרב יוסף: בפירוש אמרת לן\u0004 \u0005[לנו]\u0006 בענין זה שאמר לו: \u0003צא ומוכרן לגוים, כר' יהודה.\u0004 שרב יוסף חלה ושכח תלמודו, והיו תלמידיו מזכירים לו שבעבר אף הוא סבר כשיטה זו.","\u0003אמר רב יוסף: כמאן אזלא הא שמעתא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת הלכה זו]\u0006 של \u0003רבי,\u0004 שהורה לשומר למכור את החמץ המופקד בידו כדי למנוע הפסד מן המפקיד — \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 בענין זה, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003המפקיד פירות אצל חבירו, אפילו הן אבודין\u0004 מפני התולעים או מפני הרקב — \u0003לא יגע בהן. רבן שמעון בן גמליאל אומר: מוכרן בבית דין מפני השבת אבידה,\u0004 שכשם שאדם חייב להשיב אבידת חבירו כך חייב לדאוג שלא יאבד ממון חבירו המופקד בידו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולאו איתמר עלה\u0004 \u0005[והאם לא נאמר עליה]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שאמרו חכמים \"אפילו הם אבודים לא יגע בהם\" \u0003אלא\u0004"],["\u0003בכדי חסרונן\u0004 כלומר, בכדי השיעור המקובל שחסרים בו פירות מאוחסנים על ידי רקב ותולעים, שהוא פחות או יותר קבוע ומסויים. \u0003אבל\u0004 אם רואה שהם נאבדים ב\u0003יותר מכדי חסרונן —\u0004 הכל מודים ש\u0003מוכרן בבית דין, וכל שכן הכא\u0004 \u0005[כאן]\u0006 לענין החמץ, \u0003דהא פסידי\u0004 \u0005[שהרי נפסדים]\u0006 \u0003לגמרי,\u0004 שהרי חמץ אחר הפסח אסור בהנאה, ובכך בודאי הכל מודים שחייב למוכרם.","במשנה שנינו: \u0003ועוד אמר ר' יהודה שתי חלות\u0004 תודה היו מונחות על גב האיצטבא לסימן. \u0003תני תנא קמיה\u0004 \u0005[שנה התנא לפני]\u0006 \u0003רב יהודה\u0004 הלכה זו שמונחות היו החלות \u0003על גב האיצטבא.\u0004 לאמור, על האיצטבאות סביב המקדש. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי להצניען הוא צריך?!\u0004 והרי בדרך זו אין רואים אותן! \u0003תני\u0004 \u0005[שנה]\u0006 \u0003על גג האיצטבא\u0004 מלמעלה, לעיני כל.","\u0003אמר רחבא אמר ר' יהודה: הר הבית סטיו כפול היה\u0004 (שורת אצטבאות כפולה היתה) סביבו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003הר הבית סטיו כפול היה ר' יהודה אומר: איסטוונית היתה נקראת\u0004 והיא \u0003סטיו לפנים מסטיו.\u0004","במשנה שנינו: ר' יהודה אומר ששתי חלות תודה שהיו מונחות על האצטבאות היו \u0003פסולות.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסולות?\u0004 מהיכן נפסלו? \u0003אמר ר' חנינא: מתוך שהיו מרובות — נפסלות בלינה\u0004 שהיו חלות תודה מרובות, וכיון שלא הספיקו הכהנים לאכול את כולן היו אחדות נשארות בלילה ונפסלות בלינה. וכדי לבאר מפני מה היו חלות מרובות, מביאים מקור \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מביאין\u0004 קרבן \u0003תודה בחג המצות, מפני חמץ שבה,\u0004 שרבע מחלות התודה חמץ הן.","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור הדבר\u0005]\u0006 שאין מביאים? הרי חמץ הוא זה! \u0003אמר רב אדא בר אהבה: הכא\u0004 \u0005[כאן]\u0006 בברייתא זו לא בפסח עצמו עוסקים אלא \u0003בארבעה עשר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003וקסבר\u0004 \u0005[וסבר]\u0006 אותו תנא: \u0003אין מביאין קדשים לבית הפסול.\u0004 שאף שביום ארבעה עשר עצמו מותר לאכול חמץ עד השעה הששית, אך כיון שזמן אכילת תודה ולחמיה הוא יום ולילה, לכך אין מביאין אותה בערב פסח כדי שלא למעט בזמן אכילתה, או לגרום לה פסול מוקדם מדי.","ומשום שבימים אלה אין מביאים תודות הרי \u0003כולי עלמא\u0004 \u0005[הכל]\u0006 \u0003בשלשה עשר מייתי\u0004 \u0005[מביאים\u0006 תודות\u0005]\u0006 שכל העולים לרגל ויש עליהם חובת קרבן תודה מביאים את תודותיהם בשלושה עשר בניסן, \u0003ומתוך שהן מרובות — נפסלות בלינה\u0004 שאין הכהנים מספיקים לאכול את כולן.","\u0003משום ר' ינאי אמרו: כשירות היו\u0004 ולא נפסלו פסול חמור זה של לינה \u0003ואלא אמאי קרי להו\u0004 \u0005[מדוע קורא להן]\u0006 \u0003פסולות\u0004 — שהיו אלה חלות \u0003שלא נשחט עליהן הזבח\u0004 אלא הקדישם בפני עצמם כלחמי תודה. ואין החלות ראויות לאכילה אלא לאחר שחיטת הקרבן השייך להן. ושואלים: \u0003ונשחוט\u0004 \u0005[ושישחטו אותו]!\u0006 ומשיבים: מדובר כאן \u0003שאבד הזבח.\u0004","ומקשים: \u0003וניתי\u0004 \u0005[ונביא]\u0006 \u0003זבח אחר\u0004 במקום זה שאבד \u0003ונשחוט!\u0004 ומשיבים: ש\u0003אמר\u0004 אותו אדם שהקדיש את התודה: \u0003\"זו תודה וזו לחמה\",\u0004 שהקדישם, את התודה ולחמה יחד בהקדש אחד, וכדברי \u0003רבה.\u0004 ש\u0003אמר רבה: אבד הלחם\u0004 של קרבן התודה — \u0003מביא לחם אחר,\u0004 להשלים את הקרבן אולם אם \u0003אבדה תודה\u0004 ונשאר הלחם — \u0003אין מביא תודה אחרת. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003לחם\u0004 בא ב\u0003גלל תודה, ואין תודה\u0004 באה ב\u0003גלל לחם\u0004 כי הקרבן הוא עיקר והלחם הוא רק טפל לו.","ושואלים: \u0003וניפרקינהו ונפקינהו\u0004 \u0005[ושנפדה אותן\u0006 מן ההקדש \u0005ונוציאן]\u0006 \u0003לחולין\u0004 ולא יצטרכו לשורפן! \u0003אלא: לעולם\u0004 יש לפרש \u0003שנשחט עליהן הזבח ונשפך הדם\u0004 של הקרבן לפני שהיזו אותו על המזבח, וחלה על החלות קדושה מסויימת בשל שחיטת הזבח, ועדיין לא הוכשרו לאכילה.","\u0003וכמאן\u0004 \u0005[וכ\u0006שיטת \u0005מי]\u0006 דבר זה שהשחיטה עצמה גורמת לקדושת הלחם ששוב איננו בר פדיון — \u0003כרבי.\u0004 ש\u0003אמר רבי: שני דברים המתירין\u0004 שכל אחד מהם יש בו צורך בעבודת הקרבן \u0003מעלין\u0004 (מקדישים, פועלים) \u0003זה בלא זה.\u0004 ולכן אף השחיטה בלא ההזאה מקדשת במקצת את הלחם. \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כבשי עצרת\u0004 שמביאים עמם קרבן לחם \u0003אין מקדשין את הלחם אלא\u0004 על ידי \u0003שחיטה\u0004 של הבהמה. \u0003כיצד?\u0004 אם \u0003שחטן לשמן\u0004 כראוי להם \u0003וזרק דמן לשמן — קידש הלחם,\u0004","ואם \u0003שחטן שלא לשמן וזרק דמן שלא לשמן — לא קידש הלחם\u0004 שלא הוקרב המתיר כדינו. אולם אם \u0003שחטן לשמן וזרק דמן שלא לשמן\u0004 יש בכח השחיטה בלבד לקדש במקצת את הלחם, ולכן ה\u0003לחם קדוש\u0004 ששוב אינו יכול להיפדות \u0003ואינו קדוש\u0004 להיות מותר באכילה. אלו \u0003דברי רבי.\u0004","\u0003ר' אלעזר בר' שמעון אומר: לעולם אינו קדוש הלחם, עד שישחוט לשמן ויזרוק דמן לשמן\u0004 שאין הדבר מועיל אלא על ידי שני המתירים יחד.","את ההלכה הסברנו כשיטת רבי. ומוסיפים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' אלעזר בר' שמעון, הכא\u0004 \u0005[כאן]\u0006 לענין פסול לחמי התודה בערב פסח \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 במקרה מיוחד \u0003כגון שנתקבל הדם\u0004 לאחר השחיטה \u0003בכוס ונשפך\u0004 לפני הזאה,","\u0003ור' אלעזר בר' שמעון סבר ליה\u0004 בענין זה כשיטת \u0003אבוה\u0004 \u0005[אביו]\u0006 ר' שמעון, ש\u0003אמר\u0004 כלל גדול: \u0003כל העומד לזרוק\u0004 ומוכן להזרק \u0003כזרוק דמי\u0004 \u0005[נחשב]\u0006 ולכן הלחם מתקדש עם קבלת הדם בכלי והכנתו לזריקה, אבל לאכלו אסור עד שיזרק הדם ממש ולכן נפסלו החלות.","\u0003תנא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 \u0003משום ר' אלעזר אמרו: כשירות היו\u0004 חלות אלה לגמרי. ודרך הנחתן: \u0003כל זמן שמונחות\u0004 שתיהן — \u0003כל העם אוכלין\u0004 חמץ. \u0003ניטלה אחת מהן — תולין, לא אוכלין ולא שורפין. ניטלו שתיהן — התחילו כולם שורפין.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003אבא שאול אומר:\u0004"]]};
